SELECT 'moj-all-verified-judgments-review-002-chunk-138' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"6ba608f5-0206-5453-beaa-7d5cbffdc361","document_type":"judgment","category":"judicial","subcategory":"general","title":"حرابة -استخدام ساحي ناري -اعتداء -تعاطي احلشيش املخدر -تعاطي احلبوب احملظورة «الكبتاجون» -إقرار املدعى عليه - وجود سوابق قضائية -قيادة السيارة حتت تأثير املسكر -إقامة حد احلرابة واقتراح عقوبة النفي بالسجن عشرين سنة -إقامة حد املسكر -تعزير لقاء تعاطي احلبوب احملظورة باجللد .","document_number":"349934","case_number":"33694641","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بحائل /املساعد ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/12","year":"1434","subject":"حرابة -استخدام ساحي ناري -اعتداء -تعاطي احلشيش املخدر -تعاطي احلبوب احملظورة «الكبتاجون» -إقرار املدعى عليه - وجود سوابق قضائية -قيادة السيارة حتت تأثير املسكر -إقامة حد احلرابة واقتراح عقوبة النفي بالسجن عشرين سنة -إقامة حد املسكر -تعزير لقاء تعاطي احلبوب احملظورة باجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 349934 :‬تاريخه‪1434/1/12:‬هـ‬\n                  ‫رقم الدعوى‪33694641 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 158139‬تاريخه‪1434/6/13 :‬هـ‬\n\n\n‫حرابــة ‪ -‬اســتخدام ســاحي نــاري ‪ -‬اعتــداء ‪ -‬تعاطــي احلشــيش املخــدر‬\n‫‪ -‬تعاطــي احلبــوب احملظــورة «الكبتاجــون» ‪ -‬إقــرار املدعــى عليــه ‪-‬‬\n‫وجــود ســوابق قضائيــة ‪ -‬قيــادة الســيارة حتــت تأثيــر املســكر ‪ -‬إقامــة‬\n‫حــد احلرابــة واقتــراح عقوبــة النفــي بالســجن عشــرين ســنة ‪ -‬إقامــة‬\n       ‫حــد املســكر ‪ -‬تعزيــر لقــاء تعاطــي احلبــوب احملظــورة باجللــد ‪.‬‬\n\n\n\n\n‫‪ -1‬قــول اهلل تعالــى‪« :‬إمنــا جــزاء الذيــن يحاربــون اهلل ورســوله ويســعون‬\n‫يف األرض فســاد ًا أن يقتلــوا أو يصلبــوا أو تقطــع أيديهــم وأرجلهــم مــن‬\n‫خــاف أو ينفــوا مــن األرض ذلــك لهــم خــزي يف الدنيــا ولهم يف اآلخرة‬\n                                                   ‫عــذاب عظيــم» املائــدة ‪. 33‬‬\n                  ‫‪ -2‬قرار هيئة كبار العلماء رقم ‪85‬يف‪1401/01/11‬هـ ‪.‬‬\n‫‪ -3‬التعميــم الــوارد مــن معالــي رئيــس املجلــس األعلــى للقضــاء برقــم‬\n‫‪/292‬ت يف‪1433/08/28‬ه ـ املتضمــن تعميــم األمــر امللكــي رقــم ‪26834‬‬\n‫تاريــخ ‪1433/05/29‬ه ـ القاضــي بــأن ال يقــل ســجن احملــارب عن عشــرين‬\n                           ‫عامـ ًا وأن يكــون ذلــك قاعــدة عامــة ‪ . . .‬إلــخ‪.‬‬\n\n\n\n\n                                                                                   ‫‪222‬‬\n\f      ‫جــرى توجيــه االتهــام للمدعى عليه بترويع اآلمنني وإخافة الســبيل وذلك‬\n      ‫بإطــاق النــار علــى مجموعــة مــن األشــخاص والتســبب بإصابــة بعضهــم‬\n      ‫وإتــاف ممتلــكات بعضهــم وتنــاول مــادة االمفيتامــن املنبــه واحملظــور‬\n      ‫واحلشــيش املخــدر احملظــور واملجــرم وقيــادة الســيارة حتــت تأثيــر املخــدر‬\n      ‫املجــرم مبوجــب نظــام املــرور وطلــب إثبــات مــا أســند إليــه واحلكــم عليــه‬\n      ‫بحــد احلرابــة الــوارد يف اآليــة الكرميــة حيــث تلقــت اجلهــات األمنيــة‬\n      ‫بالغــا عــن تعــرض شــرطي إلطــاق نــار وإصابتــه لــدى مقــر عملــه بإمــارة‬\n      ‫املركــز ‪ ،‬ويف نفــس اليــوم تلقــت اجلهــات األمنيــة بالغ ـ ًا عــن تعــرض‬\n      ‫مواطــن للمطــاردة وإطــاق النــار‪ ،‬ويف نفــس اليــوم تلقــت اجلهــات األمنيــة‬\n      ‫مــن أحــد املقيمــن بالغــا عــن تعرضــه إلطــاق نــار أدت إلصابتــه وقــد‬\n      ‫أفــاد املجنــي عليهــم بأنهــم ال يعرفــون املدعــى عليــه والدافــع علــى مــا‬\n      ‫قــام بــه ‪ ،‬بعــد البحــث والتحــري عــن صاحــب الســيارة لوحظــت ســيارة‬\n      ‫قريبــة مــن مواصفــات الســيارة املطلوبــة عنــد مفــرق فتــم التوقــف عندهــا‬\n      ‫واتضــح أنهــا بقيــادة املدعــى عليــه فتــم القبــض عليــه وبتفتيــش الســيارة‬\n      ‫وجــد ســاح شــوزن أمريكــي ووجــدت أظــرف فارغــة لطلقــات ســاح‬\n      ‫شــوزن‪ ،‬قــام املجنــي عليهــم بالتعــرف علــى املدعــى عليــه ‪ ،‬أثبــت حتليــل‬\n      ‫دم املدعى عليه احتوائه على مادة االمفيتامني واحلشــيش ‪ ،‬أقر املدعى‬\n      ‫عليــه بالتهمــة وأنــه فعــل ذلــك حتــت تأثيــر الكبتاجــون واحلشــيش حيــث‬\n      ‫أصبــح يهــم بــأن هنــاك أشــياء تطــارده وأن الســوابق التــي عليــه صحيحــة‬\n      ‫وأنــه ال يعــرف الدافــع الــذي حملــه علــى هــذا التصــرف‪ ،‬وبنــاء ًا علــى‬\n      ‫مــا تقــدم مــن الدعــوى وإلقــرار املدعــى عليــه ولوجــود ســوابق عليــه وألن‬\n\n‫‪223‬‬\n\f‫فعلــه يعــد محاربــة هلل ورســوله وســعيا يف األرض فســادا وبعــد االطــاع‬\n‫علــى التعميــم الــوارد مــن معالــي رئيــس املجلــس األعلــى املتضمــن تعميــم‬\n‫األمــر امللكــي القاضــي بــأن ال يقــل ســجن احملــارب عــن عشــرين عامـ ًا‬\n‫وأن يكــون ذلــك قاعــدة عامــة ‪ . . .‬إلــخ وبنــاء ًا علــى مــا ســبق كلــه فقــد‬\n‫قــررت الدائــرة احلكــم مبــا يلــي ‪ :‬أوالً‪ /‬إقامــة حــد احلرابــة علــى املدعــى‬\n‫عليــه وتقتــرح يف ذلــك نفيــه علــى ضــوء التعميــم املشــار إليــه أعــاه‪.‬‬\n‫ثاني ـاً‪ /‬إقامــة حــد املســكر علــى املدعــى عليــه وذلــك بجلــده ثمانــن‬\n‫جلــده دفعــة واحــدة‪ .‬ثالث ـاً‪ /‬ثبــوت إدانــة املدعــى عليــه بتعاطيــه لثــاث‬\n‫حبــات محظــورة وتعزيــره لقــاء تعاطيــه احلبــوب احملظــورة بجلــده ســبعني‬\n‫جلــده دفعــة واحــدة‪ .‬رابعاً‪/‬ثبــوت قيادتــه الســيارة حتــت تأثيــر املســكر‬\n‫وعقابــه يف ذلــك عائــد إلــى ولــي األمــر وصرفــت النظــر عــن بقيــة طلبــات‬\n‫املدعــي العــام وبــكل مــا تقــدم حكمــت‪ ،‬بعــرض احلكــم علــى املدعــى‬\n‫عليــه واملدعــي العــام قــررا عــدم قناعتهمــا باحلكــم ورغبــا رفــع احلكــم‬\n‫حملكمــة االســتئناف لتدقيقــه كاملتبــع مــن غيــر الئحة ‪ ،‬عــادت املعاملة‬\n‫مــن محكمــة االســتئناف مبلحوظــة حيــث طلبــت اإلشــارة ملــدة ســجنه‬\n‫ألن مــا ورد يف التعميــم أشــار للحــد األدنــى ولــم يشــر لألعلــى ‪ ،‬قــررت‬\n‫الدائــرة يف اقتراحهــا بأنهــا تــرى أنــه يســجن عشــرين ســنة ويعامــل بعــد‬\n‫خروجــه وفقــا للتعميــم ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ومــن‬\n                                                                  ‫احملكمــة العليــا‪.‬‬\n\n\n\n\n                                                                                        ‫‪224‬‬\n\f      ‫احلمــد هلل وحــده والصــاة والســام علــى رســوله نبينــا محمــد وبعــد ففــي‬\n      ‫هــذا اليــوم الســبت املوافــق ‪1434/1/3‬ه ـ افتتحــت اجللســة يف متــام‬\n      ‫الســاعة العاشــرة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة بحائــل‪ /‬املســاعد برقــم ‪ 33694641‬يف‬\n      ‫‪1433/12/20‬ه ـ واملقيــدة بهــذه احملكمــة برقــم ‪ 332182066‬يف‬\n      ‫‪1433/12/19‬ه ـ لدينــا نحــن كال مــن ‪................‬و‪...........‬القضــاة‬\n      ‫باحملكمــة العامــة بحائــل وفيهــا حضــر املدعــي العــام واملدعــى عليهــم‬\n      ‫‪...........‬سعودي اجلنسية مبوجب السجل املدني رقم ‪1037979778‬وقرر‬\n      ‫املدعــي العــام دعــواه قائــا بصفتــي مدعيـ ًا عامـ ًا يف دائــرة االدعــاء العــام‬\n      ‫بفــرع الهيئــة مبنطقــة حائــل أدعــي علــى ‪......................:‬البالــغ مــن العمــر‬\n      ‫(‪ )33‬عامـ ًا ‪ ،‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪، )...........‬‬\n      ‫متعلــم ‪ ،‬أعــزب‪ ،‬يقيــم يف مدينــة الريــاض ‪ ،‬أوقــف بتاريخ ‪1433/6/2‬هـ‬\n      ‫وأودع الســجن العــام بحائــل مبوجــب مذكــرة التوقيــف رقــم (‪...........2‬‬\n      ‫وتاريــخ ‪1433/6/7‬ه ـ اســتناد ًا للقــرار الــوزاري (‪ )1900‬وتاريــخ‬\n      ‫‪1428/7/9‬هـ‪.‬فإنــه يف الســاعة الســابعة وأربعــن دقيقــة مــن صبــاح يــوم‬\n      ‫االثنــن ‪1433/6/2‬ه ـ تلقــت اجلهــات األمنيــة مــن املواطــن ‪)55(........... /‬‬\n      ‫عام ـ ًا ســعودي اجلنســية بالغ ـ ًا ذكــر فيــه تعــرض زميلــه املواطــن ‪/‬‬\n      ‫‪ ...........‬إلطــاق نــار وإصابتــه وذلــك عنــد مقــر عملــه بإمــارة قريــة‬\n      ‫‪ ،...........‬ويف متــام الســاعة الثامنــة صباح ـ ًا مــن نفــس اليــوم والتاريــخ‬\n      ‫تلقــت اجلهــات األمنيــة مــن املواطــن ‪........... /‬بالغ ـ ًا ذكــر فيــه تعرضــه‬\n      ‫للمطــاردة وإطــاق النــار مــن قبــل قائــد ســيارة ‪ ،......‬ويف الســاعة الثامنــة‬\n\n‫‪225‬‬\n\f‫والثلــث مــن نفــس اليــوم والتاريــخ تلقــت اجلهــات األمنيــة مــن املقيــم‬\n‫‪ /...........‬باكســتاني اجلنســية بالغ ـ ًا ذكــر فيــه تعرضــه إلطــاق نــار‬\n‫ممــا تســبب بإصابتــه وذلــك علــى طريــق ‪...........‬مــن قائــد ســيارة ‪.....‬‬\n‫وبســماع أقــوال املجنــي عليــه ‪ )34(.........../‬عامـ ًا ســعودي اجلنســية أفــاد‬\n‫أنــه عنــد ذهابــه إلــى عملــه بإمــارة قريــة ‪...........‬وعنــد مــروره بقريــة‬\n‫‪...........‬شــاهد ســيارة ‪ ....‬تفحــط وتطــارد ســيارة ‪ ......‬فتركهــا وتوجــه‬\n‫إلــى عملــه وبعــد ذلــك الحــظ أن الســيارة ‪ .......‬متشــي خلفــه حتــى توقــف‬\n‫عنــد مركــز إمــارة‪ ...........‬وتوقــف قائــد الســيارة ‪ .....‬ونــزل ومعــه ســاح‬\n‫شــوزن وقــال لــه ( أنــت وش تبــي منــي ) فأســرع نحــو البــاب لكــي يدخــل‬\n‫للمركــز فأطلــق عليــه النــار وأصابــه برجلــه اليســرى أســفل الفخــذ‬\n‫وذكــر بأنــه ال يعرفــه ‪ .‬وبســماع إفــادة املجنــي عليــه ‪........... /‬أفــاد أنــه‬\n‫أثنــاء ذهابــه إلــى عملــه بقريــة ‪...........‬شــاهد ســيارة ‪ .......‬قــدمي خــارج مــن‬\n‫طريــق إمــارة ‪...........‬وســلك طريــق قريــة ‪...........‬وبعــد فتــرة شــاهد‪......‬‬\n‫متوقــف علــى ميــن الطريــق واســتمر هــو يف طريقــه وبعــد ذلــك شــاهد ‪.....‬‬\n‫ميشــي خلفــه ويطلــب منــه التوقــف وشــاهده ولــم يعرفــه وكان معه ســاح‬\n‫فهــرب منــه فطــارده صاحــب ‪ ....‬وأطلــق النــار عليــه وكســر زجــاج‬\n‫ســيارته اخللفــي وزجــاج بــاب الراكــب األميــن اخللفــي واســتمر مبطاردتــه‬\n‫فدخــل قريــة ‪...........‬وخــرج منها مســرع ًا وكان صاحب الســيارة يطارده‬\n‫وكانــا يســيران بســرعة جنونيــة وعندمــا أقبــل علــى قريــة ‪...........‬اختفــى‬\n‫عنــه واســتمر هــو بالســير حتــى وصــل إلــى مدينــة ‪...........‬وذكــر بأنــه‬\n‫أطلــق النــار عليــه مرتــن مــن ســاح الشــوزن الــذي كان معــه‪ .‬وبســماع‬\n‫إفــادة املجنــي عليــه املقيــم ‪ )28(........... /‬عام ـ ًا باكســتاني اجلنســية‬\n‫أفــاد أنــه أثنــاء ســيره باجتــاه مدينــة ‪...........‬شــاهد ســيارة ‪ .......‬واقفــة‬\n\n\n                                                                                            ‫‪226‬‬\n\f      ‫علــى يســار الطريــق فلمــا أصبــح بجانبــه أطلــق النــار عليــه وأصابــه بيــده‬\n      ‫اليســرى وال يعــرف الســبب واســتمر بالســير حتــى وصــل إلــى مدينــة‬\n      ‫‪............‬وبعــد البحــث والتحــري عــن صاحــب الســيارة لوحظــت ســيارة‬\n      ‫قريبــة مــن مواصفــات الســيارة املطلوبــة عنــد مفــرق قريــة ‪...........‬فتــم‬\n      ‫التوقــف عندهــا واتضــح أنهــا بقيــادة املتهــم املذكــور أعــاه فتــم القبــض‬\n      ‫عليــه وبتفتيــش ســيارة املتهــم وجــد ســاح مــن نــوع شــوزن أمريكــي‬\n      ‫الصنــع ( ‪ ) ......‬صنــع( ‪ ) ...‬بــدون رقــم داخــل الســيارة باملرتبــة اخللفيــة‬\n      ‫مخبــأة حتــت قطعــة قمــاش وعــدد (‪ )26‬ســت وعشــرون طلقــة حيــة‬\n      ‫ووجــدت أظــرف فارغــة لطلقــات ســاح شــوزن ‪ ،‬وباالنتقــال واملعاينــة‬\n      ‫ملوقــع اجلرميــة األول كان عنــد مركــز إمــارة قريــة ‪...........‬شــوهدت آثــار‬\n      ‫إطــاق نــاري علــى مدخــل املركــز الــذي يفتــح ناحيــة الشــرق كمــا‬\n      ‫شــوهدت آثــار دمــاء داخــل حــوش املركــز وقريــب مــن البــاب ووجــدت‬\n      ‫آثــار دمــاء أمــام وداخــل غرفــة الضيافــة باملركــز ولوحــظ أثــر إلطــارات‬\n      ‫ســيارة نتيجــة اســتخدام املكابــح متوقفــة أمــام البــاب الرئيــس للمركــز‬\n      ‫ولــم يشــاهد أي أظــرف فارغــة باملوقــع وقــد أثبــت التقريــر الفنــي رقــم‬\n      ‫‪ ...........‬الصــادر مــن إدارة األدلــة اجلنائيــة برقــم (‪ )...........‬وتاريــخ‬\n      ‫‪1433/6/14‬ه ـ أن األظــرف التــي مت رفعهــا مــن مســرح اجلرميــة وســيارة‬\n      ‫املتهــم مطلقــة مــن الســاح الشــوزن الــذي عثــر عليــه مــع املتهــم وأقــر‬\n      ‫بحيازتــه لــه كمــا مت معاينــة ســيارة مــن نــوع ‪ .....‬حتمــل اللوحــة رقــم (‬\n      ‫‪ .... )...........‬بقيــادة املجنــي عليــه ‪ ........... /‬اتضــح أنهــا تعرضــت إلطــاق‬\n      ‫نــار مــن اخللــف حيــث كســر الزجــاج اخللفــي و زجــاج الراكــب اخللفــي‬\n      ‫األميــن كمــا شــوهدت آثــار للمقذوفــات يف ســقف الســيارة كمــا مت‬\n      ‫معاينــة ســيارة مــن نــوع ‪ .....‬حتمــل اللوحــة رقــم ( ‪ )...........‬بقيــادة املجنــي‬\n\n\n‫‪227‬‬\n\f‫عليــه املقيــم ‪...........‬اتضــح تعرضهــا إلطــاق نــار مــن جهــة بــاب الســائق‬\n‫ونتــج عنــه حتطــم زجــاج بــاب الســائق وارتطام املقذوفات ببــاب الراكب‬\n‫مــن ا لداخــل وشــوهدت آثــار دمــاء علــى عجلــة القيــادة للســيارة وبــاب‬\n‫الســائق مــن الداخــل وقــد أثبــت قصــاص األثــر بعــد معاينتــه للموقــع‬\n‫الــذي يقــع بــن قريــة ‪...........‬وقريــة ‪...........‬أن اآلثــار تبــن أن هناك ســيارة‬\n‫نزلــت ميــن الطريــق وتوقفــت ثــم عــادت للطريــق مــرة أخــرى وهــذه اآلثــار‬\n‫مطابقــة ألثــار الســيارة مــن نــوع ‪ .....‬حتمــل اللوحــة رقــم ‪ ...........‬اللــون‬\n‫التــي يقودهــا املتهــم ومبعاينــة موقــع احلادثــة عنــد إمــارة قريــة ‪...........‬لــم‬\n‫يعثــر علــى مــا يفيــد التحقيــق ألن املوقــع مســفلت وقــد أثبــت خطــاب‬\n‫مديــر شــعبة األســلحة واملتفجــرات عــدم وجــود أي ســاح مرخــص باســم‬\n‫املتهــم وبعــرض الســيارة مــن نــوع ‪ .......‬حتمــل لوحــة رقــم‪ ...........‬علــى‬\n‫املواطــن ‪ ........... /‬اســتطاع التعــرف عليهــا وأنهــا نفــس الســيارة التــي‬\n‫كانــت تطــارده وقــام قائدهــا بإطــاق النــار عليــه كمــا جــرى عــرض‬\n‫الســيارة املشــار إليهــا علــى املواطــن ‪........... /‬واســتطاع التعــرف عليهــا‬\n‫وأنهــا نفــس الســيارة التــي شــاهدها عنــد قدومــه إلــى إمــارة قريــة ‪...........‬‬\n‫وبعــرض املتهــم مــع مجموعــة أشــخاص مشــابهني لــه علــى املواطــن ‪/‬‬\n‫‪...........‬واملواطــن ‪........... /‬اســتطاعا التعــرف عليــه أنــه هــو مــن كان‬\n‫يقــود الســيارة الكابــرس املشــار إليهــا امللــك بحائــل برقــم ‪)...........‬‬\n‫وتاريــخ ‪1433/6/29‬ه ـ والتقريــر الصــادر مــن مستشــفى امللــك بحائــل‬\n‫برقــم‪ )...........‬وتاريــخ ‪ /6/29‬وقــد تضمــن التقريــر الطبــي النهائــي‬\n‫للمجنــي عليــه ‪...........‬رقــم (‪ )...........‬الصــادر مــن مستشــفى امللــك‬\n‫……… بحائــل برقــم (‪ )......................‬وتاريــخ ‪1433/6/21‬ه ـ ادعــاء‬\n‫املجنــي عليــه إصابتــه بطلــق نــاري هوائــي وكان يعانــي مــن كســر‬\n\n\n                                                                                            ‫‪228‬‬\n\f      ‫متفتــت مفتــوح مــن الدرجــة الثالثــة وقــد مت إجــراء عمليــة جراحيــة‬\n      ‫لتنظيــف اجلــرح مــع تثبيــت الكســر مبســمار نخاعــي وخــرج بتاريــخ‬\n      ‫‪1433/6/8‬ه ـ مــع إعطــاءه موعــد للمتابعــة بالعيــادات اخلارجيــة ومــدة‬\n      ‫الشــفاء ســتة أســابيع مــا لــم حتــدث مضاعفــات ‪.‬كمــا أثبتــت التقاريــر‬\n      ‫الطبيــة للمجنــي عليــه ‪........... /‬رقــم (‪ )...........‬الصــادر مــن مستشــفى‬\n      ‫امللــك ……… بحائــل برقــم (‪...........‬وتاريــخ ‪1433/6/29‬ه ـ ورقــم‬\n      ‫(‪ )...........‬الصــادر مستشــفى ‪1433‬ه ـ املتضمنــة إصابــة بطلــق نــاري‬\n      ‫تســبب بإصابــة الشــريان واألوعيــة واألعصــاب للركبــة اليســرى ومــدة‬\n      ‫الشــفاء من ثالثة أشــهر إلى ســتة أشــهر كما أثبت التقرير الكيميائي‬\n      ‫الشــرعي رقم (‪ )...........‬الصادر من مركز مراقبة الســموم والكيمياء‬\n      ‫الطبيــة مبنطقــة القصيــم برقم‪...........‬وتاريــخ ‪1433/6/29‬ه ـ إيجابيــة‬\n      ‫العينــة املأخــوذة مــن املتهــم ملــادة األمفيتامــن املنبهــة واحملظــورة كمــا‬\n      ‫ثبــت إيجابيــة العينــة للتتراهيدروكانــا بينــول وهــو مــن نــواجت أيــض‬\n      ‫احلشــيش املخــدر وورد التقريــر رقــم ‪...........‬الصــادر مــن األدلــة اجلنائيــة‬\n      ‫‪ ،،،‬املتعلــق بفحــص املســحات التــي مت أخذهــا مــن أيــدي املتهــم‬\n      ‫املذكــور ســلبية العينــة ملخلفــات اإلطــاق النــاري وهــذا ال يعنــي عــدم‬\n      ‫اســتخدام الســاح لعــدة عوامــل مــن ضمنهــا ( نوعيــة الســاح وآليتــه‬\n      ‫العامــل الزمنــي وإزالــة اآلثــار عــن طريــق غســيل األيــدي أو مســحها‬\n      ‫بقصــد أو بــدون قصــد) وبســماع شــهادة الشــاهد ‪)26(...................... /‬‬\n      ‫عام ـ ًا ســعودي اجلنســية أفــاد أن زميلــه املجنــي عليــه ‪...................... /‬‬\n      ‫اتصــل بــه وذكــر لــه تعرضــه إلطــاق نــار مــن قبــل قائــد ســيارة ‪......‬‬\n      ‫فتوجــه لــه علــى طريــق ‪...........‬ويف طريقــه شــاهد الســيارة ‪ .....‬واقفــة‬\n      ‫علــى جانــب الطريــق عنــد قريــة ‪...........‬ونــازل منهــا شــخص معــه ســاح‬\n\n\n‫‪229‬‬\n\f‫ولــم يتوقــف عنــده واســتمر بالســير إلــى مدينــة ‪...........‬ملقابلــة املجنــي‬\n‫عليــه ‪.........../‬كمــا ذكــر بأنــه لــم يشــاهد املتهــم وهــو يطلــق النــار أو‬\n‫يقــوم باملطــاردة وبســماع شــهادة الشــاهد ‪...................... /‬أفــاد أنــه عنــد‬\n‫حضــوره إلــى مقــر عملــه بإمــارة قريــة ‪...........‬وقبــل دخولــه للمركــز‬\n‫قابلتــه ســيارة مــن نــوع ‪ ......‬يقودهــا شــخص مكشــوف الــرأس وبعــد‬\n‫دخولــه للمركــز شــاهد زميلــه املجنــي عليــه ‪...................... /‬مصابـ ًا يف‬\n‫غرفــة الضيافــة وقــام بإســعافه مــع مديــر املركــز وأخبــره بــأن قائــد‬\n‫ســيارة ‪ ......‬هــو مــن أطلــق عليــه النــار وباســتجواب املتهــم أقــر بأنــه خــرج‬\n‫مــن مدينــة الريــاض لوجــود ثــاث ســيارات تطــارده وكان يريــد الذهــاب‬\n‫إلــى قريــة ‪...........‬ألخــذ ســاح شــوزن موجــود يف املنــزل وذلــك أنــه تنــاول‬\n‫حبتــن مــن احلبــوب احملظــورة بعــد خروجــه مــن الريــاض وأصبــح يــرى‬\n‫أشــياء تطــارده ووصــل إلــى القريــة قرابــة الســاعة السادســة صباح ـ ًا‬\n‫وأخــذ الســاح الشــوزن وهــو ســاح يعــود لــه وغيــر مرخــص وكان‬\n‫هنــاك ظــل يطــارده وعندمــا تابعــه كانــت ســيارة ‪ ......‬فخرجــت عــن‬\n‫الطريــق وكان اجلــو غبــار وعندمــا عــادت إلــى الطريــق حتولــت الســيارة‬\n‫إلــى جيــب فلحــق بــه حتــى وصــل إلــى إمــارة ‪...........‬ونــزل منــه شــخص‬\n‫وحــاول الهــرب ولكنــه أطلــق عليــه النــار وســمعه يصــرخ فركــب‬\n‫ســيارته وتوجــه إلــى قريــة ‪...........‬وشــاهد ســيارة ‪ .....‬وأطلــق عليــه النــار‬\n‫وبعدمــا جتــاوز قريــة ‪...........‬توقــف فمــرت مــن أمامــه ســيارة ‪ ....‬فأطلــق‬\n‫النــار عليهــا وأنــه ال يعلــم ســبب قيامــه بهــذه األفعــال كمــا ذكــر بأنــه ال‬\n‫يعــرف األشــخاص الذيــن أطلــق عليهــم النــار وليــس بينــه وبينهــم أي‬\n‫عــداوة وقــد اســفر التحقيــق معــه عــن اتهامــه بترويــع اآلمنــن وإخافــة‬\n‫الســبيل وذلــك بإطــاق النــار علــى مجموعــة مــن األشــخاص والتســبب‬\n\n\n                                                                                          ‫‪230‬‬\n\f      ‫بإصابــة بعضهــم وإتــاف ممتلــكات بعضهــم واملجــرم شــرع ًا واتهامــه‬\n      ‫بتنــاول مــادة االمفيتامــن املنبــه واحملظــور واحلشــيش املخــدر واحملظــور‬\n      ‫واملجــرم مبوجــب الفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة وقيــادة الســيارة حتــت تأثيــر املخــدر املجرم‬\n      ‫مبوجــب نظــام املــرور ‪ ( .‬مت فــرز أوراق مســتقلة ملعاجلــة موضــوع حيــازة‬\n      ‫الســاح والذخيــرة بــدون ترخيــص مــن قبــل احملكمــة املختصــة) وذلــك‬\n      ‫لألدلــة والقرائــن التاليــة‪ -1 :‬اعترافــه املصــدر شــرع ًا املــدون علــى‬\n      ‫الصفحــة رقــم ( ‪ )5.4‬لفــة رقــم(‪ -2 .)1‬مــا جــاء بشــهادة الشــهود املدونــة‬\n      ‫علــى الصفحــة رقــم (‪ )14.13.10‬لفــة رقــم (‪ -3 )5‬مــا جــاء بالتقاريــر‬\n      ‫الطبيــة املشــار إليهــا املرفقــة لفــة رقــم ( ‪ -4 )60.53.47.45.24‬مــا جــاء‬\n      ‫مبحضــر املعاينــة املــدون علــى الصفحــة رقــم (‪ )3.2‬لفــة رقــم(‪ -5 )4‬مــا‬\n      ‫جــاء مبحضــر القبــض والتفتيــش املــدون علــى الصفحــة رقــم (‪ )4‬لفــة‬\n      ‫رقــم (‪ -6 )4‬مــا جــاء باحملضــر املعــد مــن قبــل قصــاص األثــر املــدون علــى‬\n      ‫الصفحــة رقــم (‪ )6‬لفــة رقــم (‪ -7 )5‬مــا جــاء مبحاضــر العــرض للمتهــم‬\n      ‫وســيارته املدونــة علــى الصفحــة رقــم (‪ )16.15‬لفــة رقــم (‪ -8 )5‬مــا جــاء‬\n      ‫بالتقريــر اجلنائــي املصــدر رقــم (‪ )8‬لعــام ‪1433‬ه ـ املرفــق لفــة رقــم (‪)71‬‬\n      ‫‪ -9‬مــا جــاء بالتقريــر الفنــي لألســلحة رقــم (‪ )51‬لعــام ‪1433‬ه ـ املشــار‬\n      ‫إليــه واملرفــق لفــة رقــم (‪ -10 )67‬مــا جــاء بالتقرير الكيميائي الشــرعي‬\n      ‫املشــار إليــه املرفــق لفــه رقــم (‪ )56‬وبالبحــث يف ســجله اجلنائــي تبــن أن‬\n      ‫لــه ســتة ســوابق هــي ‪ :‬اعتــداء ‪ -‬فعــل فاحشــة اللــواط ‪ -‬حيــازة واســتعمال‬\n      ‫مخــدرات ‪ -‬ترويــج املســكرات ‪ -‬حيــازة املخــدرات وحيــث إمنــا أقــدم‬\n      ‫عليــه فعــل محــرم ومعاقــب عليــه شــرع ًا ويعــد ضربـ ًا من ضروب اإلفســاد‬\n      ‫يف األرض وملــا فيــه مــن إخافــة الســبيل وترويــع اآلمنــن وســالكي‬\n\n\n‫‪231‬‬\n\f‫الطريــق ‪ ،،،‬أطلــب إثبــات إدانتــه مبــا أســند إليــه اســتناد ًا للمادتــن‬\n‫(‪ )129.126‬مــن نظــام اإلجــراءات اجلزائيــة واحلكــم عليــه بحــد احلرابــة‬\n‫الــوارد يف اآليــة الكرميــة رقــم (‪ )33‬مــن ســورة املائــدة يف ضــوء قــرار‬\n‫هيئــة كبــار العلمــاء رقــم (‪ )85‬وتاريــخ ‪1401/1/11‬ه ـ ومصــادرة‬\n‫الســيارة املســتخدمة يف اجلرميــة وإثبــات إدانتــه بتعاطــي مادتــي احلشــيش‬\n‫املخــدر واالمفيتامــن املنبــه واحلكــم عليــه مبــا يلــي‪ -1 :‬الســجن ‪-2‬املنــع‬\n‫مــن الســفر وفق ـ ًا للمادتــن (‪ )56.41‬مــن نظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة وإثبــات إدانتــه بقيــادة الســيارة حتــت تأثيــر املخــدر‬\n‫وإفهامــه بــأن عقابــه علــى ذلــك عائــد للجهــة املختصــة ( علمـ ًا بــأن احلــق‬\n‫اخلــاص مــا زال قائم ـ ًا ) هكــذا ادعــى وبــرد ذلــك علــى املدعــى عليــه‬\n‫املتهــم فأجــاب وهــو باألهليــة املعتبــرة شــرعا قائــا ‪ :‬مــا ذكــره املدعــي‬\n‫العــام مــن أنــي أطلقــت النــار علــى التفصيــل الــذي ذكــره وعــدده ثــاث‬\n‫مــرات علــى ثالثــة أشــخاص فهــو صحيــح ولكنــي أطلقــت حتــت تأثيــر‬\n‫مــا تعاطيتــه مــن حبــوب الكبتاجــون وعددهــا حبتــان وســيجارة واحــدة‬\n‫مــن احلشــيش املخــدر والســوابق املذكــورة يف الدعــوى العامــة كلهــا‬\n‫صحيحــة وأنــا أعمــل بشــركة ‪ ...........‬مبدينــة الريــاض هكــذا أجــاب‬\n‫فجــرى الرجــوع إلــى أوراق املعاملــة وجــد بــن طياتهــا بينــات املدعــي‬\n                            ‫العام التي أشار اليها يف الئحته وهي كما يلي‪:‬‬\n‫‪ .1‬اعترافــه املصــدر شــرع ًا املــدون علــى الصفحــة رقــم (‪ )5.4‬لفــة رقــم‬\n                                                                                ‫(‪)1‬‬\n‫‪ .2‬مــا جــاء بشــهادة الشــهود املدونــة علــى الصفحــة رقــم (‪14.13.10‬‬\n                                                                   ‫(لفــة رقــم (‪)5‬‬\n‫‪ .3‬مــا جــاء بالتقاريــر الطبيــة املشــار إليهــا املرفقــة لفــة رقــم‬\n\n\n                                                                                      ‫‪232‬‬\n\f                                                            ‫( ‪)60.53.47.45.24‬‬\n      ‫‪ .4‬مــا جــاء مبحضــر املعاينــة املــدون علــى الصفحــة رقــم (‪ )3.2‬لفــة رقــم‬\n                                                                                     ‫( ‪)4‬‬\n      ‫‪ .5‬مــا جــاء مبحضــر القبــض والتفتيــش املــدون علــى الصفحــة رقــم (‪)4‬‬\n                                                                           ‫لفــة رقــم (‪)4‬‬\n      ‫‪ .6‬مــا جــاء باحملضــر املعــد مــن قبــل قصــاص األثــر املــدون علــى الصفحــة‬\n                                                                  ‫رقــم (‪ )6‬لفــة رقــم(‪)5‬‬\n      ‫‪ .7‬مــا جــاء مبحاضــر العــرض للمتهــم وســيارته املدونــة علــى الصفحــة‬\n                                                          ‫رقــم (‪ )16.15‬لفــة رقــم (‪)5‬‬\n      ‫‪ .8‬مــا جــاء بالتقريــر اجلنائــي املصــدر رقــم (‪ )8‬لعــام ‪1433‬ه ـ املرفــق لفــة‬\n                                                                               ‫رقــم (‪)71‬‬\n      ‫‪ .9‬مــا جــاء بالتقريــر الفنــي لألســلحة رقــم (‪ )51‬لعــام ‪1433‬ه ـ املشــار‬\n                                                          ‫إليــه واملرفــق لفــة رقــم (‪)67‬‬\n      ‫‪ .10‬مــا جــاء بالتقريــر الكيميائــي الشــرعي املشــار إليــه املرفــق لفــه رقــم‬\n                                                                                    ‫(‪)56‬‬\n      ‫باالطــاع عليهــا وجدناهــا تتضمــن مــا أشــار اليهــا املدعــي العــام بالئحته‬\n      ‫ومنهــا اعتــراف املدعــى عليــه املصــدق شــرعا املــدون لفــه (‪ )1‬ص ‪5-4‬‬\n      ‫املتضمــن باســتجواب املتهــم أقــر بأنــه خــرج مــن مدينــة الريــاض لوجــود‬\n      ‫ثــاث ســيارات تطــارده وكان يريــد الذهــاب إلــى قريــة ‪...........‬ألخــذ‬\n      ‫ســاح شــوزن موجــود يف املنــزل وذلــك أنــه تنــاول حبتــن مــن احلبــوب‬\n      ‫احملظــورة بعــد خروجــه مــن الريــاض وأصبــح يــرى أشــياء تطــارده ووصــل‬\n      ‫إلى القرية قرابة الســاعة السادســة صباح ًا وأخذ الســاح الشــوزن وهو‬\n      ‫ســاح يعــود لــه وغيــر مرخــص وكان هنــاك ظــل يطــارده وعندمــا تابعــه‬\n\n\n‫‪233‬‬\n\f‫كانــت ســيارة ‪ ......‬فخرجــت عــن الطريــق وكان اجلــو غبــار وعندمــا‬\n‫عــادت إلــى الطريــق حتولــت الســيارة إلــى جيــب فلحــق بــه حتــى وصــل‬\n‫إلــى إمــارة ‪...........‬ونــزل منــه شــخص وحــاول الهــرب ولكنــه أطلــق عليــه‬\n‫النــار وســمعه يصــرخ فركــب ســيارته وتوجــه إلــى قريــة ‪...........‬وشــاهد‬\n‫ســيارة ‪ .....‬وأطلــق عليهــا النــار وبعدمــا جتــاوز قريــة ‪...........‬توقــف فمــرت‬\n‫مــن أمامــه ســيارة ‪ .....‬فأطلــق النــار عليهــا وأنــه ال يعلــم ســبب قيامــه بهــذه‬\n‫األفعــال كمــا ذكــر بأنــه ال يعــرف األشــخاص الذيــن أطلــق عليهــم‬\n‫النــار وليــس بينــه وبينهــم أي عــداوة أ ه ـ والنتهــاء وقــت اجللســة رفعــت‬\n‫اجللســة ‪،،،‬ويف جلســة أخــرى وفيهــا حضــر املدعــي العــام واملدعــى عليــه‬\n‫ويف هــذه اجللســة جــرى الرجــوع إلــى أوراق املعاملــة وجــد بــن طياتهــا‬\n‫اعتــراف مصــدق للمدعــى عليــه مــدون علــى لفــه (‪ )1‬صفحــة صـ ـ ‪5/4‬ـ ـ ـ‬\n‫وهــذا نصــه ‪ :‬اقــر واعتــرف أنــا املواطــن ‪...........‬هويــة وطنيــة رقــم ‪...........‬‬\n‫وتاريــخ ‪1415/8/22‬ه ـ ســجل حائــل بأنــي كنــت ليلــة االثنــن موجــودا‬\n‫بالريــاض ليــا وقمــت بــأكل حبــوب مخــدرة وبعــد ذلــك قــام أصحــاب‬\n‫ثالثــة ســيارات مبضايقتــي فقصــدت التوجــه إلــى قريــة ‪...........‬لكــي‬\n‫آخــذ ســاحي املوجــود مبنزلنــا هنــاك وكانــت الســيارات تضايقنــي‬\n‫حتــى وصلــت إلــى ‪...........‬وتوجهــت مــع طريــق ‪...........‬قاصــدا‪...........‬‬\n‫وكان الفجــر قــد خــرج وانبــاح الشــوف وكان ظــل خلفــي يتابعنــي‬\n‫وتوجهــت إلــى منزلنــا بقريــة ‪...........‬وأخــذت ســاحا لــي نــوع شــوزن ومعــه‬\n‫ذخيــره وركبــت ســيارتي ‪ .....‬ثــم شــاهدت الظــل مــرة أخــرى وقمــت‬\n‫بطــرده وملــا اقتربــت منــه خرجــت ســيارة ‪ ....‬ثــم خــرج عــن اخلــط وعــادت‬\n‫إليــه وملــا عــادت للطريــق حتولــت إلــى ‪ .....‬وقمــت مبطاردتــه حتــى وصــل‬\n‫إلــى مركــز إمــارة ‪...........‬ونــزل منــه شــخص وقلــت لــه مــاذا تريــد منــي‬\n\n\n                                                                                            ‫‪234‬‬\n\f      ‫تالحقنــي ومعــي الســاح نــوع شــوزن فهــرب يريــد الدخــول إلــى مبنــى‬\n      ‫اإلمــارة وقمــت بإطــاق النــار عليــه وســمعت صراخــه ثــم حتركــت‬\n      ‫مــن أمــام املركــز واجتهــت مــع طريــق ‪...........‬وشــاهدت فــورد ميشــي‬\n      ‫أمامــي فقمــت مبطاردتــه وإطــاق النــار عليــه وقمــت باللحــاق بــه حتــى‬\n      ‫منتصــف الطريــق بــن ‪...........‬و‪ ...........‬ثــم توقفــت ومــر مــن عنــدي ‪....‬‬\n      ‫متوجهــا الــى ‪...........‬وقمــت بإطــاق النــار م الســاح الــذي معــي مــن دون‬\n      ‫أي ســبب علمــا باننــي ال أعــرف مــن هــم الذيــن أطلقــت النــار عليهــم‬\n      ‫ولــم يكــن بينــي وبينهــم عــداوة أو مشــكله هــذا اقــرار منــي واعتــراف‬\n      ‫مبــا حصــل ومــا بــدر منــي حــول ذلــك وعليــه اوقــع أ ه ـ واملصــدق عليــه‬\n      ‫ـاء علــى‬ ‫شــرعا مــن قبــل فضيلــة قاضــي احملكمــة العامــة ب‪ ...........‬فبنـ ً‬\n      ‫مــا تقــدم مــن الدعــوى واإلجابــة وبتأمــل القضيــة ودراســتها وحيــث‬\n      ‫صــادق املدعــى عليــه علــى دعــوى املدعــي العــام وأنــه يتعاطــى احلبــوب‬\n      ‫احملظــورة واحلشــيش وأنــه قــاد الســيارة حتــت تأثيــر املســكر وقــرر أنــه‬\n      ‫أطلــق النــار وأصــاب مــن أصــاب حتــت تأثيــر احلبــوب واحلشــيش ومبــا أن‬\n      ‫املدعــى عليــه صاحــب ســوابق ممــا يــدل علــى تأصــل الشــر والفســاد يف‬\n      ‫نفســه وفعلــه أخيــر ًا محاربــه هلل ورســوله وســعي يف األرض فســاد ًا وملــا‬\n      ‫جــاء يف إقــرار املدعــى عليــه املصــدق شــرعا ولقولــه تعالــى [ إمنــا جــزاء‬\n      ‫الذيــن يحاربــون اهلل ورســوله ويســعون يف األرض فســاد ًا أن يقتلــوا أو‬\n      ‫يصلبــوا أو تقطــع أيديهــم وأرجلهــم مــن خــاف أو ينفــوا مــن األرض ذلــك‬\n      ‫لهــم خــزي يف الدنيــا ولهــم يف اآلخــرة عــذاب عظيــم ] املائــدة ‪33‬وملــا جــاء‬\n      ‫يف قــرار هيئــة كبــار العلمــاء رقــم ‪85‬يف‪1401/01/11‬ه ـ وبعــد اإلطــاع‬\n      ‫علــى التعميــم الــوارد لنــا مــن معالــي رئيــس املجلــس األعلــى للقضــاء‬\n      ‫برقــم ‪/292‬ت يف‪1433/08/28‬ه ـ املتضمــن تعميــم األمــر امللكــي رقــم‬\n\n\n‫‪235‬‬\n\f‫‪26834‬تاريخ‪1433/05/29‬ه ـ القاضــي بــأن ال يقــل ســجن احملــارب‬\n‫ـاء علــى‬‫عــن عشــرين عام ـ ًا وأن يكــون ذلــك قاعــدة عامــة ‪ . . .‬إلــخ فبنـ ً‬\n‫مــا ســبق كلــه فقــد ظهــر لنــا مــا يلــي ‪ :‬أوالً‪/‬أمرنــا بإقامــة حــد احلرابــة‬\n‫علــى املدعــى عليــه ونقتــرح يف ذلــك نفيــه علــى ضــوء التعميــم املشــار إليــه‬\n‫أعــاه ‪ -‬ثانياً‪/‬أمرنــا بإقامــة حــد املســكر علــى املدعــى عليــه وذلــك‬\n‫بجلــده ثمانــن جلــده دفعــة واحــدة ‪ -‬ثالثاً‪/‬ثبــت لدينــا إدانــة املدعــى‬\n‫عليــه بتعاطيــه لثــاث حبــات محظــورة وأمرنــا بتعزيــر املدعــى عليــه لقــاء‬\n‫تعاطيــه احلبــوب احملظــورة وذلــك بجلــده ســبعني جلــده دفعــة واحــدة ‪-‬‬\n‫رابعاً‪/‬ثبــت لدينــا أن املدعــى عليــه قــاد الســيارة وحتــت تأثيــر املســكر‬\n‫وعقابــه يف ذلــك عائــد إلــى ولــي األمــر وصرفنــا النظــر عــن بقيــة طلبــات‬\n‫املدعــي العــام ‪ -‬وبــكل مــا تقــدم حكمنــا بعــرض احلكــم علــى املدعــى‬\n‫عليــه واملدعــي العــام قــررا عــدم قناعتهمــا باحلكــم ورغبــا رفــع احلكــم‬\n‫حملكمــة االســتئناف لتدقيقــه كاملتبــع مــن غيــر الئحــة وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                    ‫‪1434/1/10‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم الســبت املوافق‪1434/02/02‬ه ـ‬\n‫افتتحــت اجللســة الســاعة احلاديــة عشــر والنصــف وقــد وردتنــا املعاملــة‬\n‫مــن محكمــة االســتئناف مبنطقــة حائــل مبوجــب كتــاب رئيســها‬\n‫رقــم ‪ 34128869‬بتاريــخ ‪1434/1/26‬ه ــاملرفق معــه قــرار الدائــرة‬\n‫اخلماســية برقــم ‪ 3415383‬بتاريــخ ‪1434/1/18‬ه ـ ونــص احلاجــه منــه‬\n‫(وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة لوحــظ أن أصحــاب‬\n‫الفضيلــة وفقهــم اهلل قــد حكمــوا بإقامــة حــد احلرابــة علــى املدعــى عليه‬\n‫واقترحــوا نفيــه مــن األرض علــى ضــوء التعميــم املشــار إليــه إال أنهــم لــم‬\n\n\n                                                                                        ‫‪236‬‬\n\f      ‫يصرحــوا مبــدة ســجنه حيــث ان التعميــم املشــار إليــه حــدد االقــل ولــم‬\n      ‫يحــدد األعلــى والبــد مــن ذلــك كمــا وجــد أن صــورة الضبــط لــم تصــدق‬\n      ‫طبــق أصلهــا حســب التعليمــات ملالحظــة ذلــك وإجــراء مــا يلــزم واهلل‬\n      ‫املوفــق) أ ه ـ قضــاة اســتئناف ‪...........‬و‪...........‬و‪ ...........‬و‪...........‬ورئيــس‬\n      ‫الدائــرة ‪...........‬أختامهــم وتواقيعهــم عليــه جنيــب أصحــاب الفضيلــة‬\n      ‫وفقنــا اهلل وإياهــم إلــى الصــواب أننــا نقتــرح ســجنه مــدة قدرهــا عشــرون‬\n      ‫عامــا ويعامــل يف إخراجــه بعــد هــذه املــدة وفــق مــا جــاء بالتعميــم املشــار‬\n      ‫إليــه بعاليــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                              ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/2/2‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم األربعــاء املوافــق‪1434/02/13‬‬\n      ‫ه ـ افتتحــت اجللســة الســاعة التاســعة والربــع وقــد عــادت املعاملــة مــن‬\n      ‫محكمــة االســتئناف مبنطقــة حائــل مبوجــب كتــاب رئيســها رقــم‬\n      ‫‪ 34301881‬يف ‪1434/02/06‬ه ـ املرفــق معــه قــرار تصديــق الدائــرة‬\n      ‫اخلماســية برقــم ‪3431178‬يف ‪1434/02/05‬ه ـ املتضمــن املصادقــة على‬\n      ‫ماحكــم بــه أصحــاب الفضيلــة‪ .‬قضــاة االســتئناف ‪ ...........‬و‪...........‬‬\n      ‫و‪ ...........‬و‪ ..............‬ورئيــس الدائــرة ‪...........‬أختامهــم وتواقيعهــم أه ـ‬\n      ‫‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                         ‫وســلم ‪ .‬حــرر يف ‪1434/2/13‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي هــذا اليوم األربعاء املوافــق ‪1434/07/19‬هـ‬\n      ‫افتتحــت اجللســة الســاعة الواحــدة وخمســة وأربعــون دقيقــة وقــد وردنــا‬\n      ‫صــورة مــن كتــاب رئيــس احملكمــة العليــا املوجــه أصلــه إلــى خــادم‬\n      ‫احلرمــن الشــريفني رئيــس مجلــس الــوزراء رقــم ‪ 341118972‬يف‬\n      ‫‪1434/07/03‬ه ــاملرفق معــه قــرار الدائــرة اجلزائيــة األولــى باحملكمــة‬\n\n\n‫‪237‬‬\n\f‫العليــا رقــم ‪ 1/1/139‬يف ‪1434/6/13‬ه ـ املتضمــن املصادقــة علــى‬\n‫احلكــم ونصــه ‪ :‬فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ولألســباب‬\n‫التــي ذكرهــا أصحــاب الفضيلــة حــكام القضيــة قــرروا احلكــم مبــا‬\n‫يلــي ‪ :‬أوال ‪ :‬إقامــة حــد احلرابــة علــى املدعــى عليــه واقتــراح أصحــاب‬\n‫الفضيلــة نفيــه‪ .‬ثاني ـاً‪ :‬إقامــة حــد املســكر بجلــده ثمانــن جلــده دفعــة‬\n‫واحــدة ‪ .‬ثالث ـاً‪ :‬ثبــت لديهــم إدانــة املدعــى عليــه بتعاطيــه لثــاث حبــات‬\n‫محظــورة وقــرروا تعزيــره بجلــده ســبعني جلــده دفعــة واحــدة‪ .‬رابعـاً‪ :‬ثبــت‬\n‫لديهــم قيــادة املدعــى عليــه للســيارة حتت تأثير املســكر وعقابه يف ذلك‬\n‫لولــي األمــر ‪ ،‬وصرفــوا النظــر عــن بقيــة طلــب املدعــي العــام‪ .‬وبعرضــه‬\n‫علــى الطرفــن قــررا عــدم القناعــة ‪ ،‬وبرفعــه حملكمــة االســتئناف‬\n‫مبنطقــة حائــل صدقتــه بالقــرار رقــم (‪ )3431178‬يف ‪1434/02/05‬هــ‪.‬‬\n‫ثــم وردت املعاملــة إلــى احملكمــة العليــا كمــا تقــدم ‪ ،‬وبدراســة الصــك‬\n‫املذكــور ‪ ،‬وجميــع أوراق املعاملــة قــررت الدائــرة املوافقــة علــى احلكــم‬\n‫أه ـ ‪ .‬أعضــاء احملكمــة العليــا ‪...........‬و‪...........‬و‪...........‬و‪ ...........‬ورئيــس‬\n‫الدائــرة ‪...........‬تواقيعهــم وأختامهــم ‪ ،‬وأمــرت بإحلــاق ذلــك علــى ســجله‬\n‫‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                  ‫وســلم ‪ .‬حــرر يف ‪1434/7/19‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                            ‫‪238‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":222,"source_page_end":238,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0b99fb5f1c944d696eee559d8e736030392742c2380eeade5d2b400ebd537083","normalized_text_hash":"9e9cb3ab3bc56d33be370c66ac3702d5f81182f3504ab11fa38d9487c1747c8b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p222-349934"},{"id":"7209ff70-512c-55bc-a036-997a4349aa8d","document_type":"judgment","category":"judicial","subcategory":"general","title":"حرابة -سرقة -سطو مسلح -شرب املسكر -تهديد بالساح - سرقة سيارة -إحداث إصابات -مقاومة قوات األمن -اقرار مصدق شرع ا -من شروط احلرابة حمل الساح -تعزير بالسجن واجللد.","document_number":"34176771","case_number":"34100345","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة ومبشاركة القاضين بها","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/2","year":"1434","subject":"حرابة -سرقة -سطو مسلح -شرب املسكر -تهديد بالساح - سرقة سيارة -إحداث إصابات -مقاومة قوات األمن -اقرار مصدق شرع ا -من شروط احلرابة حمل الساح -تعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 34176771 :‬تاريخه‪1434/4/2:‬هـ‬\n                         ‫رقم الدعوى‪34100345 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                    ‫‪ 195169‬تاريخه‪1434/4/2 :‬هـ‬\n\n\n      ‫حرابــة ‪ -‬ســرقة ‪ -‬ســطو مســلح ‪ -‬شــرب املســكر ‪ -‬تهديــد بالســاح ‪-‬‬\n      ‫ســرقة ســيارة ‪ -‬إحــداث إصابــات ‪ -‬مقاومــة قــوات األمــن ‪ -‬اقــرار مصــدق‬\n      ‫شــرع ًا ‪ -‬مــن شــروط احلرابــة حمــل الســاح ‪ -‬تعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n\n      ‫قــال ابــن قدامــة ‪»:‬الشــرط الثانــي أن يكــون معهــم ســاح فــإن لــم يكــن‬\n      ‫معهــم ســاح فهــم غيــر محاربــن ألنهــم ال مينعــون مــن يقصدهــم وال‬\n                                     ‫نعلــم يف هــذا خالفـ ًا أ‪.‬ه ـ املغنــي ‪. 298/10‬‬\n\n\n\n\n      ‫جــرى توجيــه االتهــام للمدعــى عليــه باالشــتراك يف الســطو علــى عــدد‬\n      ‫مــن العمالــة مبحطــات الوقــود حتــت تهديــد الســاح وســلبهم والتســبب‬\n      ‫يف إصابــة اثنــن منهــم واالشــتراك يف ســرقة ســيارة وصــدم ســيارة‬\n      ‫الدوريــة وإحــداث تلفيــات بهــا‪ ،‬والهــروب مــن رجــال األمــن‪ ،‬والتســتر‬\n      ‫علــى شــريكه باجلرميــة وطلــب إثبــات مــا أســند إليــه واحلكــم عليــه‬\n      ‫بحــد احلرابــة ‪ ،‬حيــث تلقــت الشــرطة بالغــا مــن عمــال محطــة بــأن‬\n      ‫املدعــى عليــه ومعــه شــخص آخــر قامــا بتهديدهــم وســلبوا مــا يقــارب‬\n      ‫تســعة آالف ريــال وعشــرين دفتــرا «بطاقــات وقــود» وجــواالت العاملــن‬\n      ‫وكســرا كاميــرا املراقبــة ثــم هربــا ‪ ،‬ثــم تلقــت الشــرطة بالغــا مــن‬\n‫‪239‬‬\n\f‫منــدوب شــركة تأجيــر ســيارات عــن حضــور املدعــى عليــه ونــزع املفتــاح‬\n‫مــن العامــل بالقــوة وهــرب بهــا ‪ ،‬كمــا تلقــت الشــرطة بالغــا عــن‬\n‫عمليــة ســطو أخــرى ألحــد محطــات الوقــود ‪ ،‬جــرى البحــث والتحــري‬\n‫عنهمــا والتوصــل للمدعــى عليــه وهــرب بعدمــا قــام باالصطــدام بســيارة‬\n‫الدوريــة‪ ،‬قبــض علــى املدعــى عليــه الحقــا عنــد أحــد الشــقق املفروشــة‬\n‫وبتفتيــش الغرفــة التــي يســكنها عثــر معــه علــى ســبعة جــواالت منهــا‬\n‫أحــد اجلــواالت املســروقة مــن أحــد عمــال احملطــة وكوبونــات احملطــة‬\n‫ومســدس أســود غيــر حقيقــي وســاطور‪ ،‬كمــا عثــر معــه علــى قطعــة‬\n‫يشــتبه بأنهــا مــن احلشــيش املخــدر‪ ،‬تعــرف العمــال علــى املدعــى عليــه‪،‬‬\n‫أقــر املدعــى عليــه مبــا ورد يف الئحــة االدعــاء العــام وقــرر بأنــه كان‬\n‫حينهــا ســكرانا وأنــه هــدد عمــال احملطــة مبســدس لعبــة إال أنــه لــم يقــم‬\n‫بضربهــم وتعذيبهــم كمــا أقــر أنــه أخــذ مــن احملطــة املبالــغ املشــار لهــا‬\n‫يف صحيفــة الدعــوى واجلــواالت مــن العمــال والكوبونــات كمــا أنكــر‬\n‫قيامــه بســرقة الســيارة ودفــع بأنــه أخذهــا مــن شــخص آخــر وال يعلــم‬\n‫عــن كونهــا مســروقة وأقــر بهربــه واصطدامــه بســيارة الدوريــة ‪ ،‬عليــه‬\n‫وألن املدعــى عليــه لــم يكــن معــه ســاح وإمنــا مســدس اللعبــة وهــو ليــس‬\n‫بســاح وال يف معنــى الســاح‪ ،‬وألن املدعــي العــام لــم يقــدم بينــة تؤيــد‬\n‫دعــواه وغايــة مــا قــدم إقــرار املدعــى عليــه املصــدق شــرع ًا وأيضـ ًا مــا ورد‬\n‫يف التقريــر الطبــي لعاملــي احملطــة وهــذا يقــوي التهمــة علــى املدعــى‬\n‫عليــه باعتدائــه علــى عاملــي احملطــة بالســاح‪ ،‬وجلميــع مــا ســبق فقــد‬\n‫حكمــت الدائــرة مبــا يلــي‪ :‬أوالً‪ /‬صــرف النظــر عــن طلــب املدعــي العــام‬\n‫إقامــة حــد احلرابــة علــى املدعــى عليــه لعــدم ثبــوت موجبــه‪ .‬ثانيـاً‪ /‬تعزيــر‬\n‫املدعــى عليــه بســجنه ثمانيــة أعــوام مــن تاريــخ إيقافــه وجلــده ثمامنائــة‬\n\n\n                                                                                         ‫‪240‬‬\n\f      ‫جلــدة مفرقــة علــى دفعــات كل دفعــة خمســن جلــدة بــن كل فتــرة‬\n      ‫وأخــرى عشــرة أيــام‪ .‬ثالث ـاً‪ /‬ثبــوت إدانــة املدعــى عليــه بشــرب املســكر‬\n      ‫ويجلــد لقــاء ذلــك ثمانــن جلــدة دفعــة واحــدة حــد املســكر ‪ ،‬قــرر‬\n      ‫املدعــى عليــه القناعــة بينمــا قــرر املدعــي العــام عدمهــا وأفهــم بتعليمــات‬\n                      ‫االســتئناف ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة العامــة‬\n      ‫مبحافظــة جــدة ومبشــاركة القاضيــن بهــا ‪ .............‬والقاضــي ‪...........‬‬\n      ‫القاضــي يف احملكمــة العامــة مبحافظــة جــدة وبنــاء علــى املعاملــة‬\n      ‫احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة جــدة‪/‬‬\n      ‫املســاعد برقــم ‪ 34100345‬وتاريــخ ‪1434/3/1‬ه ـ املقيــدة باحملكمــة‬\n      ‫برقــم ‪ 34381367‬وتاريــخ ‪1434/01/27‬ه ـ ويف يــوم االثنــن‬\n      ‫‪1434/03/09‬هـ افتتحت اجللســة الســاعة ‪ 11 : 00‬وفيها حضر املدعي‬\n      ‫العــام ‪...........‬وادعــى علــى احلاضــر معــه ‪28 ،...........‬عام ـ ًا ‪ ،‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )...........‬موقــوف يف ســجون‬\n      ‫محافظــة جــدة مبوجــب أمــر متديــد التوقيــف رقــم (‪ )18/121‬وتاريــخ‬\n      ‫ا فيدعــواه أنــه بتاريــخ ‪1433/8/21‬ه ـ تلقــت‬           ‫‪1433/9/26‬ه ـ قائ ـ ً‬\n      ‫الدوريــات األمنيــة بــاغ مــن عمــال محطــة ‪...........‬بطريــق ………وهــم‬\n      ‫ال مــن املقيم‪............./‬واملقيــم‪ ........... /‬واملقيــم‪.........../‬‬     ‫ك ً‬\n      ‫واملقيــم‪( .........../‬بنقالديشــيي اجلنســية) واملواطن‪.........../‬الذيــن أفــادوا‬\n      ‫عــن حضــور املدعــى عليــه ومعــه شــخص آخــر الــى احملطــة وبحوزتهمــا‬\n      ‫ســاح ابيــض مــن نــوع ســاطور وســاح نــاري مــن نــوع مســدس (غيــر‬\n\n‫‪241‬‬\n\f‫حقيقــي) وقامــا بتهديدهــم وطلبــا منهــم إرشــادهما علــى مــكان وجــود‬\n‫إيــرادات احملطــة فقــام العامــل بإيصالهمــا إلــى املكتــب اخلــاص باحملطــة‬\n‫حتــت تهديــد الســاح وعنــد وصولهمــا للمكتــب قامــا بضــرب العامــل‬\n‫وتهديــد جميــع األشــخاص الذيــن كانــوا بداخــل الغرفــة وأخــذا إيــراد‬\n‫احملطــة وقــدره (‪ )9272‬تســعة آالف ومائتــان واثنــان وســبعون ريــا ًال‬\n‫وعــدد عشــرين دفتــر (كــروت بنزيــن) وجــواالت العاملــن وعددهــا‬\n‫تســعة جــواالت وكســرا كاميــرا املراقبــة ثــم هربــا‪ ،‬وقــد صــدر بحــق‬\n‫املخبر‪.........../‬التقريــر الطبــي رقــم (بــدون) وتاريــخ ‪1433/8/21‬ه ـ‬\n‫املتضمــن إصابتــه بكدمــة بالعــن اليمنــى ومــدة الشــفاء ثالثــة أيــام‬\n‫وصــدر بحــق املخبر‪.........../‬التقريــر الطبــي رقــم (بــدون) وتاريــخ‬\n‫‪1433/8/21‬ه ـ املتضمــن إصابتــه بجــرح قطعــي يف فــروة الــرأس ومــدة‬\n‫الشــفاء أســبوع ‪ .‬وبتاريــخ ‪1433/8/21‬ه ـ أبلــغ مركــز شــرطة ‪...........‬‬\n‫املواطــن ‪....................../‬منــدوب شــركة‪...........‬لتأجير الســيارات عــن‬\n‫حضــور املدعــى عليــه الــى فــرع الشــركة بشــارع‪...........‬ألجل اســتئجار‬\n‫ســيارة وطلــب معاينــة الســيارة قبــل أن يســتأجرها فخــرج معــه الــى‬\n‫الســيارة التــي كانــت متوقفــة أمــام الفــرع مــن نــوع ‪ ..............‬رقــم اللوحــة‬\n‫(‪ )...........‬اللــون ‪ ..........‬وقــام بفتحهــا لــه ملعاينتهــا إال أنــه ســحب املفتــاح‬\n‫مــن يــده بالقــوة وركــب الســيارة عنــوة وهــرب بهــا ‪ .‬وبتاريــخ‬\n‫‪1433/9/18‬ه ـ تلقــت الدوريــات األمنيــة بــاغ مــن عمــال محطــة ‪...........‬‬\n‫ال مــن املقيم‪.........../‬واملقيــم ‪........... /‬‬      ‫بطريــق املدينــة وهــم ك ً‬\n‫واملقيم‪....................../‬واملقيــم‪( ………/‬بنقالديشــيي اجلنســية) الذيــن‬\n‫أفــادوا عــن حضــور املدعــى عليــه ومعــه شــخص آخــر إلــى مقــر ســكنهم‬\n‫وطرقــا عليهــم البــاب وعندمــا فتحــوا البــاب كان أحــد األشــخاص‬\n\n\n                                                                                              ‫‪242‬‬\n\f      ‫يحمــل يف يــده مســدس هددهــم بــه وأخــذ منهــم إيــراد احملطــة املقــدر‬\n      ‫بحوالــي (‪ )7689‬ســبعة آالف وســتمائة وتســعة وثمانــن ريــا ًال وأجهــزة‬\n      ‫جواالتهــم وعددهــا ســبعة أجهــزة وإقامــة املدعو‪.........../‬ثــم أقفــا‬\n      ‫الســكن عليهــم مــن اخلــارج وهربــا وبنــاء علــى املعلومــات التــي أدلــى بهــا‬\n      ‫املجنــي عليهــم وبالبحــث والتحــري اتضــح بــأن هنــاك شــريحتني مت‬\n      ‫تركيبهــا علــى احــد األجهــزة املســروقة بعــد احلادثــة وان الشــريحتني‬\n      ‫تخــص املدعو‪(.........../‬لــم يتــم توجيــه االتهــام إليــه بشــيء) الــذي مت‬\n      ‫القبــض عليــه بتاريــخ ‪1433/9/18‬ه ـ بحــي ‪...........‬ومبناقشــته أفــاد بأنــه‬\n      ‫قبــل شــهر رمضــان ورد لــه اتصــال علــى جوالــه مــن املدعــى عليــه وطلــب‬\n      ‫منــه مقابلتــه لوجــود مشــكلة لديــه وقابلــه املدعــى عليــه ومعــه شــخص‬\n      ‫آخــر ال يعرفــه ألجــل إيصالهمــا إلــى شــارع ‪...........‬فركبــا معــه فذكــر‬\n      ‫لــه املدعــى عليــه بأنــه حدثــت لهمــا مضاربــة مــع عمــال محطــة ‪...........‬‬\n      ‫ولــم يوضــح لــه تفاصيــل مــا حــدث وبســؤاله عــن الشــريحتني وجهــاز‬\n      ‫الهاتــف اجلــوال املســروق ذكــر بــأن اجلهــاز أخــذه مــن املدعــى عليــه وهــو‬\n      ‫موجــود لديــه باملنــزل وتبــن انــه اجلهــاز الــذي ســلب مــن املجنــي‬\n      ‫عليه‪،....................../‬وقــد مت الوصــول إلــى املدعــى عليــه مــن خــال‬\n      ‫متكــن املدعو‪.........../‬مــن االتصــال عليــه وقــد حضــر وبقيادتــه الســيارة‬\n      ‫الفــورد املبلــغ عــن ســرقتها وأثنــاء القبــض صــدم ســيارة الدوريــة ممــا‬\n      ‫أحــدث بهــا تلفيــات قــدرت مببلــغ (‪ )1500‬ريــال وهــرب وبتاريــخ‬\n      ‫‪1433/9/19‬ه ـ عثــر علــى الســيارة ‪ .....‬متوقفــة عنــد إحــدى الشــقق‬\n      ‫املفروشــة التــي يســكن بهــا املدعــى عليــه فتــم القبــض عليــه وبتفتيــش‬\n      ‫الغرفــة التــي يســكنها عثــر علــى ســبعة أجهزة هواتف جــوال من ضمنها‬\n      ‫اجلهــاز املســروق مــن عمــال احملطــة وكذلــك كوبونــات بنزيــن تابعــة‬\n\n\n‫‪243‬‬\n\f‫حملطــة ‪...........‬ومســدس لونــه أســود (غيــر حقيقــي) وســاطور كمــا عثــر‬\n‫علــى قطعــة يشــتبه أنهــا مــن احلشــيش املخــدر (فصلــت لذلــك أوراق‬\n‫مســتقلة وأحيلــت ملكافحــة املخــدرات) واتضــح بــأن الســيارة التــي‬\n‫كانــت بقيادتــه مســروقة ومعمــم عنهــا ومبناقشــته مبدئي ـ ًا اعتــرف‬\n‫بالســرقة مبرافقــة شــخص آخــر يدعى‪،.........../‬ســعودي اجلنســية‬\n‫(فصلــت أوراق مســتقلة للبحــث عنــه( وباســتجواب املدعــى عليــه اعتــرف‬\n‫أنــه اتفــق مــع املدعو‪.........../‬علــى ســرقة محطــة ‪...........‬الواقعــة بطريــق‬\n‫امللــك ……… كونهمــا محتاجــن للمــال وعنــد وصولهمــا للمحطــة‬\n‫كان يوجــد هنــاك غرفــة بأحــد زوايــا احملطــة وعنــد مشــاهدتهما لعمال‬\n‫احملطــة هددهــم بواســطة مســدس لونــه أســود (لعبــة) وهددهــم زميلــه‬\n‫بســكني وأدخلوهــم داخــل الغرفــة وســلبا مــا معهــم مــن مبالــغ ماليــة‬\n‫وكــروت تعبئــة بنزيــن ثــم هربــا إلــى عمــارة حتــت اإلنشــاء قريبــة مــن‬\n‫احملطــة وظــا بهــا قرابــة ثــاث ســاعات ثــم اتصــل بزميلــه ‪......................‬‬\n‫وطلــب منــه احلضــور ألجــل إيصالهمــا إلــى دوار ‪...........‬وبعــد أن ركبــا‬\n‫مــع‪........... /‬يســلمه احــد اجلــواالت املســروقة دون أن يبلغــه بعمليــة‬\n‫الســرقة كمــا أقــر بــان الســيارة‪......‬التي ضبطــت معــه ســرقها زميلــه‬\n‫‪.........../‬ويعلــم بســرقتها وقــد أخذهــا منــه مقابــل مبلــغ وقــدره خمســمائة‬\n‫ريــال وصدقــت أقوالــه شــرع ًا بذلــك‪ .‬وبعــرض املدعــى عليــه‬\n‫واملدعو‪.........../‬علــى املخبريــن يف محطــة ‪...........‬بحــي ‪...........‬تعرفــوا‬\n‫علــى املدعــى عليــه وأكــدوا أنــه مــن ضمــن األشــخاص الذيــن هددوهــم‬\n‫مبســدس كان يحملــه ‪ .‬وبعرضهمــا علــى املخبريــن يف محطــة ‪...........‬‬\n‫بحــي ‪...........‬تعرفــوا علــى املدعــى عليــه وأكــدوا أنــه مــن ضمــن‬\n‫األشــخاص الذيــن هددوهــم مبســدس كان يحملــه ‪ .‬وقــد انتهــى‬\n\n\n                                                                                         ‫‪244‬‬\n\f      ‫التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه باالشــتراك يف الســطو علــى‬\n      ‫عــدد مــن العمالــة مبحطــات الوقــود حتــت تهديــد الســاح وســلبهم‬\n      ‫والتســبب يف إصابــة اثنــن منهــم واالشــتراك يف ســرقة ســيارة وصــدم‬\n      ‫سيارة الدورية وإحداث تلفيات بها‪ ،‬والهروب من رجال األمن‪،‬والتستر‬\n      ‫علــى شــريكه باجلرميــة ‪،‬مبوجــب قــرار االتهــام رقــم ‪ ...........‬املؤيــد بقــرار‬\n      ‫جلنــة إدارة الهيئــة رقم‪...........‬لعــام ‪1434‬ه ـ وذلــك لألدلــة والقرائن التالية‬\n      ‫‪ -1:‬اعترافــه املصــدق شــرع ًا املنــوه عنــه املــدون يف دفتــر التحقيــق لفــة‬\n      ‫(‪ )40‬ص(‪ -2.)12‬محضــر القبــض املنــوه عنــه املــدون يف دفتــر التحقيــق‬\n      ‫املرفــق داخــل الطــرد لفــة (‪ )40‬ص(‪ -3.)10-2‬محضــر العــرض املــدون‬\n      ‫علــى ص(‪ )8‬لفــة(‪ -4 .)1‬محضــر العــرض املنــوه عنــه املــدون يف دفتــر‬\n      ‫التحقيــق املرفــق داخــل الطــرد لفــة(‪ )68‬ص (‪ -5 .)4-3‬مــا جــاء يف‬\n      ‫التقريريــن الطبيــن املنــوه عنهمــا املرفقــن داخــل الطــرد لفــة (‪.)13-12‬‬\n      ‫‪ -6‬العثــور علــى بعــض املســروقات بحوزتــه مــن ضمنهــا جــواالت‬\n      ‫وكوبونــات التعبئــة اخلاصــة باحملطــة‪ -7 .‬ماجــاء يف كتــاب البحــث‬\n      ‫اجلنائــي رقــم ‪/14/20/19275‬ع‪ 22‬يف ‪1433/9/25‬ه ـ املتضمــن صــدم‬\n      ‫املدعــى عليــه بالســيارة التــي كان يقودهــا ســيارة الدوريــة وقيمــة تقديــر‬\n      ‫التلفيــات التــي حلقــت بهــا ص(‪ -8 .)50-49‬مــا ورد يف إقــرار ‪...........‬‬\n      ‫املــدون علــى ص(‪ )11‬لفــة(‪ .)40‬وباالطــاع علــى صحيفــة ســوابقه عثــر‬\n      ‫لــه علــى ســابقة حيــازة مخــدرات‪ .‬وحيــث إن مــا أقــدم عليــه املدعــى عليــه‬\n      ‫وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n      ‫ويعــد ضربـ ًا مــن ضــروب احلرابــة والســعي يف األرض فســاد ًا وتعــد علــى‬\n      ‫حرمــات املســلمني وأموالهــم علــى ســبيل الغلبــة والقهــر‪ ،‬فإننــي اطلــب‬\n      ‫إثبــات مــا اســند إليــه اســتنادا ًللمادتــن (‪ ) 126،129‬مــن نظــام‬\n\n\n‫‪245‬‬\n\f‫اإلجــراءات اجلزائيــة واحلكــم عليــه بحد احلرابة الــوارد يف اآلية الكرمية‬\n‫رقــم (‪ )33‬مــن ســورة املائــدة علــى ضــوء قــرار هيئــة كبــار العلمــاء رقــم‬\n‫(‪ )85‬وتاريــخ ‪1401/11/11‬هــ‪( .‬علم ـ ًا أن احلــق اخلــاص مــازال قائم ـاً)‬\n‫هــذه دعــواي وبعــرض مــا جــاء يف دعــوى املدعــي العــام علــى املدعــى عليــه‬\n‫ا مــا ذكــره املدعــي العــام يف الئحتــه مــن الســطو على‬     ‫‪...........‬أجــاب قائـ ً‬\n‫احملطــة فهــو صحيــح وأنــا كنــت يف حالــة ســكر عنــد قيامــي بالســطو‬\n‫علــى احملطــة وقــد هــددت عمــال احملطــة مبســدس لعبــة ولــم أقــم‬\n‫بضربهــم وتعذيبهــم وقــد أخــذت مــن احملطــة املبلــغ املذكــور يف الدعــوى‬\n‫وكذلــك بعــض اجلــواالت والكوبونــات وأمــا مــا ذكــر مــن اشــتراكي‬\n‫يف ســرقة الســيارة فغيــر صحيــح فقــد أخــذت الســيارة مــن ‪...........‬وال‬\n‫أعلــم بســرقتها مــن عدمــه وأمــا مــا ذكــر مــن صدمــي لســيارة الدوريــة‬\n‫وهروبــي مــن رجــال األمــن فهــو صحيــح وأنــا تائــب ونــادم علــى مــا فعلــت‬\n‫ا نعــم لــدي ســابقة‬  ‫هكــذا أجــاب وبســؤاله عــن الســابقة أجــاب قائ ـ ً‬\n‫حيــازة مخــدرات هكــذا أجــاب ولالطــاع علــى أوراق املعاملــة جــرى‬\n‫تأجيــل اجللســة إلــى يــوم االثنــن ‪1434/3/23‬ه ـ الســاعة ‪09 : 00‬‬\n‫وأغلقــت اجللســة الســاعة ‪ 11 : 30‬وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n‫نبينــا محمــد وعلــى آلــه وصحبــه حــرر يف ‪1434/3/16‬ه ـ ثــم يف جلســة‬\n‫أخــرى ويف هــذا اليــوم االثنــن ‪1434/3/23‬ه ـ افتتحــت اجللســة الســاعة‬\n‫‪ 09 : 00‬وفيهــا حضــر املدعــي العــام حضــر حلضوره املدعــى عليه ‪...........‬‬\n‫ا بينتــي مــا جــاء يف أوراق‬  ‫وبســؤال املدعــي العــام عــن بينتــه أجــاب قائ ـ ً‬\n‫املعاملــة هكــذا أجــاب وبالرجــوع إلــى أوراق املعاملــة وجدنــا باللفــة رقــم‬\n‫‪ 40‬صحيفــة ‪ 12‬إقــرار االعتــراف املصــدق شــرع ًا والــذي نصــه إقــرار‬\n‫اعتــراف بتاريــخ ‪1433/9/19‬ه ـ أقــر أنــا املدعــو‪ .............. /‬ســعودي‬\n\n\n                                                                                           ‫‪246‬‬\n\f      ‫اجلنســية ‪ 28‬ســنة رقــم الهويــة ( ‪ )...........‬وأنــا بكامــل قــواي العقليــة‬\n      ‫املعتبــرة شــرع ًا وبطوعــي واختيــاري ال مجبــر ًا وال مكره ـ ًا بأنــه قبــل‬\n      ‫شــهر رمضــان بحوالــي أســبوعني تقريبـ ًا قابلــت أحــد أصدقائــي يدعــى‪/‬‬\n      ‫‪ ...........‬واتفقــت معــه علــى ســرقة محطــة‪ ...........‬الواقعــة بطريــق امللــك‬\n      ‫ا عنــد وصولنــا للمحطــة كان‬         ‫لكونــه ال يوجــد معنــا أي مبالــغ وفع ـ ً‬\n      ‫يوجــد هنــاك غرفــة يف إحــدى زوايــا احملطــة عندهــا شــاهدنا عمــال‬\n      ‫احملطــة وقمنــا بتهديدهــم بواســطة مســدس لونــه أســود معــي لعبــة‬\n      ‫وســكني مــع زميلــي وقمنــا بإدخالهــم بداخــل الغرفــة وتهديدهــم‬\n      ‫باملســدس وبعــد ذلــك قمنــا بســلب منهــم مبلــغ وقــدره ســبعة آالف ريــال‬\n      ‫وكــروت كوبــون تعبئــة بنزيــن وشــريط س يــدي اخلــاص باحملطــة‬\n      ‫وبعدهــا ذهبــت إلــى عمــارة قريبــة مــن احملطــة حتــت اإلنشــاء وجلســنا‬\n      ‫بهــا مــا يقــارب ثــاث ســاعات وعندهــا اتصلــت علــى أحــد أصدقائــي‬\n      ‫ا حضــر‬   ‫يدعــى‪........... /‬وطلبــت منــه احلضــور لغــرض إيصالــي وفع ـ ً‬\n      ‫املذكــور بســيارة ‪ ......‬وكان معــه شــخص يدعــى‪........... /‬وعنــد حضور‬\n      ‫املذكــور ‪...........‬ركبنــا معــه وقــام بإيصالــي إلــى دوار ‪...........‬بحــي‬\n      ‫‪...........‬علم ـ ًا بأننــي قمــت بإعطــاء املذكــور جهــاز مــن األجهــزة التــي‬\n      ‫قمنــا بســرقتها مــن عمــال احملطــة هــذا إقــراري ومســتعد التصديــق عليــه‬\n      ‫شــرعاً‪ .‬املقــر مبــا فيــه ‪......................‬بصمــة أ‪.‬ه ـ وبعــرض ذلــك علــى‬\n      ‫ا مــا ورد يف اإلقــرار كلــه صحيــح ولكنــي‬           ‫املدعــى عليــه قــرر قائ ـ ً‬\n      ‫كنــت يف حالــة ســكر أثنــاء قيامــي بالســطو علــى احملطــة هكــذا قــال‬\n      ‫كمــا وجــد باللفــة ‪ 13‬التقريــر الطبــي املبدئــي رقــم ‪ 10861698‬يف‬\n      ‫‪1433/8/21‬ه ـ املتضمــن إصابة‪...........‬بنغالديشــي اجلنســية بكدمــة‬\n      ‫بالعــن اليمنــى ‪.‬كمــا وجــد باللفــة رقــم ‪ 14‬التقريــر الطبــي املبدئــي رقــم‬\n\n\n‫‪247‬‬\n\f‫‪ 10861699‬يف ‪1433/8/21‬ه ـ املتضمــن إصابة‪...........‬بنغالديشــي‬\n‫اجلنســية بجــرح قطعــي يف فــروة الــرأس‪ .‬وبعــرض التقريريــن علــى‬\n‫ا ال أذكــر أنــي ضربــت عمــال احملطــة وإمنــا‬   ‫املدعــى عليــه أجــاب قائ ـ ً‬\n‫اكتفيــت بتهديدهــم مبســدس اللعبــة‪ ،‬لكــن قــد أكــون قمــت بدفعهــم‬\n‫هكــذا أجــاب كمــا جــرى االطــاع علــى اإلقــرار املصــدق شــرع ًا‬\n‫ل‪...........‬يف اللفــة (‪ )40‬صحيفــة (‪ )11‬والــذي نصــه إقــرار بتاريــخ‬\n‫‪1434/9/19‬ه ـ أقــر أنــا املدعــو‪...................... /‬ســعودي اجلنســية ‪34‬‬\n‫ســنة رقــم الهويــة (‪ )...........‬وأنــا بكامــل قــواي العقليــة شــرع ًا وبطوعــي‬\n‫واختيــاري بأنــه قبــل شــهر رمضــان ورد لــي اتصــال علــى جوالــي رقــم‬\n‫(‪ )...........‬مــن املدعــو‪........... /‬وكان ذلــك يف حــدود الســاعة الرابعــة‬\n‫فجــر ًا وطلــب منــي احلضــور إلــى طريــق امللــك لغــرض مقابلتــه لكــون‬\n‫ا قمــت بقيــادة ســيارتي مــن نــوع ‪ ......‬وذهبــت إلــى‬ ‫لديــه مشــكلة وفع ـ ً‬\n‫ال من شــخص يدعى‪........... /‬وشــخص‬        ‫طريــق امللــك وكان يرافقنــي ك ً‬\n‫آخــر يدعــى ‪........... /‬وعنــد وصولــي لطريــق امللــك قابلــت املذكــور‪/‬‬\n‫‪...........‬وشــخص ال أعــرف اســمه وركبــوا معــي بالســيارة وذكــر لــي‬\n‫املذكــور‪........... /‬بأنــه حــدث مقاومــة لهــم مــع عامــل محطــة ‪...........‬‬\n‫وقــام بإعطائــي جــوال ‪ ......‬وهــو اجلهــاز الــذي أحضــره أخــي ‪...........‬‬\n‫لــإدارة وكذلــك قــام املذكــور بإعطائــي كوبونــات تعبئــة بنزيــن‬\n‫شــركة‪...........‬وكان الشــخص الــذي يرافــق املدعــو‪........... /‬يرتــدي‬\n‫كاب علــى رأســه هــذا إقــراري وعليــه جــرى التوقيــع أ‪.‬ه ـ كمــا جــرى‬\n‫االطــاع علــى أوراق املعاملــة وجــرى االطــاع علــى مــا ورد يف محضــر‬\n‫القبــض املنــوه عنــه املــدون يف دفتــر التحقيــق املرفــق داخــل الطــرد لفــة‬\n‫(‪ )40‬صحيفــة (‪ .)2،10‬كمــا جــرى االطــاع علــى مــا ورد يف محضــر‬\n\n\n                                                                                       ‫‪248‬‬\n\f      ‫العــرض املــدون علــى ص(‪ )8‬لفــة (‪ .)1‬محضــر العــرض املــدون يف دفتــر‬\n      ‫التحقيــق داخــل الطــرد لفــة (‪ .)13،12‬كمــا جــرى االطــاع علــى مــا ورد‬\n      ‫يف كتاب البحث اجلنائي رقم ‪/14/20/19275‬ع‪ 22‬يف ‪1433/9/25‬هـ‬\n      ‫املتضمــن صــدم املدعــى عليــه بالســيارة التــي كان يقودهــا ســيارة‬\n      ‫الدوريــة وقيمــة تقديــر التلفيــات التــي حلقــت بهــا ص (‪ ،)50،49‬وللتأمــل‬\n      ‫رفعــت اجللســة وتأجلــت ليــوم االثنــن ‪1434/4/1‬ه ـ الســاعة ‪09 : 00‬‬\n      ‫وأغلقــت اجللســة الســاعة ‪ 09 : 30‬وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n      ‫نبينــا محمــد وعلــى آلــه وصحبــه حــرر يف ‪1434/3/23‬ه ـ ثــم يف جلســة‬\n      ‫أخــرى ويف هــذا اليــوم االثنــن ‪1434/04/01‬هـ افتتحت اجللســة الســاعة‬\n      ‫‪ 10 : 00‬وفيــه احضــر املدعــي العــام حضــر حلضوره املدعــى عليه ‪...........‬‬\n      ‫وبعــد االطــاع علــى املعاملــة وتأمــل أوراق القضيــة عليــه وبنــاء علــى مــا‬\n      ‫تقــدم مــن الدعــوى واإلجابــة ومبــا أن املدعــى عليــه قــد أقــر مبهاجمتــه‬\n      ‫لعمــال احملطــة وإخافتهــم مبســدس اللعبــة وأنكــر أن معــه ســاح أو‬\n      ‫ســكني أو غيــر ذلــك وألن مــن شــروط احملــارب وجــود الســاح معــه فــإن‬\n      ‫لــم يكــن معــه ســاح فهــو غيــر محــارب قــال ابــن قدامــة‪ :‬الشــرط الثانــي‬\n      ‫أن يكــون معهــم ســاح فــإن لــم يكــن معهــم ســاح فهــم غيــر محاربــن‬\n      ‫ألنهــم ال مينعــون مــن يقصدهــم وال نعلــم يف هــذا خالف ـ ًا أ‪.‬ه ـ املغنــي‬\n      ‫‪ 298/10‬واملدعــى عليــه لــم يكــن معــه ســاح وإمنــا كان معــه مســدس‬\n      ‫اللعبــة كمــا ذكــر ومســدس اللعبــة ليــس بســاح وال يف معنــى الســاح‬\n      ‫وألن املدعــي العــام لــم يقــدم بينــة تؤيــد دعــواه وغايــة مــا قــدم إقــرار‬\n      ‫املدعــى عليــه املصــدق شــرع ًا وأيضـ ًا مــا ورد يف التقريــر الطبــي لعاملــي‬\n      ‫احملطــة وهــذا يقــوي التهمــة علــى املدعــى عليــه باعتدائــه علــى عاملــي‬\n      ‫احملطــة بالســاح وجلميــع مــا ســبق فقــد حكمنــا مبــا يلــي‪ :‬أوالً‪ :‬صــرف‬\n\n\n‫‪249‬‬\n\f‫النظــر عــن طلــب املدعــي العــام إقامــة حــد احلرابــة علــى املدعــى عليــه‬\n‫لعــدم ثبــوت موجبــه‪ .‬ثاني ـاً‪ :‬تعزيــر املدعــى عليــه بســجنه ثمانيــة أعــوام‬\n‫مــن تاريــخ إيقافــه وجلــده ثمامنائــة جلــدة مفرقــة علــى دفعــات كل دفعــة‬\n‫خمســن جلــدة بــن كل فتــرة وأخــرى عشــرة أيــام ثالث ـاً‪ :‬ثبــت لدينــا‬\n‫إدانــة املدعــى عليــه بشــرب املســكر ويجلــد لقــاء ذلــك ثمانــن جلــدة‬\n‫دفعــة واحــدة حــد املســكر علمـ ًا بــأن احلــق اخلــاص مــازال قائمـ ًا وبعــرض‬\n‫ذلــك علــى املدعــي العــام قــرر عــدم القناعــة وجــرى تســليمه نســخة مــن‬\n‫احلكــم لالعتــراض عليــه خــال ثالثــن يوم ـ ًا وأمــا املدعــى عليــه فقــرر‬\n‫القناعــة وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n                                       ‫وصحبه وسلم حرر يف ‪1434/04/01‬هـ‬\n‫احلمــد هلل وحــده فلــدي أنــا ‪ .........‬القاضــي باحملكمــة العامــة بجــدة‬\n‫وكانــت املعاملــة قــد عــادت مــن محكمــة االســتئناف مبوجــب خطــاب‬\n‫فضيلــة رئيســها برقــم ‪ 34/381367‬يف ‪1434/6/27‬ه ــواملتضمن أنــه‬\n‫جــرى تدقيــق احلكــم مــن الدائــرة اجلزائيــة اخلماســية الثالثــة وصــدر‬\n‫بشــأنه القــرار ذو الرقــم ‪ 34176771‬وتاريــخ ‪1434/4/2‬ه ـ املــدون‬\n‫علــى ظهــر الصــك والــذي نصــه احلمــد هلل وحــده وبعــد‪ :‬فقــد اطلعنــا‬\n‫علــى هــذا الصــك رقــم ‪ 341767771‬وتاريــخ ‪1434/4/2‬ه ــالصادر مــن‬\n‫أصحــاب الفضيلــة القضــاة باحملكمــة العامــة بجــدة وأصدرنــا القــرار‬\n‫رقــم ‪ 34229460‬وتاريــخ ‪1434/6/4‬ه ـ املتضمــن املوافقــة علــى احلكــم‬\n‫أ‪.‬ه ـ وعليــه أمــرت بإحلــاق ذلــك علــى ضبطــه وســجله وبــاهلل التوفيــق‬\n‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه حــرر يف‬\n                                                            ‫‪1434/07/17‬ه ـ ‪.‬‬\n\n\n\n                                                                                     ‫‪250‬‬\n\f251\n\f252\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":239,"source_page_end":252,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"aac87b8e01cd0d7b182b59c954ad25da931b0899c73c848247402e76f72e98e8","normalized_text_hash":"81ce48e270a5d4d89a7cdf1eb80253d9c015fee84893fac41f8f1d8022714ff2","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p239-34176771"},{"id":"2dcfb181-1c31-5cc4-86dd-2be226324cc1","document_type":"judgment","category":"judicial","subcategory":"general","title":"خطف -إرغام فتاة على ركوب سيارة ومحاولة خطفها -االعتداء على فتاة بالضرب وسبها -االصطدام بسيارة -التعزير بالسجن واجللد واملنع من مباشرة أي عمل له ارتباط بالنساء األجنبيات","document_number":"34239665","case_number":"341974","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بينبع","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/13","year":"1434","subject":"خطف -إرغام فتاة على ركوب سيارة ومحاولة خطفها -االعتداء على فتاة بالضرب وسبها -االصطدام بسيارة -التعزير بالسجن واجللد واملنع من مباشرة أي عمل له ارتباط بالنساء األجنبيات","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34239665 :‬تاريخه ‪1434/6/13 :‬هـ‬\n                            ‫رقم الدعوى‪341974 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34290759‬تاريخه‪1434/8/8 :‬هـ‬\n\n\n      ‫خطــف ‪ -‬إرغــام فتــاة علــى ركــوب ســيارة ومحاولــة خطفهــا ‪ -‬االعتــداء‬\n      ‫علــى فتــاة بالضــرب وســبها ‪ -‬االصطــدام بســيارة ‪ -‬التعزيــر بالســجن‬\n      ‫واجللــد واملنــع مــن مباشــرة أي عمــل لــه ارتبــاط بالنســاء األجنبيــات‬\n                                                                             ‫عنــه ‪.‬‬\n\n\n\n\n       ‫ال) ‪.‬‬\n          ‫‪ -1‬قول اهلل تعالى‪( :‬وال تقربوا الزنا إنه كان فاحشة وساء سبي ً‬\n      ‫‪ -2‬قولــه صلــى اهلل عليــه وســلم‪( :‬إياكــم والدخــول علــى النســاء) رواه‬\n                                                               ‫البخــاري ومســلم‬\n      ‫‪ -3‬قولــه صلــى اهلل عليــه وســلم‪( :‬ال يخلــون رجــل بامــرأة إال كان‬\n                                         ‫الشــيطان ثالثهمــا) رواه الترمــذي‬\n\n\n\n\n      ‫توجيــه االتهــام للمدعــى عليــه بــإركاب فتــاة ال متــت لــه بصلــة شــرعية‬\n      ‫واالعتــداء عليهــا وســبها‪ ،‬واالصطــدام بســيارة متوقفــة بالطريــق‪،‬‬\n      ‫حيــث تقدمــت فتــاة بشــكوى علــى املدعــى عليــه مبحاولــة خطفهــا‪،‬‬\n      ‫طلــب املدعــي العــام إثبــات مــا أســند للمدعــى عليــه واحلكــم بعقوبــة‬\n      ‫تعزيريــة رادعــة لــه ولغيــره‪ ،‬أقــر املدعــى عليــه بركــوب الفتــاة ‪ ،‬وصــدم‬\n      ‫الســيارة املتوقفــة‪ ،‬وإنــكاره مــا ســوى ذلــك ‪ ،‬ودفــع بعــدم خطــف الفتــاة‬\n\n‫‪253‬‬\n\f‫وإمنــا ركبــت معــه لتوصيلهــا مــن املستشــفى ملنزلهــا ثــم طلبــت منــه مــا ًال‬\n‫فرفــض فادعــت بهــذه الدعــوى‪ ،‬أحضــر املدعــي العــام شــاهد ًا وهــو أحد‬\n‫أعضــاء الدوريــات األمنيــة‪ ،‬فشــهد بوجــود الفتــاة ملقــاة علــى األرض‬\n‫وذكــرت لــه مــا حصــل عليهــا مــن قبــل قائــد الســيارة ‪ ،‬جــرى الرجــوع‬\n‫إلــى محضــر االســتجواب ومحضــر الضبــط ومحضــر الشــهادة ومحضــر‬\n‫أقــوال املــرأة‪ ،‬صــدر احلكــم بثبــوت إدانــة املدعــى عليــه بــإركاب فتــاة‬\n‫ال متــت لــه بصلــة شــرعية ‪ ،‬وصــدم ســيارة متوقفــة ‪ ،‬وتوجيــه التهمــة‬\n‫لــه باالعتــداء علــى الفتــاة بالضــرب والــركل والتلفــظ عليهــا وتعزيــره‬\n‫بالســجن خمســة أشــهر وجلــده مائتــي جلــدة مفرقــة علــى دفعــات ومنعــه‬\n‫مــن مباشــرة أي عمــل لــه ارتبــاط بالنســاء األجنبيــات عنــه ‪ ،‬صــدق‬\n                                            ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد‪ :‬فلــدي أنــا ‪ .........‬القاضــي يف احملكمــة العامــة‬\n‫بينبــع ‪ ،‬وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بينبع‪/‬املســاعد برقــم ‪ ..........‬وتاريــخ ‪1434/01/03‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ ..........‬وتاريــخ ‪1433/12/29‬ه ـ ففــي يــوم االثنــن‬\n‫املوافــق ‪1434/01/26‬ه ـ افتتحــت اجللســة وفيهــا تقــدم املدعــي العــام‬\n‫ســعودي بالســجل املدنــي رقــم ‪ ..............‬بدعــوى محــررة يف املعاملــة جــاء‬\n‫فيهــا‪ :‬بصفتــي مدعيــا عامــا يف دائــرة االدعــاء العــام مبحافظــة ينبــع‬\n‫أدعــي علــى ‪ ......... ، .........‬عامــا ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم (‪ )..........‬عســكري بالدفــاع اجلــوي‪ ،‬قبــض عليــه بتاريــخ‬\n‫‪1433/7/16‬ه ـ وأفــرج عنــه بتاريــخ ‪1433/7/22‬هــ‪ ،‬حيــث أنــه بتاريــخ‬\n\n                                                                                       ‫‪254‬‬\n\f      ‫‪1433/7/16‬ه ـ تقدمــت الفتــاة‪ ........... /‬قيــام املتهــم أعــاه مبحاولــة‬\n      ‫خطفهــا وباالطــاع علــى محضــر القبــض تبــن أن املتهــم قــام بصــدم‬\n      ‫مجموعــة مــن الســيارات أثنــاء ســيره بالطريــق‪ ،‬وبســماع شــهادة‪......‬‬\n      ‫شــاهد الســيارة التــي يقودهــا املتهــم متيــل للجهــة اليســرى واليمنــى‬\n      ‫وصدمــت إحــدى الســيارات ‪ ،‬وبســماع شــهادة شــاهد الســيارة التــي‬\n      ‫يقودهــا املتهــم ويقــوم بــركل فتــاة مــن الســيارة وطرحهــا علــى األرض‬\n      ‫والتلفــظ عليهــا بقولــه‪( :‬اهلل يلعنــك) ‪ ،‬وباســتجواب املتهــم بعــد إحاطتــه‬\n      ‫بالتهمــة املنســوبة إليــه اعتــرف باصطحابــه للفتــاة املدعيــة ألجــل‬\n      ‫إيصالهــا وأنكــر مــا نســب إليــه مــن تهمــة ‪ ،‬وبالبحــث عــن ســوابقه تبــن‬\n      ‫عــدم وجــود ســوابق مســجلة عليــه ‪ ،‬وانتهــى التحقيــق إلــى توجيــه االتهــام‬\n      ‫ل ــه بــإركاب فتــاة ال متــت لــه بصلــة شــرعية واالعتــداء عليهــا والتلفــظ‬\n      ‫عليهــا وصــدم ســيارة كانــت متوقفــة بالطريــق ‪ ،‬وذلــك لألدلــة والقرائــن‬\n                                                                                 ‫التاليــة‪:‬‬\n      ‫‪ -1‬مــا جــاء يف أقــوال املتهــم علــى الصفحــة (‪ )1‬املرفــق علــى ملــف‬\n                                                   ‫التحقيــق املرفــق لفــة رقــم (‪)18‬‬\n                                  ‫‪ -2‬ما جاء يف محضر القبض املرفق لفة رقم (‪)8‬‬\n         ‫‪ -3‬ما جاء يف شهادة الشاهد على الصفحة رقم ‪ )4( :‬املرفق لفة (‪)2‬‬\n      ‫‪ -4‬مــا جــاء يف شــهادة الشــاهد علــى الصفحــة رقــم ‪ )8( :‬املرفــق لفــة‬\n      ‫(‪ ، )18‬وحيــث أن مــا أقــدم عليــه املتهــم فعــل محــرم ومعاقــب عليــه‬\n      ‫شــرع ًا ‪ -‬لــذا أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة‬\n      ‫رادعــة لــه ولغيــره ‪ .‬هكــذا ادعــى املدعــي العــام ‪ .‬وبعــرض الدعــوى علــى‬\n      ‫املدعــى عليــه أجــاب قائــا ‪ :‬مــا ذكــره املدعــي العــام يف دعــواه منــه‬\n      ‫مــا هــو صحيــح ومنــه مــا هــو غيــر صحيــح ‪ ،‬فالصحيــح هــو ركــوب‬\n\n\n‫‪255‬‬\n\f‫الفتــاة املذكــورة يف الدعــوى معــي وصدمــي لســيارة واحــد نــوع (‪).....‬‬\n‫ومــا ســوى ذلــك فغيــر صحيــح ‪ ،‬فلــم أختطــف الفتــاة وإمنــا ركبــت معــي‬\n‫لتوصيلهــا مــن مستشــفى ‪ .....‬إلــى منزلهــا ثــم طلبــت منــي مــاال فرفضــت‬\n‫إعطاءهــا ‪ ،‬فادعــت أنــي قــد قمــت بخطفهــا هكــذا أجــاب ‪ .‬وعليــه‬\n‫ولطلــب البينــة مــن املدعــي العــام رفعــت اجللســة ‪ .‬ويف جلســة أخــرى‬\n‫حضــر املدعــي العــام واملدعــى عليــه وبســؤال املدعــي العــام عــن البينــة؟‬\n‫أحضــر للشــهادة ‪ .........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫(‪ ).............‬والــذي يعمــل يف الدوريــات األمنيــة يف ‪ ، ....‬وبســؤاله عمــا‬\n‫لديــه مــن شــهادة ؟ قــال ‪ :‬أشــهد هلل تعالــى بأنــه أثنــاء تعقيــب الدوريــة‬\n‫بحــي ‪ ...‬علــى طريــق الشــاحنات الحظنــا وجــود مواطنــن يفيــدون أن‬\n‫صاحــب ‪ ....‬لوحــة رقــم (‪ ).......‬قــام بصــدم عــدة ســيارات ودخــل داخــل‬\n‫احلــي ومت البحــث عليــه مــن قبلنــا ووجدنــا فتــاة تســتنجد وهــي كاشــفة‬\n‫عــن وجههــا وتقــول أنهــا كانــت مــع صاحــب ‪ ...‬ال تعــرف اســمه لكــي‬\n‫يوصلهــا مشــوار وطلــب منهــا جوالهــا لكــي يتصــل لكونــه ليــس لديــه‬\n‫رصيــد وقــام بقفــل اجلــوال وعنــد محاولــة أخذهــا للجــوال قــام بســحب‬\n‫غطــاء وجههــا وعنــد تغييــر مســار الطريــق قامــت بالركــوب لألمــام‬\n‫ولــف دركســون الســيارة وصــدم الســائق بســيارات كانــت واقفــة حتــى‬\n‫تســتنجد باملواطنــن ثــم صــدم صبــة داخــل احلــي ووقفــت الســيارة وقــام‬\n‫بتنزيلهــا مــن الســيارة وقــام بضربهــا وســبها هــذا مــا قالتــه لنــا الفتــاة ‪،‬‬\n‫وقــد بحثنــا عــن صاحــب الســيارة ‪ ....‬ولــم جندهــا وســلمنا الفتــاة قســم‬\n‫شــرطة ‪ .....‬هــذا مــا شــهد بــه ‪ ،‬وبســؤال املدعــي العــام هــل لديــك مزيــد‬\n‫بينــة ؟ قــال ‪ :‬نعــم ‪ ،‬وأطلــب مهلــة إلحضارهــا فأجيــب لطلبــه ورفعــت‬\n‫اجللســة لذلــك ‪.‬ويف جلســة أخــرى حضــر املدعــي العــام واملدعــى عليــه‬\n\n\n                                                                                        ‫‪256‬‬\n\f      ‫وبســؤال املدعــي العــام عــن البينــة؟ قــال‪ :‬لــم حتضــر وأطلــب مهلــة أخــرى‬\n      ‫فأجيــب لطلبــه وأفهــم بأنهــا املهلــة األخيــرة لذلــك ورفعــت اجللســة لذلــك ‪.‬‬\n      ‫ويف جلســة أخــرى حضــر املدعــي العــام واملدعــى عليــه وجــرى عــرض مــا‬\n      ‫جــاء يف الشــهادة املدونــة يف اجللســة قبــل الســابقة عليــه فقــال ‪ :‬مــا جــاء‬\n      ‫يف الشــهادة بعضــه صحيــح والبعــض اآلخــر غيــر صحيــح ‪ ،‬فمــا جــاء‬\n      ‫يف الشــهادة مــن أنــي صدمــت عــدة ســيارات فغيــر صحيــح فلــم أصــدم‬\n      ‫ســوى ســيارة واحــدة نــوع (‪ ).....‬بعــد أن قامــت الفتــاة بلــف مقــود الســيارة‬\n      ‫‪ ،‬ومــا ذكــره عــن الفتــاة مــن أنــي ســحبت غطــاء وجههــا ثــم تنزيلهــا‬\n      ‫وضربهــا وســبها فغيــر صحيــح هكــذا قــال ‪ ،‬وعليــه إلفهــام املدعــي‬\n      ‫العــام بإحضــار مزكــن لشــاهده املذكــور رفعــت اجللســة ‪ .‬ويف جلســة‬\n      ‫أخــرى حضــر املدعــي العــام واملدعــى عليــه ‪ ،‬وبســؤال املدعــي العــام عــن‬\n      ‫تزكيــة الشــاهد ؟ قــال‪ :‬لــم أمتكــن مــن إحضــار مزكــن وأطلــب مهلــة‬\n      ‫لذلــك فأجيــب لطلبــه ‪ .‬ويف جلســة أخــرى حضــر املدعــي العــام واملدعــى‬\n      ‫عليــه وبســؤال املدعــي العــام عــن تزكيــة الشــاهد؟ قــال لــم أمتكــن‬\n      ‫مــن إحضــار مزكــن وأطلــب مهلــة أخــرى إلحضارهــم فأجيــب لطلبــه‬\n      ‫وأفهــم بأنهــا املهلــة األخيــرة لذلــك ‪ .‬ويف جلســة أخــرى حضــر املدعــي‬\n      ‫العــام واملدعــى عليــه ‪ ،‬وجــرى ســؤال املدعــي العــام عــن تزكيــة شــاهده‬\n      ‫ـزك لــه ‪ ،‬هكــذا قــال ‪ ،‬وعليــه فقــد‬  ‫؟ فقــال لــم نتمكــن مــن إحضــار مـ ٍ‬\n      ‫اعتبرتــه عاجــز ًا عــن ذلــك ‪ ،‬ثــم جــرى الرجــوع للمعاملــة واالطــاع علــى‬\n                                                     ‫أدلــة املدعــي العــام فتبــن أنهــا‪:‬‬\n      ‫‪ /1‬مــا جــاء يف أقــوال املتهــم علــى ص ‪ 1‬مــن لفــة ‪ 18‬وبالرجــوع إليهــا‬\n      ‫تبــن إقــرار املدعــى عليــه بــإركاب املــرأة معــه يف الســيارة لوحدهــا بــا‬\n      ‫ا وإنــكاره محاولــة خطفهــا ‪،‬‬       ‫محــرم الســاعة التاســعة والنصــف لي ـ ً‬\n      ‫ودعــواه أنهــا هددتــه إن لــم يعطهــا مــا ًال فســوف تقــوم بالصــراخ وتدعــي‬\n‫‪257‬‬\n\f                                                              ‫عليــه أنــه خطفهــا ‪.‬‬\n‫‪ /2‬مــا جــاء يف محضــر القبــض لفــه (‪ )8‬وفيــه أنــه عنــد قيــام الدوريــة‬\n‫بجولــة داخــل احلــي وجــد فتــاة تســتنجد وكانــت كاشــفة عــن وجههــا‬\n‫وعنــد ســؤالها أفــادت إنهــا كانــت مــع صاحــب ســيارة ‪ .........‬الــذي قــام‬\n‫بصــدم العربــات وكان يحــاول اختطافهــا وقــام بأخــذ جوالهــا وإقفالــه‪.‬‬\n‫‪ /3‬شــهادة الشــاهد املدونــة علــى ص ‪ 4‬لفــه ‪ 2‬وفيهــا بأنــه أثنــاء ذهابــه‬\n‫إلــى منزلــه شــاهد ســيارة مــن نــوع (‪ )...‬أبيــض قــام بالوقــوف خلــف‬\n‫طبلــون الكهربــاء وســمع أصــوات غيــر مفهومــة وبعــد ذلــك فتــح صاحــب‬\n‫الســيارة البــاب وقــام بــركل فتــاة مــن الســيارة وطرحهــا علــى األرض‬\n‫وقــال لهــا ‪( :‬اهلل يلعنــك) وهــرب أ‪ .‬ه ـ وبعــرض مــا جــاء يف الشــهادة‬\n‫أعــاه علــى املدعــى عليــه قــال‪ :‬مــا جــاء يف الشــهادة غيــر صحيــح‪،‬‬\n‫والصحيــح مــا ذكرتــه هكــذا قــال‪ .‬كمــا جــرى االطــاع علــى أقــوال‬\n‫الفتــاة املدونــة علــى ص ‪ 3‬لفــة ‪ 18‬وفيهــا‪( :‬قمــت باالتصــال عليــه يف‬\n‫ا فحضــر وقمــت بالركــوب معــه وطلــب‬            ‫حــدود الســاعة العاشــرة لي ـ ً‬\n‫منــي جوالــي وبعدهــا شــاهدته يقــوم مبحاولــة إقفــال اجلــوال وطلبــت‬\n‫منــه اســتعادته إال إنــه أخــذ يضحــك بصــوت مرتفــع ثــم قمــت باالتصــال‬\n‫علــى الدوريــات األمنيــة إال إنــه أخــذ جوالــي الثانــي ثــم قــام بإخــراج‬\n‫مســدس وقــال لــي ‪( :‬هــذا مســدس مــو لعبــة) ‪ ،‬حيــث قــام بإخراجــه مــن‬\n‫مــكان لــم أشــاهده ثــم قمــت بضــرب يــده برجلــي ثــم ركبــت باملقعــد‬\n‫األمامــي وقمــت بلــف الطــارة حيــث صدمــت ســيارة كانــت واقفــة ثــم‬\n‫قــام بضربــي وعضنــي بيــدي ثــم قــام بركلــي برجلــه وخرجــت خــارج‬\n‫الســيارة ثــم ذهــب بســيارته )اه ـ ‪ .‬وبعــرض مــا جــاء يف أقــوال املــرأة أعــاه‬\n‫علــى املدعــى عليــه قــال ‪ :‬مــا ذكرتــه مــن اعتدائــي عليهــا أو تهديدهــا‬\n\n\n                                                                                       ‫‪258‬‬\n\f      ‫فغيــر صحيــح هكــذا قــال ‪ ،‬فبنــاء علــى مــا تقــدم وبعــد االطــاع علــى‬\n      ‫دعــوى املدعــي العــام وإجابــة املدعــى عليــه‪ ،‬وبعــد االطــاع علــى املعاملــة‬\n      ‫ونظــر ًا إلقــرار املدعــى عليــه مبــا نســبه إليــه املدعــي العــام مــن إركاب‬\n      ‫فتــاة ال متــت لــه بصلــة شــرعية وصــدم ســيارة كانــت متوقفــة وإنــكاره‬\n      ‫االعتــداء والتلفــظ علــى الفتــاة ‪ ،‬وملــا جــاء يف شــهادة الشــاهد املدونــة يف‬\n      ‫جلســة ســابقة مــن العثــور علــى الفتــاة وهــي تســتنجد وكانــت كاشــفة‬\n      ‫عــن وجههــا ‪ ،‬وملــا جــاء يف شــهادة الشــاهد املدونــة أعــاه مــن مشــاهدته‬\n      ‫لســيارة املدعــى عليــه يف توقفهــا ثــم ســيرها مــرة أخــرى ثــم توقفهــا وقيــام‬\n      ‫املدعــى عليــه بفتــح بــاب الســيارة وركل الفتــاة ثــم طرحهــا علــى األرض‬\n      ‫وقولــه لهــا‪ ( :‬اهلل يلعنــك ) وملــا جــاء يف أقــوال الفتــاة املشــار إليهــا اعــاه ‪،‬‬\n      ‫وألنــه يبعــد علــى املــرأة أن جتــر علــى نفســها األذى يف ســمعتها وعرضهــا‬\n      ‫ا ؛لذلــك كلــه فقــد‬  ‫باتهــام مــن اعتــدى عليهــا إال يف حــال وقــوع ذلــك فعـ ً‬\n      ‫ثبــت لــدي إدانــة املدعــى عليــه بــإركاب فتــاة ال متــت لــه بصلــة شــرعي‬\n      ‫وصــدم ســيارة كانــت متوقفــة بالطريــق وتوجــه التهمــة لــه باالعتــداء‬\n         ‫علــى الفتــاة بالضــرب والــركل والتفلــظ عليهــا بقولــه‪(:‬اهلل يلعنــك )‬\n      ‫وألن مــا قــام بــه املدعــى عليــه فعــل محــرم وســلوك منكــر وفيــه تســاهل‬\n      ‫يف شــأن األعــراض التــي جــاءت الشــريعة اإلســامية بحفظهــا وألن يف‬\n      ‫فعلــه بــإركاب الفتــاة لوحدهــا دون محــرم ويف الليــل قــرب مــن اخلطــوات‬\n      ‫املوصلــة للفاحشــة وقــد قــال اهلل تعالــى‪ ( :‬وال تقربــوا الزنــا إنــه كان‬\n      ‫ال ) ولقوله صلى اهلل عليه وســلم‪ (:‬إياكم والدخول‬                ‫فاحشــة وســاء ســبي ً‬\n      ‫علــى النســاء ) رواه البخــاري ومســلم ولقولــه صلــى اهلل عليــه وســلم ‪« :‬‬\n      ‫ال يخلــون رجــلٌ بامــرأة إال كان الشــيطان ثالثهمــا » رواه الترمــذي ‪ .‬لــذا‬\n                           ‫فقــد قــررت تعزيــر املدعــى عليــه للحــق العــام مبــا يلــي ‪:‬‬\n\n\n‫‪259‬‬\n\f‫‪ /1‬ســجنه ملــدة خمســة أشــهر يحتســب منهــا مــا أمضــاه مــن توقيــف‬\n                                                         ‫بســبب هــذه القضيــة ‪.‬‬\n‫‪ /2‬جلــده مئتــن وخمســن جلــدة مفرقــة على دفعات كل دفعة خمســون‬\n                  ‫جلــدة وبــن كل دفعــة وأخــرى مــا ال يقــل عــن عشــرة أيام ‪.‬‬\n‫‪/3‬منعــه مــن مباشــرة أي عمــل لــه ارتبــاط بالنســاء األجنبيــات عنــه ‪.‬‬\n‫هــذا مــا ظهــر لــي وبــه حكمــت وبعــرض احلكــم علــى املدعــي العــام‬\n‫قــرر اعتراضــه بــدون الئحــة اعتراضيــة ‪ ،‬وبعرضــه علــى املدعــى عليــه‬\n‫قــرر اعتراضــه وطلــب تســليمه نســخة مــن احلكــم لتقــدمي اعتراضــه‬\n‫عليــه فأفهــم باملراجعــة يــوم الثالثــاء ‪1434/6/13‬ه ـ الســتالم نســخة‬\n‫احلكــم وجــرى إفهامــه بتعليمــات االســتئناف يف ضبطــه وبــاهلل التوفيــق‬\n      ‫‪ ،‬وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف ‪1434/6/11‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد‬\n‫فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة اخلامســة مبحكمــة‬\n‫االســتئناف يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بينبــع املســاعد برقــم‬\n‫‪ 332274610‬وتاريــخ ‪1434/7/19‬ه ـ املرفــق بهــا القــرار رقــم‬\n‫‪ 34239665‬وتاريخ‪1434/6/13‬ه ـ الصــادر مــن فضيلــة الشــيخ ‪.....‬‬\n‫القاضــي باحملكمــة العامــة بينبــع املتضمــن دعــوى املدعــي العــام ضــد‬\n‫‪ .....‬ســعودي اجلنســية املتهــم بــإركاب فتــاة ال متــت لــه بصلــه شــرعية‬\n‫والتلفــظ عليهــا‪ ،‬احملكــوم فيــه مبــا دون بباطنــه ‪ ،‬وبدراســة القــرار‬\n‫وصــورة ضبطــه والئحتــه االعتراضيــة قررنــا املوافقــة علــى احلكــم ‪،‬‬\n‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n                                                                                    ‫‪260‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":253,"source_page_end":260,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7b58e3642fcf09130448d46bb4c7f02af295143f78571ffe1db355e56c888132","normalized_text_hash":"678728fcbf3b395d8e75444153235dde3f4202bd9524e725491c91c6bcde734b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p253-34239665"},{"id":"175c2ad3-e2b1-5f76-8633-eac5ce1dcab5","document_type":"judgment","category":"judicial","subcategory":"general","title":"خطف -الشروع يف خطف فتاة -عدم ثبوت البينة -عدم ثبوت","document_number":"34206620","case_number":"34197926","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/05/06","year":"1434","subject":"خطف -الشروع يف خطف فتاة -عدم ثبوت البينة -عدم ثبوت","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34206620 :‬تاريخه‪1434/05/06 :‬هـ‬\n                         ‫رقم الدعوى‪34197926 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34246663‬تاريخه‪1434/6/20 :‬هـ‬\n\n\n       ‫خطــف ‪ -‬الشــروع يف خطــف فتــاة ‪ -‬عــدم ثبــوت البينــة ‪ -‬عــدم ثبــوت‬\n                                                                                 ‫إدانــة ‪.‬‬\n\n\n\n\n       ‫قــول النبــي صلــى اهلل عليــه وســلم ( لــو يعطــى النــاس بدعواهــم الدعــى‬\n                                                    ‫رجــال دمــاء قــوم وأموالهــم )‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــي العــام علــى املدعــى عليــه بقيامــه باالشــتراك يف محاولــة‬\n       ‫خطــف فتــاة بالقــوة ويطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة‬\n       ‫تعزيريــة رادعــة ‪ -‬حيــث إنــه مت القبــض علــى املدعــى عليــه إثــر ورود بــاغ‬\n       ‫عــن وجــود حالــة بحــي ‪ ...‬وبالوصــول للموقــع وجــدت (املجنــي عليهــا)‬\n       ‫وتدعــي بــأن املدعــى عليــه قــام باالشــتراك مــع شــخص آخــر مبحاولــة‬\n       ‫خطفهــا بالقــوة‪ ،‬أنكــر املدعــى عليــه مبــا جــاء يف الدعــوى ‪ -‬عــدم‬\n                                                           ‫وجــود بينــة للمدعــي العــام‪.‬‬\n       ‫فبنــاء علــى مــا تقــدم حكمــت احملكمــة بإخــاء ســبيل املدعــى عليهــم‬\n       ‫وصــرف النظــر عــن الدعــوى‪ ،‬قــرر املدعــي العــام االعتــراض وطلــب‬\n       ‫االســتئناف بالئحــة وقــرر املدعــى عليــه القناعــة‪ .‬صــدق احلكــم مــن‬\n                                                                 ‫محكمــة االســتئناف‪.‬‬\n‫‪261‬‬\n\f‫احلمد هلل وحده وبعد فلدي أنا ‪ ....‬القاضي يف احملكمة اجلزائية مبكة‬\n‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة مبكــة املكرمــة برقــم ‪ 34197926‬وتاريــخ ‪1434/04/29‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 341054864‬وتاريــخ ‪1434/04/29‬ه ـ ففــي‬\n‫يــوم األربعــاء املوافــق ‪1434/05/01‬ه ـ افتتحت اجللســة الســاعة ‪10 : 15‬‬\n‫وفيهــا حضــر املدعــي العــام ‪ ....‬مبوجــب خطــاب التكليــف مــن مرجعــه‬\n‫رقــم ‪ 337‬يف ‪1434/01/24‬ه ـ وادعــى علــى احلاضــر معــه باملجلــس‬\n‫ا بدعــواه حيــث أنــه‬  ‫الشــرعي ‪ ....‬مينــي اجلنســية باإلقامــة رقــم ‪ ....‬قائ ـ ً‬\n‫بتاريــخ ‪1434/05/21‬ه ـ مت القبــض علــى املدعــى عليــه أثــر ورود بــاغ‬\n           ‫عــن وجــود حالــة بحــي ‪ ......‬وبالوصــول للموقــع يف متــام الســاعة‬\n‫(‪ 05 : 58‬صباحــا) وجــدت (املجنــي عليهــا) وتدعــى (‪ )...‬تفيــد بأنهــا‬\n‫حضــرت إلــى احلــرم ألداء العمــرة حيــث قــام أخوهــا بإيصالهــا للحــرم‬\n‫وبعــد أن انتهــت مــن أداء العمــرة بعــد صــاة الفجــر مباشــرة ركبــت‬\n‫ســيارة وذلــك إليصالهــا مشــوار حلــي الكعكيــة لشــراء رأس مــن الغنــم‬\n‫مــن حلقــة الكعكيــة ويف أثنــاء الطريق طلب منها قائد الســيارة األجرة‬\n‫مبلــغ وقــدره (‪ )20‬ريــا ًال فقامــت بإعطائــه مبلــغ (‪ )100‬ريــال لكــي يأخذ‬\n‫قيمــة املشــوار ويــرد لهــا الباقــي فتوقــف قائــد الســيارة أمــام بقالــة تدعــى‬\n‫‪ .....‬ثــم خــرج هــو وصاحــب البقالــة املدعــى عليــه وتــرك البقالــة مفتوحــة‬\n‫ثــم قــام املدعــى عليــه بفتــح بــاب غرفــة تقــع بجــوار البقالــة وقــال (دخلهــا‬\n‫هنــا) بينمــا حضــر إليهــا صاحــب الســيارة وســحبها بالقــوة مــن جهــة‬\n‫كتفهــا األيســر ممــا أدى إلــى شــق عباءتهــا وذلــك لكــي يدخلهــا الغرفــة‬\n\n                                                                                         ‫‪262‬‬\n\f      ‫فرفضــت وصرخــت وعندهــا هــرب قائــد الســيارة ولــم يــرد لهــا باقــي‬\n      ‫املبلــغ فقامــت باالتصــال علــى الدوريــات األمنيــة وعنــد حضــور الدوريــة‬\n      ‫أرشــدت رجــال األمــن إلــى منــزل املدعــى عليــه وذكــرت بأنــه قــام بفتــح‬\n      ‫بــاب الغرفــة الواقعــة بجــوار البقالــة وكان ينتظــر عنــد البــاب حتــى‬\n      ‫يتمكــن قائــد الســيارة مــن إدخالهــا للغرفــة وأفــادت بأنهــا لــم تتعــرض‬\n      ‫ألي إصابــة ســوى أن مالبســها تعرضــت للتلــف وبســؤالها عــن قائــد‬\n      ‫الســيارة أفــادت بأنــه شــخص مــن اجلنســية اليمنيــة عمــره حوالــي (‪)30‬‬\n      ‫عامـ ًا طويــل القامــة نحيــف اجلســم لــه شــارب وذقــن خفيفــان كان يلبــس‬\n      ‫بنطــال جنــز أبيــض اللــون وقميــص أســود اللــون وأفــادت بــأن الســيارة‬\n      ‫صغيــرة احلجــم ال تعــرف نوعهــا أو رقــم لوحاتهــا بيضــاء اللــون مقاعدهــا‬\n      ‫رصاصيــة اللــون (فصلــت لــه أوراق مســتقلة) ومبعاينــة مالبــس املجنــي‬\n      ‫عليهــا اتضــح متــزق عباءتهــا مــن جانــب كتفهــا األيســر حيــث تبــن وجــود‬\n      ‫قطــع كبيــر جــد ًا وبعــرض املدعــى عليــه علــى الفتــاة تعرفــت عليــه وقــد‬\n      ‫انتهــى التحقيــق إلــى توجيــه االتهــام إليــه باالشــتراك يف محاولــة خطــف‬\n      ‫فتــاة بالقــوة وذلــك لألدلــة والقرائــن املوضحــة بالدعــوى وحيــث إن مــا‬\n      ‫قــام بــه املدعــى عليــه فعــل محــرم ومعاقــب عليــه شــرعا أطلــب إثبــات مــا‬\n      ‫أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة رادعــة علمـ ًا بــأن احلــق اخلــاص‬\n      ‫ال زال قائمـ ًا هــذه دعــواي وبســؤال املدعــى عليــه قــال مــا ذكــره املدعــي‬\n      ‫العــام غيــر صحيــح وال أعــرف املــرأة املذكــورة وال صاحــب الســيارة‬\n      ‫املزعومــة وال أعــرف عــن هــذه القضيــة ســوى أننــي ابتليــت بهــذه التهمــة‬\n      ‫الباطلــة جملــة وتفصيــا هــذه إجابتــي وقــال املدعــي العــام الصحيــح مــا‬\n      ‫ذكــرت وبطلــب البينــة قــال بينتــي مــا جــاء يف أوراق املعاملــة وبدراســة‬\n      ‫القضيــة وقــراءة املعاملــة ومحاضــر التحقيــق واألدلــة لــم أجــد فيهــا مــا‬\n\n\n‫‪263‬‬\n\f‫يديــن املدعــى عليــه ســوى شــكوى املجنــي عليهــا وتعرفهــا علــى املدعــى‬\n‫عليــه ومبواجهتــه أصــر علــى إنــكاره فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n‫واإلجابــة وإلــى إنــكار املدعــى عليــه لدعــوى املدعــي العــام وعــدم وجــود‬\n‫البينــة املوصلــة ســوى دعــوى املشــتكية ‪ ،‬ولقــول النبــي صلــى اهلل‬\n‫عليــه وســلم ‪ ( :‬لــو يعطــى النــاس بدعواهــم الدعــى رجــال دمــاء قــوم‬\n‫وأموالهــم ) لــذا فقــد حكمــت بعــدم ثبــوت دعــوى املدعــي العــام وأخليــت‬\n‫ســبيل املدعــى عليــه مــن هــذه الدعــوى وقنــع املدعــى عليــه وقــد عــارض‬\n‫املدعــي العــام وطلــب االســتئناف بالئحــة فأجيــب لطلبــه وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n‫‪1434/05/01‬ه ـ ثــم عــادت املعاملــة مــن محكمــة االســتئناف وبرفقهــا‬\n‫القــرار رقــم ‪ 34246663‬وتاريــخ ‪1434/06/20‬ه ـ املتضمــن املوافقــة‬\n‫والتصديــق علــى احلكــم قاضــي اســتئناف ‪ ....‬قاضــي اســتئناف ‪.....‬‬\n‫قاضــي اســتئناف ‪ ....‬لــذا جــرى إحلاقــه وإثباتــه وبــاهلل التوفيــق حــرر يف‬\n                                                              ‫‪1434/07/10‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                   ‫‪264‬‬\n\f265\n\f266\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":261,"source_page_end":266,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ec765bfebaf6af347c2233143af912401db0a332dc22cda4477d525ca13b02f8","normalized_text_hash":"90c3004390543f3282ca9facda9db531237f00b2f918112f905c92ddbd2a0021","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p261-34206620"},{"id":"c91ca4d6-c095-5d8c-9d9c-7f2e28903950","document_type":"judgment","category":"judicial","subcategory":"general","title":"سحر -حيازة طالسم سحرية -متائم بها شيء من القرآن -كون املدعى عليه كفيف وأجنبي ويغلب عليه اجلهل يف األمور العقدية -ظرف مخفف للعقوبة -تعزير بأخذ التعهد عليه.","document_number":"34229340","case_number":"3350512","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/06/04","year":"1434","subject":"سحر -حيازة طالسم سحرية -متائم بها شيء من القرآن -كون املدعى عليه كفيف وأجنبي ويغلب عليه اجلهل يف األمور العقدية -ظرف مخفف للعقوبة -تعزير بأخذ التعهد عليه.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34229340:‬تاريخه‪1434/06/04 :‬هـ‬\n           ‫رقم الدعوى‪ 3350512 :‬رقم قرار التصديق‬\n                ‫من محكمة االستئناف‪34266244:‬‬\n                           ‫تاريخه‪1434/07/11:‬هـ‬\n\n\n       ‫ســحر ‪ -‬حيــازة طالســم ســحرية ‪ -‬متائــم بهــا شــيء مــن القــرآن ‪ -‬كــون‬\n       ‫املدعــى عليــه كفيــف وأجنبــي ويغلــب عليــه اجلهــل يف األمــور العقديــة‬\n                         ‫‪ -‬ظــرف مخفــف للعقوبــة‪ -‬تعزيــر بأخــذ التعهــد عليــه‪.‬‬\n\n\n\n\n       ‫‪ -1‬قولــه صلــى اهلل عليــه وســلم (إن الرقــى والتمائــم والتولــة شــرك)‪.‬‬\n       ‫رواه أحمــد وأبــو داود واحلاكــم وصححــه ووافقــه الذهبــي واأللبانــي‪.‬‬\n       ‫‪ -2‬الراجــح مــن قــول أهــل العلــم أن التمائــم التــي ال تشــتمل علــى شــيء‬\n                    ‫مــن القــرآن وأســماء اهلل عــز وجــل وصفاتــه محرمــة مطلقـ ًا‬\n\n\n\n\n       ‫ادعــى املدعــي العــام علــى املدعــى عليــه بحيــازة عــدد مــن األوراق حتتــوي‬\n       ‫علــى طالســم ســحرية ومتيمتــن بهمــا طالســم ســحرية‪ ،‬وذلــك بعــد مــا‬\n       ‫مت القبــض عليــه مــن قبــل اجلهــات املختصــة ومعــه أوراق حتتــوي علــى‬\n       ‫أعمــال كفريــة وشــركية محرمــة كتبــت بخــط اليــد‪ ،‬ومتيمتــن بهمــا‬\n       ‫طالســم ســحرية ‪،‬وطلــب املدعــي العــام احلكــم عليــه بعقوبــة تعزيريــة‪،‬‬\n       ‫‪،‬وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه بواســطة املترجــم‬\n       ‫أنكرهــا ودفــع بــأن حيازتــه ملــا ذكــر يف دعــواه ألجــل أن يكــون هنــاك‬\n       ‫محبــة بينــه وبــن زميلــه يف العمــل وال يــدري مــا يف هــذه األوراق وال‬\n\n‫‪267‬‬\n\f‫يعلــم إن كان القصــد منهــا ســحر وشــعوذة ‪،‬وباالطــاع علــى األوراق‬\n‫وجــد أنهــا حتتــوي علــى آيــات قرآنيــة وليســت طالســم‪،‬ولكون املدعــى‬\n‫عامــي وأجنبــي ويغلــب عليــه اجلهــل يف األمــور العقديــة لــذا فقــد مت‬\n                                                                        ‫عليــه ّ‬\n‫احلكــم بأخــذ التعهــد الشــديد عليــه بعــدم تكــرار مــا بــدر منــه وإفهامــه‬\n‫بــأن يعلــق أمــره كلــه هلل‪ ،‬ويفــوض أمــره إليــه‪ ،‬فهــو النافــع الضــار وهــو‬\n‫الــذي يجلــب الــرزق واخليــر وليــس التمائــم وتعليقهــا فهــي ال تنفعــه وال‬\n‫تضــره‪ ،‬وال تغنــي عنــه شــيئاً‪ ،‬فمــن تــوكل علــى اهلل كفــاه‪ ،‬وقــرب إليــه‬\n‫كل بعيــد‪ -‬ويســر لــه كل عســير ‪،‬وبعــرض احلكــم علــى املدعــى عليــه‬\n‫قــرر القناعــة بــه كمــا قــرر املدعــي العــام املعارضــة عليــه واكتفــى مبــا‬\n‫جــاء يف الئحــة الدعــوى عــن تقــدمي الئحــة اعتراضيــة‪ ،‬وبعــد رفــع احلكــم‬\n                                  ‫حملكمــة االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد ويف يــوم األحــد املوافــق ‪1433 /10 /29‬ه ـ وبنــاء‬\n‫علــى املعاملــه املقيــده بهــذه احملكمــة برقــم ‪ 33130963‬يف ‪/19‬‬\n‫‪1433 /01‬ه ـ واحملالــة لنــا مــن رئيــس احملكمــة برقــم ‪ 3350512‬يف‬\n‫‪1433 /01 /19‬ه ـ افتتحــت اجللســه الســاعة احلاديــة عشــر صباحــا يف‬\n‫هــذه القضيــه رقــم ( ‪ ) 3338800003‬وفيهــا حضــر املدعــي العــام ‪/‬‬\n‫‪...‬وادعــى علــى املدعــو‪... /‬البالــغ مــن العمــر ( ‪ ) 28‬عامــا مســلم الديانــه‬\n‫باكســتاني اجلنســية مبوجــب رخصــة االقامــة رقــم ( ‪ )...‬ســائق شــاحنة‬\n‫غيــر محصــن قبــض عليــه بتاريــخ ‪1433 /1 /5‬ه ـ وافــرج عنــه بالكفالــة‬\n‫بتاريخ ‪1433 /1 /5‬هـ يســكن محافظة االحســاء ‪ /‬الهفوف انه بتاريخ‬\n‫‪1433 /1 /5‬ه ـ قبــض عليــه مــن قبــل هيئــة االمــر باملعــروف والنهــي‬\n\n                                                                                     ‫‪268‬‬\n\f      ‫عــن املنكــر املتضمــن انــه باالطــاع علــى محتــوى الظــرف البريــدي‬\n      ‫الــوارد مــن باكســتان املرســل الــى املدعــى عليــه تبــن أنــه عبــارة عــن‬\n      ‫مجموعــة أوراق وذاكــرة جــوال وبالكشــف علــى األوراق تبــن أنهــا‬\n      ‫حتتــوي علــى أعمــال كفريــة وشــركية محرمــة وحتتــوي علــى عــدة‬\n      ‫طالســم ســحري كتبــت بخــط اليــد مبــاء زعفــران مخلــوط بنجاســات‬\n      ‫بهــا رائحــة كريهــة جــدا ‪ ،‬ومتيمتــن بهمــا طالســم ســحرية كإحــراز‬\n      ‫وحجــب تخــص املدعــى عليــه ‪ ،‬وأمــا ذاكــرة اجلــوال حتتــوي علــى اغانــي‬\n      ‫بلغتهــم وبســماع اقــوال املدعــى عليــه أقــر بحيــازة األوراق املضبوطــة معــه‬\n      ‫وأن القصــد منهــا الشــفاء كونــه يعانــي مــن بعــض اآلالم ‪ .‬وقــد أســفر‬\n      ‫التحقيــق عــن توجيــه االتهــام لــه بحيــازة عــدد مــن االوراق حتتــوي علــى‬\n      ‫طالســم ســحرية ومتيمتــن بهمــا طالســم ســحرية وذلــك لألدلــة والقرائــن‬\n      ‫التاليــة ‪ -1 :‬مــا جــاء يف اقــوال املدعــى عليــه املدونــة رقــم ( ‪) 11 -10‬‬\n      ‫مــن ملــف إجــراءات االســتدالل املرفــق علــى اللفــة رقــم ( ‪ -2 ) 1‬محضــر‬\n      ‫املعاينــة املعــد مــن قبــل هيئــة االمــر باملعــروف والنهــي عــن املنكــر املرفــق‬\n      ‫علــى اللفــة رقــم ( ‪ ) 8‬وبالبحــث عمــا إذا كان لــه ســوابق لــم يعثــر لــه‬\n      ‫علــى ســوابق علــى املســتوى احمللــي وحيــث ان مــا اقــدم عليــه املذكــور‬\n      ‫وهــو بكامــل اهليتــه املعتبــرة شــرعا فعــل محــرم ومعاقــب عليــه شــرعا‬\n      ‫اطلــب اثبــات مــا اســند اليــه واحلكــم عليــه بعقوبــة تعزيرية تزجــره وتردع‬\n      ‫غيــره هــذه دعــواى وبعــرض ذلــك علــى املدعــى عليــه عــن طريــق املترجــم‬\n      ‫املعــروف لدينــا املدعــو ‪... /‬هنــدي اجلنســية مبوجــب اإلقامــة رقــم[ ‪]...‬‬\n      ‫قــال مــا ذكــره املدعــي العــام يف دعــواه مــن حيازتــي اوراق كفريــة‬\n      ‫وشــركية محرمــة وحتتــوي علــى طالســم ســحرية كتبــت بخــط اليــد‬\n      ‫مبــاء زعفــران ومتيمتــن بهــا طالســم ســحرية فغيــر صحيــح والصحيــح‬\n\n\n‫‪269‬‬\n\f‫حيــث انــي كنــت اعمــل يف باكســتان فأخبرنــي زميلــي اســمه ‪...‬وكان‬\n‫يعمــل يف الســعودية كمنــدوب يف شــركة ‪...‬قــال لــي حينمــا تصــل الــى‬\n‫الســعودية ســتعطى راتبــا وقــدره الفــان ومئتــا ريــال فلمــا ذهبــت الــى‬\n‫الســعودية قــام باعطائــى راتبــا فجــن جنونــي فاتصلــت علــى اخــي يف‬\n‫باكســتان فاخبرتــه مبــا حــدث لــي ثــم قــام اخــي بارســال هــذه الطالســم‬\n‫لــي حتــى يكــون هنــاك محبــة بينــي وبــن زميلــي ‪...‬وانــا ال ادري مــا هــو‬\n‫يف هــذه االوراق وال اعلــم ان كان القصــد منهــا ســحر وشــعوذه ام ال‬\n‫هكــذا اجــاب وبتصفــح كامــل اوراق املعاملــة لإلطــاع علــى الطالســم‬\n‫املذكــورة لــم اجــد فيهــا مــا يفيــد عمــا ذكــر يف باطــن تلــك االوراق‬\n‫وعليــه فقــد قــررت رفــع اجللســة إلحضــار تلــك التمائــم لالطــاع عليهــا‬\n‫وحضــور البينــة ويف جلســة أخــرى وبنــاء علــى تعميــدي مــن فضيلــة‬\n‫الشــيخ‪ /‬د‪... .‬رئيــس احملكمــة اجلزائيــة باألحســاء املكلــف مبوجــب‬\n‫خطابــه رقــم (‪ )34/1238435‬يف ‪1434/5/21‬ه ـ لنظــر القضايــا مــا‬\n‫عــدا الســجناء وفيهــا حضــر املدعــي العــام وحضــر حلضــوره املدعــى‬\n‫عليــه كمــا حضــر حلضورهمــا املترجــم وكان قــد جــرت الكتابــة‬\n‫منــا ملركــز شــرطة الرقيقــة مبوجــب خطابنــا رقــم (‪ )3411397‬يف‬\n‫‪1434/1/3‬ه ـ إلحضــار الطالســم وقــد ألفــى اجلــواب مبوجــب خطابهــم‬\n‫رقــم (‪7090/9/21‬س) وبرفقــه ظــرف وبفتحــه وفحــص مــا بداخلــه‬\n‫وجــد خرقــة بداخلهــا خيــط مطاطــي مخــاط عليــه قطعــة صغيــرة علــى‬\n‫شــكل مربــع ومت فحــص مــا بداخلــه وجــد بــه ورقتــان وبتصفحهمــا‬\n‫وقراءتهمــا اتضــح أنهــا آيــات قرآنيــة وليســت طالســم ســحرية وحلاجتــي‬\n‫لدراســة القضيــة لــذا فقــد قــررت رفــع اجللســة ويف جلســة أخــرى حضــر‬\n‫املدعــي العــام وحضــر حلضــوره املدعــى عليــه كمــا حضــر حلضورهمــا‬\n\n\n                                                                                   ‫‪270‬‬\n\f      ‫املترجــم وبدراســة وتأمــل أوراق املعاملــة وضبــط القضيــة فبنــاء علــى مــا‬\n      ‫تقــدم مــن الدعــوى واإلجابــة وحيــث إن احملــوز مــع املدعــى عليــه ليســت‬\n      ‫طالســم ومتائــم ســحرية وإمنــا هــي متيمــة فيهــا ورقتــان مكتــوب فيهمــا‬\n      ‫آيــات قرآنيــة وحيــث إن الراجــح مــن أقــوال أهــل العلــم أن التمائــم التــي‬\n      ‫تشــتمل علــى شــيء مــن القــرآن وأســماء اهلل عــز وجــل وصفاتــه محرمــة‬\n      ‫مطلقــا؛ لعمــوم نهــي النبــي صلــى اهلل عليــه وســلم ‪(( :-‬إن الرقى والتمائم‬\n      ‫والتولــة شــرك))‪ .‬رواه أحمــد وأبــو داود واحلاكــم وصححــه ووافقــه‬\n      ‫الذهبــي واأللبانــي‪ .‬وســد ًا للذريعــة؛ فإنــه يفضــي إلــى تعليــق مــا ليــس‬\n      ‫مباح ـ ًا مــن التمائــم الشــركية والطالســم الســحرية؛ وحتــى ال ميتهــن‬\n      ‫شــيئا مــن القــرآن بحملــه يف مــكان قضــاء احلاجــة والقــاذورات‪ .‬لذلــك‬\n      ‫كلــه فقــد قــررت مــا يلــي‪ :‬أوال‪ :‬لــم يثبــت لــدي حيــازة املدعــى عليــه‬\n      ‫لطالســم ســحرية ومتيمتــن بهــا طالســم ســحرية وصرفــت النظــر مــن‬\n      ‫إثبــات ذلــك ثانيــا‪ :‬ثبــت لــدي حيــازة املدعــى عليــه لتميمــة فيهــا ورقتــان‬\n      ‫مكتوبــا فيهــا آيــات قرآنيــة ونظــرا لكــون املدعــى عليــه عامــي وأجنبــي‬\n      ‫ويغلــب عليــه اجلهــل يف األمــور العقديــة لــذا فقــد قــررت أخــذ التعهــد‬\n      ‫الشــديد عليــه بعــدم تكــرار مــا بــدر منــه وأفهمتــه بــأن يعلــق أمــره كلــه‬\n      ‫هلل؛ ويفــوض أمــره إليــه‪ ،‬فهــو النافــع الضــار وهــو الــذي يجلــب الــرزق‬\n      ‫واخليــر وليــس التمائــم وتعليقهــا فهــي ال تنفعــه وال تضــره‪ ،‬وال تغنــي عنــه‬\n      ‫شــيئاً‪ ،‬فمــن تــوكل علــى اهلل كفــاه‪ ،‬وقــرب إليــه كل بعيــد‪ ،‬ويســر‬\n      ‫لــه كل عســير‪ .‬ففهــم ذلــك ومبــا ســبق كلــه حكمــت وبعرضــه علــى‬\n      ‫املدعــى عليــه بواســطة املترجــم قــرر القناعــة بــه كمــا قــرر املدعــي العام‬\n      ‫املعارضــة عليــه واكتفــى مبــا جــاء يف الئحــة الدعــوى عــن تقــدمي الئحــة‬\n      ‫اعتراضيــة وبذلــك تكــون القضيــة منتهيــة وقــررت بعــث كامــل أوراق‬\n\n\n‫‪271‬‬\n\f‫املعاملــة حملكمــة االســتئناف بالشــرقية لتدقيــق احلكــم حســب املتبــع‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n‫تســليما كثيــرا احلمــد هلل وحــده وبعــد ‪ .........‬املســجل برقــم ‪34229340‬‬\n‫وتاريــخ ‪1434/6/4‬ه ـ اخلــاص بدعــوى املدعــى العــام ضــد‪ ...‬اجلنســية‬\n‫يف قضيــة ســحر وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n‫املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                     ‫وصحبــه وســلم حــرر يف ‪1434/7/8‬ه ـ‬\n\n\n\n\n                                                                                  ‫‪272‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":267,"source_page_end":272,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d81337d0114a98a280ce6fe402a42c298da3b6a67c510224acbf7baed2c9257e","normalized_text_hash":"e1c3c0aa71f26a50fe1c700063ba44337e96b9f63984a8b334225783422fe94b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p267-34229340"},{"id":"15609758-d658-517c-871c-cc7114cf8a52","document_type":"judgment","category":"judicial","subcategory":"general","title":"سحر -الوساطة يف أعمال السحر عن طريق النقل -إنكار -عدم وجود بينة -عدم إدانة -صرف نظر.","document_number":"3430618","case_number":"3417710","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/05","year":"1434","subject":"سحر -الوساطة يف أعمال السحر عن طريق النقل -إنكار -عدم وجود بينة -عدم إدانة -صرف نظر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 3430618:‬تاريخه‪1434/02/05 :‬هـ‬\n           ‫رقم الدعوى‪ 3417710:‬رقم قرار التصديق‬\n               ‫من محكمة االستئناف‪34192651:‬‬\n                           ‫تاريخه‪1434/04/20:‬هـ‬\n\n\n      ‫ســحر‪ -‬الوســاطة يف أعمــال الســحر عــن طريــق النقــل ‪ -‬إنــكار ‪ -‬عــدم‬\n                                       ‫وجــود بينــة ‪ -‬عــدم إدانــة ‪ -‬صــرف نظــر‪.‬‬\n\n\n\n\n                    ‫‪ .1‬األصل براءة ذمة املتهم حتى يدل الدليل على خالفه‪.‬‬\n                     ‫‪ .2‬كل دليل تطرق إليه االحتمال سقط به االستدالل‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام علــى املدعــى عليــه بالتوســط يف أعمــال الســحر‬\n      ‫عــن طريــق النقــل ألكل أمــوال النــاس بالباطــل ‪،‬وطلــب املدعــي العــام‬\n      ‫احلكــم عليــه بعقوبــة تعزيريــة ‪،‬وبعــرض دعــوى املدعــي العــام علــى‬\n      ‫املدعــى عليــه أنكرهــا جملــة وتفصيــا ودفــع أنــه ســائق وطبيعــة عملــه‬\n      ‫التوصيــل ‪،‬ونظــر ًا إلنــكار املدعــى عليــه لدعــوى املدعــي العــام ‪،‬وألن‬\n      ‫األصــل بــراءة ذمــة املتهــم حتــى يــدل الدليــل علــى خالفــه‪ ،‬وبنــاء علــى مــا‬\n      ‫تقــدم حكمــت احملكمــة بصــرف النظــر عــن طلــب املدعــي العــام إيقــاع‬\n      ‫العقوبــة التعزيريــة علــى املدعــى عليــه ‪،‬وبعــرض احلكــم علــى الطرفــن‬\n      ‫قــرر املدعــى عليــه قناعتــه باحلكــم وقــرر املدعــي العــام االعتــراض‬\n      ‫علــى احلكــم بــدون الئحــة اعتراضيــة ‪،‬وبعــد رفــع احلكــم حملكمــة‬\n                                                   ‫االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n‫‪273‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‬\n‫فلــدي أنــا القاضــي باحملكمــة اجلزئيــة بالدمــام ففــي يــوم األربعــاء‬\n‫املوافق‪1434/1/28‬ه ـ افتتحــت اجللســة الســاعة احلاديــة عشــر صباح ـ ًا‬\n‫بنــاء علــى املعاملــة احملالــة إلينــا مــن فضيلــة رئيــس احملكمــة اجلزئيــة‬\n‫بالدمــام برقــم ‪ 3417710‬وتاريخ‪1434/1/7‬ه ـ واملقيــدة بــوارد مكتبنا‬\n‫برقــم‪ 3483224‬وتاريخ‪1434/1/11‬ه ـ واملتعلقــة بدعــوى املدعــي العــام‬\n                                                                         ‫ضــد ‪.../‬‬\n‫وفيهــا حضــر املدعــي العــام ‪ .../‬وادعــى علــى احلاضــر معــه ‪... /‬اجلنســية‬\n‫مبوجــب الرقــم الشــخصي ‪...‬قائــا يف دعــواه إنــه باالطــاع علــى محضــر‬\n‫القبــض املعــد مــن قبــل هيئــة األمــر باملعــروف و النهــي عــن املنكــر تبــن‬\n‫انــه وردت لهــم شــكوى مــن أحــد املواطنــن ضــد أحــد الســحرة يف‬\n‫مملكــة البحريــن يدعــى‪ .......... /‬و أن زوجتــه تضــررت منــه و أن لــه‬\n‫أعــوان و وســطاء يقومــون بإيصــال األعمــال الســحرية إلــى اململكــة‬\n‫العربيــة الســعودية مقابــل مبالــغ ماليــة و قــام املدعــي بتزويــد الهيئــة برقــم‬\n‫الســاحر البحرينــي فتــم تكليــف أحــد املصــادر ( امــرأة ) باالتصــال‬\n‫عليــه و طلبــت منــه أن يعمــل لزوجهــا عطفــا و تســخير ًا لهــا بحيــث ال‬\n‫يــرى يف الوجــود إال هــي و طلبــت أيض ـ ًا عالج ـ ًا ألختهــا لكونهــا تعانــي‬\n‫مــن االنطــواء و العزلــة و طلــب مــن املصــدر اســمها و اســم أمهــا و اســم‬\n‫الــزوج و اســم أمــه و اســم أختهــا و اســم أمهــا و طلــب مبلــغ خمســة آالف‬\n‫ريــال قيمــة العــاج و ثالثــة آالف أتعــاب الوســيط الــذي ســيأتي بــه للدمام‬\n‫و قــال للمصــدر ســيتصل عليــك شــخص لتحديــد االســتالم و التســليم‬\n\n                                                                                         ‫‪274‬‬\n\f      ‫‪ ،‬ثــم ورد اتصــال علــى املصــدر مــن قبــل املدعــى عليــه و مت حتديــد‬\n      ‫اليــوم و املــكان يف مجمــع ‪ ...‬بالدمــام ‪ ،‬و نظــر ًا لضخامــة املبلــغ و خوفـ ًا‬\n      ‫عليــه مــن الضيــاع مت ترقيــم مبلــغ ألــف ريــال و تزويــد املصــدر بــه و يف‬\n      ‫الوقــت احملــدد متــت مشــاهدة املصــدر و هــو يتقابــل مــع املدعــى عليــه‬\n      ‫فقــام بإعطــاء املصــدر ظــرف بــه حجابــن و قــارورة مــاء صحــة غيــر‬\n      ‫مختومــة و قــام املصــدر بتســليمه املبلــغ فتــم القبــض عليــه و علــى مرافــق‬\n      ‫لــه يدعــى ‪(...‬صــدر بحقــه أمــر حفــظ دعــوى ) و بفتــح احلاجبــن لــم‬\n      ‫يتضــح فيهمــا شــئ مــن أعمــال الســحر فقــد كتــب يف األول ( صــار لــم‬\n      ‫يكــن الــى صفيــه ) و الثانــي ( إلــى مــن هــذا مــن هنــا هــو ( و باســتجواب‬\n      ‫املدعــى عليــه أفــاد أنــه يعمــل ســائق ســطحه لنقــل الســيارات و قــدم إلــى‬\n      ‫الســعودية إليصــال ظــرف حيــث اتصــل عليــه شــخص ال يعرفــه و طلــب‬\n      ‫منــه إيصــال أوراق خلالتــه يف الســعودية فوافــق كونــه يحضــر للســعودية‬\n      ‫كثيــر ًا و تقابــل مــع شــخص يف مجمــع البحريــن و أعطــاه ظــرف و معــه‬\n      ‫وقــارورة فســأله عــن الــذي بداخــل الظــرف فقــال أوراق و فتحــه لــه ثــم‬\n      ‫أخــذه و قــال لــه الشــخص إذا عــدت أعطيتــك املبلــغ حيــث اتفقــا علــى‬\n      ‫مبلــغ ‪ 50‬دينــار و أخبــره الشــخص بــأن خالتــه ســوف تســتلم الظــرف ‪،‬‬\n      ‫و عنــد وصولــه للســعودية اتصــل علــى املــرأة و بعــد مقابلتــه لهــا ســلمها‬\n      ‫الظــرف و القــارورة و أعطتــه ظــرف ثــم تفاجــأ بالقبــض عليــه كمــا أفــاد‬\n      ‫بــأن مرافقــه صديــق لــه و كثيــر مــا يكــون معــه و ليــس لــه أي عالقــة‬\n      ‫بــاألوراق و قــد انتهــى التحقيــق إلــى اتهــام املدعــى عليــه بالتوســط يف‬\n                                  ‫أعمــال الســحر ألكل أمــوال النــاس بالباطــل ‪.‬‬\n                                                        ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n      ‫‪ -1‬اعترافــه بأنــه اتصــل عليــه شــخص ال يعرفــه و طلــب منــه إيصــال‬\n\n\n‫‪275‬‬\n\f‫أوراق إلــى الســعودية فوافــق و تقابــل مــع الشــخص و أعطــاه ظــرف و‬\n‫معــه قــارورة و اتفقــا علــى مبلــغ ‪ 50‬دينــار مقابــل إيصالهــا املرفــق علــى‬\n                                                             ‫أللفــه رقــم (‪.)15-11‬‬\n                         ‫‪ -2‬محضر القبض املرفق على اللفه رقم ( ‪.) 5 - 4‬‬\n    ‫‪ -3‬ضعف دفعــه ال سيما ما يتعلق بـمعرفته مبن أعطاه املضبوطات ‪.‬‬\n                        ‫‪ -4‬استالمه للمبلغ املرقم قرينة على صحة االتهام ‪.‬‬\n‫و حيــث إن مــا أقــدم عليــه املدعــى عليــه و هــو بكامــل أهليتــه املعتبــرة‬\n                      ‫شــرع ًا فعــل محــرم و معاقــب عليــه شــرع ًا أطلــب إثبــات‬\n‫إدانتــه مبــا أســند إليــه و احلكــم عليــه بعقوبــة تعزيريــة تزجــره و تــردع‬\n‫غيــره هــذه دعــواي وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه‬\n‫أجــاب بقولــه مــا ذكــره املدعــي العــام مــن اتهامــي بالتوســط يف أعمــال‬\n‫الســحر ألكل أمــوال النــاس بالباطــل فغيــر صحيــح هكــذا أجــاب و‬\n‫ا بأنــي اعمــل ســائق ســطحه وطبيعــة عملــي هــي التوصيــل‬          ‫أضــاف قائـ ً‬\n‫ورقــم جوالــي معلــق للجميــع وذلــك بكتابتــه علــى الســطحة هكــذا‬\n‫ا ال توجــد علــي‬  ‫أضــاف وبســؤال املدعــى عليــه عــن الســوابق أجــاب قائـ ً‬\n‫أي ســابقة كمــا جــرى اطالعــي علــى أوراق املعاملــة كمــا جــرى‬\n‫اطالعــي علــى الئحــة دعــوى املدعــي العــام املتضمنــة عــدم وجــود ســوابق‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ونظــر ًا‬ ‫علــى املدعــى عليــه فبنـ ً‬\n                           ‫ملــا قــرره الطرفــان ومــا مت رصــده وضبطــه أعــاه‬\n                                                    ‫ونظر ًا إلنكار املدعى عليه‬\n‫لدعــوى املدعــي ونظــرا إلــى أن األصــل بــراءة ذمــة املتهــم حتــى يــدل‬\n‫الدليــل علــى خالفــه ونظــرا إلــى أن مــا قــام بــه املدعــى عليــه يتطــرق‬\n‫إليهــا احتمــال أنــه خــدع بذلــك وكل دليــل تطــرق إليــه االحتمــال ســقط‬\n\n\n                                                                                        ‫‪276‬‬\n\f      ‫بــه االســتدالل ونظــرا إلــى أن خلــو ســجل املدعــى عليــه مــن الســوابق‬\n                                                    ‫قرينــة تعضــد أصــل بــراءة الذمــة ‪.‬‬\n      ‫لــذا ولــكل مــا ســبق ‪:‬لــم يثبــت لــدي إدانــة املدعــى عليــه مبــا نســب‬\n      ‫إليــه يف دعــوى املدعــي العــام وبذلــك حكمــت وصرفــت النظــر عــن‬\n      ‫طلــب املدعــي العــام إيقــاع العقوبــة التعزيريــة علــى املدعــى عليــه وبذلــك‬\n      ‫حكمــت وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه قناعتــه‬\n      ‫باحلكــم وقــرر املدعــي العــام االعتــراض علــى احلكــم بــدون الئحــة‬\n      ‫اعتراضيــة ورفعــه حملكمــة االســتئناف مكتفيــا مبــا يف أوراق املعاملــة‬\n      ‫وعليــه فقــد قــررت رفــع املعاملــة كاملــة حملكمــة االســتئناف لتدقيــق‬\n      ‫احلكــم وختمــت يف احلاديــة عشــر والنصــف صباح ـ ًا وعلــى ذلــك جــرى‬\n      ‫التوقيــع وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n                                    ‫وصحبــه وســلم ‪ .‬حــرر يف ‪14 34 /1 /28‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n      ‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبدينــة الدمــام برقــم ‪3483224‬‬\n      ‫وتاريــخ ‪1434/2/30‬ه ـ املقيــدة لــدى احملكمة برقم ‪/34/521850‬ج‪1‬‬\n      ‫وتاريــخ ‪1434/3/1‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n      ‫باحملكمــة الشــيخ ‪...‬املســجل برقــم ‪ 3430618‬وتاريــخ ‪1434/2/5‬ه ـ‬\n      ‫اخلــاص بدعوى‪/‬املدعــي العــام ضد‪.../‬اجلنســية يف قضيــة ســحر وقــد‬\n      ‫تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة‬\n      ‫القراروصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة ععلــى احلكــم‬\n      ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                                  ‫حرريف‪1434/4/20‬ه ـ‬\n\n\n‫‪277‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":273,"source_page_end":277,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0ff08efb6255387b0a1ce32b59b892646377ab0c5a337a84ea53672dfe3aa45e","normalized_text_hash":"d851d8bdaea964a6011dde57e24dce8aff929f8a01edb3d1b0be55296ac1bc07","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p273-3430618"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"6ba608f5-0206-5453-beaa-7d5cbffdc361","document_type":"judgment","category":"judicial","subcategory":"general","title":"حرابة -استخدام ساحي ناري -اعتداء -تعاطي احلشيش املخدر -تعاطي احلبوب احملظورة «الكبتاجون» -إقرار املدعى عليه - وجود سوابق قضائية -قيادة السيارة حتت تأثير املسكر -إقامة حد احلرابة واقتراح عقوبة النفي بالسجن عشرين سنة -إقامة حد املسكر -تعزير لقاء تعاطي احلبوب احملظورة باجللد .","document_number":"349934","case_number":"33694641","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بحائل /املساعد ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/12","year":"1434","subject":"حرابة -استخدام ساحي ناري -اعتداء -تعاطي احلشيش املخدر -تعاطي احلبوب احملظورة «الكبتاجون» -إقرار املدعى عليه - وجود سوابق قضائية -قيادة السيارة حتت تأثير املسكر -إقامة حد احلرابة واقتراح عقوبة النفي بالسجن عشرين سنة -إقامة حد املسكر -تعزير لقاء تعاطي احلبوب احملظورة باجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 349934 :‬تاريخه‪1434/1/12:‬هـ‬\n                  ‫رقم الدعوى‪33694641 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 158139‬تاريخه‪1434/6/13 :‬هـ‬\n\n\n‫حرابــة ‪ -‬اســتخدام ســاحي نــاري ‪ -‬اعتــداء ‪ -‬تعاطــي احلشــيش املخــدر‬\n‫‪ -‬تعاطــي احلبــوب احملظــورة «الكبتاجــون» ‪ -‬إقــرار املدعــى عليــه ‪-‬‬\n‫وجــود ســوابق قضائيــة ‪ -‬قيــادة الســيارة حتــت تأثيــر املســكر ‪ -‬إقامــة‬\n‫حــد احلرابــة واقتــراح عقوبــة النفــي بالســجن عشــرين ســنة ‪ -‬إقامــة‬\n       ‫حــد املســكر ‪ -‬تعزيــر لقــاء تعاطــي احلبــوب احملظــورة باجللــد ‪.‬‬\n\n\n\n\n‫‪ -1‬قــول اهلل تعالــى‪« :‬إمنــا جــزاء الذيــن يحاربــون اهلل ورســوله ويســعون‬\n‫يف األرض فســاد ًا أن يقتلــوا أو يصلبــوا أو تقطــع أيديهــم وأرجلهــم مــن‬\n‫خــاف أو ينفــوا مــن األرض ذلــك لهــم خــزي يف الدنيــا ولهم يف اآلخرة‬\n                                                   ‫عــذاب عظيــم» املائــدة ‪. 33‬‬\n                  ‫‪ -2‬قرار هيئة كبار العلماء رقم ‪85‬يف‪1401/01/11‬هـ ‪.‬‬\n‫‪ -3‬التعميــم الــوارد مــن معالــي رئيــس املجلــس األعلــى للقضــاء برقــم‬\n‫‪/292‬ت يف‪1433/08/28‬ه ـ املتضمــن تعميــم األمــر امللكــي رقــم ‪26834‬‬\n‫تاريــخ ‪1433/05/29‬ه ـ القاضــي بــأن ال يقــل ســجن احملــارب عن عشــرين‬\n                           ‫عامـ ًا وأن يكــون ذلــك قاعــدة عامــة ‪ . . .‬إلــخ‪.‬‬\n\n\n\n\n                                                                                   ‫‪222‬‬\n\f      ‫جــرى توجيــه االتهــام للمدعى عليه بترويع اآلمنني وإخافة الســبيل وذلك‬\n      ‫بإطــاق النــار علــى مجموعــة مــن األشــخاص والتســبب بإصابــة بعضهــم‬\n      ‫وإتــاف ممتلــكات بعضهــم وتنــاول مــادة االمفيتامــن املنبــه واحملظــور‬\n      ‫واحلشــيش املخــدر احملظــور واملجــرم وقيــادة الســيارة حتــت تأثيــر املخــدر‬\n      ‫املجــرم مبوجــب نظــام املــرور وطلــب إثبــات مــا أســند إليــه واحلكــم عليــه‬\n      ‫بحــد احلرابــة الــوارد يف اآليــة الكرميــة حيــث تلقــت اجلهــات األمنيــة‬\n      ‫بالغــا عــن تعــرض شــرطي إلطــاق نــار وإصابتــه لــدى مقــر عملــه بإمــارة‬\n      ‫املركــز ‪ ،‬ويف نفــس اليــوم تلقــت اجلهــات األمنيــة بالغ ـ ًا عــن تعــرض‬\n      ‫مواطــن للمطــاردة وإطــاق النــار‪ ،‬ويف نفــس اليــوم تلقــت اجلهــات األمنيــة‬\n      ‫مــن أحــد املقيمــن بالغــا عــن تعرضــه إلطــاق نــار أدت إلصابتــه وقــد‬\n      ‫أفــاد املجنــي عليهــم بأنهــم ال يعرفــون املدعــى عليــه والدافــع علــى مــا‬\n      ‫قــام بــه ‪ ،‬بعــد البحــث والتحــري عــن صاحــب الســيارة لوحظــت ســيارة‬\n      ‫قريبــة مــن مواصفــات الســيارة املطلوبــة عنــد مفــرق فتــم التوقــف عندهــا‬\n      ‫واتضــح أنهــا بقيــادة املدعــى عليــه فتــم القبــض عليــه وبتفتيــش الســيارة‬\n      ‫وجــد ســاح شــوزن أمريكــي ووجــدت أظــرف فارغــة لطلقــات ســاح‬\n      ‫شــوزن‪ ،‬قــام املجنــي عليهــم بالتعــرف علــى املدعــى عليــه ‪ ،‬أثبــت حتليــل‬\n      ‫دم املدعى عليه احتوائه على مادة االمفيتامني واحلشــيش ‪ ،‬أقر املدعى‬\n      ‫عليــه بالتهمــة وأنــه فعــل ذلــك حتــت تأثيــر الكبتاجــون واحلشــيش حيــث‬\n      ‫أصبــح يهــم بــأن هنــاك أشــياء تطــارده وأن الســوابق التــي عليــه صحيحــة‬\n      ‫وأنــه ال يعــرف الدافــع الــذي حملــه علــى هــذا التصــرف‪ ،‬وبنــاء ًا علــى‬\n      ‫مــا تقــدم مــن الدعــوى وإلقــرار املدعــى عليــه ولوجــود ســوابق عليــه وألن‬\n\n‫‪223‬‬\n\f‫فعلــه يعــد محاربــة هلل ورســوله وســعيا يف األرض فســادا وبعــد االطــاع‬\n‫علــى التعميــم الــوارد مــن معالــي رئيــس املجلــس األعلــى املتضمــن تعميــم‬\n‫األمــر امللكــي القاضــي بــأن ال يقــل ســجن احملــارب عــن عشــرين عامـ ًا‬\n‫وأن يكــون ذلــك قاعــدة عامــة ‪ . . .‬إلــخ وبنــاء ًا علــى مــا ســبق كلــه فقــد‬\n‫قــررت الدائــرة احلكــم مبــا يلــي ‪ :‬أوالً‪ /‬إقامــة حــد احلرابــة علــى املدعــى‬\n‫عليــه وتقتــرح يف ذلــك نفيــه علــى ضــوء التعميــم املشــار إليــه أعــاه‪.‬‬\n‫ثاني ـاً‪ /‬إقامــة حــد املســكر علــى املدعــى عليــه وذلــك بجلــده ثمانــن‬\n‫جلــده دفعــة واحــدة‪ .‬ثالث ـاً‪ /‬ثبــوت إدانــة املدعــى عليــه بتعاطيــه لثــاث‬\n‫حبــات محظــورة وتعزيــره لقــاء تعاطيــه احلبــوب احملظــورة بجلــده ســبعني‬\n‫جلــده دفعــة واحــدة‪ .‬رابعاً‪/‬ثبــوت قيادتــه الســيارة حتــت تأثيــر املســكر‬\n‫وعقابــه يف ذلــك عائــد إلــى ولــي األمــر وصرفــت النظــر عــن بقيــة طلبــات‬\n‫املدعــي العــام وبــكل مــا تقــدم حكمــت‪ ،‬بعــرض احلكــم علــى املدعــى‬\n‫عليــه واملدعــي العــام قــررا عــدم قناعتهمــا باحلكــم ورغبــا رفــع احلكــم‬\n‫حملكمــة االســتئناف لتدقيقــه كاملتبــع مــن غيــر الئحة ‪ ،‬عــادت املعاملة‬\n‫مــن محكمــة االســتئناف مبلحوظــة حيــث طلبــت اإلشــارة ملــدة ســجنه‬\n‫ألن مــا ورد يف التعميــم أشــار للحــد األدنــى ولــم يشــر لألعلــى ‪ ،‬قــررت‬\n‫الدائــرة يف اقتراحهــا بأنهــا تــرى أنــه يســجن عشــرين ســنة ويعامــل بعــد‬\n‫خروجــه وفقــا للتعميــم ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ومــن‬\n                                                                  ‫احملكمــة العليــا‪.‬‬\n\n\n\n\n                                                                                        ‫‪224‬‬\n\f      ‫احلمــد هلل وحــده والصــاة والســام علــى رســوله نبينــا محمــد وبعــد ففــي‬\n      ‫هــذا اليــوم الســبت املوافــق ‪1434/1/3‬ه ـ افتتحــت اجللســة يف متــام‬\n      ‫الســاعة العاشــرة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة بحائــل‪ /‬املســاعد برقــم ‪ 33694641‬يف‬\n      ‫‪1433/12/20‬ه ـ واملقيــدة بهــذه احملكمــة برقــم ‪ 332182066‬يف‬\n      ‫‪1433/12/19‬ه ـ لدينــا نحــن كال مــن ‪................‬و‪...........‬القضــاة‬\n      ‫باحملكمــة العامــة بحائــل وفيهــا حضــر املدعــي العــام واملدعــى عليهــم‬\n      ‫‪...........‬سعودي اجلنسية مبوجب السجل املدني رقم ‪1037979778‬وقرر‬\n      ‫املدعــي العــام دعــواه قائــا بصفتــي مدعيـ ًا عامـ ًا يف دائــرة االدعــاء العــام‬\n      ‫بفــرع الهيئــة مبنطقــة حائــل أدعــي علــى ‪......................:‬البالــغ مــن العمــر‬\n      ‫(‪ )33‬عامـ ًا ‪ ،‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪، )...........‬‬\n      ‫متعلــم ‪ ،‬أعــزب‪ ،‬يقيــم يف مدينــة الريــاض ‪ ،‬أوقــف بتاريخ ‪1433/6/2‬هـ‬\n      ‫وأودع الســجن العــام بحائــل مبوجــب مذكــرة التوقيــف رقــم (‪...........2‬‬\n      ‫وتاريــخ ‪1433/6/7‬ه ـ اســتناد ًا للقــرار الــوزاري (‪ )1900‬وتاريــخ‬\n      ‫‪1428/7/9‬هـ‪.‬فإنــه يف الســاعة الســابعة وأربعــن دقيقــة مــن صبــاح يــوم‬\n      ‫االثنــن ‪1433/6/2‬ه ـ تلقــت اجلهــات األمنيــة مــن املواطــن ‪)55(........... /‬‬\n      ‫عام ـ ًا ســعودي اجلنســية بالغ ـ ًا ذكــر فيــه تعــرض زميلــه املواطــن ‪/‬‬\n      ‫‪ ...........‬إلطــاق نــار وإصابتــه وذلــك عنــد مقــر عملــه بإمــارة قريــة‬\n      ‫‪ ،...........‬ويف متــام الســاعة الثامنــة صباح ـ ًا مــن نفــس اليــوم والتاريــخ‬\n      ‫تلقــت اجلهــات األمنيــة مــن املواطــن ‪........... /‬بالغ ـ ًا ذكــر فيــه تعرضــه‬\n      ‫للمطــاردة وإطــاق النــار مــن قبــل قائــد ســيارة ‪ ،......‬ويف الســاعة الثامنــة‬\n\n‫‪225‬‬\n\f‫والثلــث مــن نفــس اليــوم والتاريــخ تلقــت اجلهــات األمنيــة مــن املقيــم‬\n‫‪ /...........‬باكســتاني اجلنســية بالغ ـ ًا ذكــر فيــه تعرضــه إلطــاق نــار‬\n‫ممــا تســبب بإصابتــه وذلــك علــى طريــق ‪...........‬مــن قائــد ســيارة ‪.....‬‬\n‫وبســماع أقــوال املجنــي عليــه ‪ )34(.........../‬عامـ ًا ســعودي اجلنســية أفــاد‬\n‫أنــه عنــد ذهابــه إلــى عملــه بإمــارة قريــة ‪...........‬وعنــد مــروره بقريــة‬\n‫‪...........‬شــاهد ســيارة ‪ ....‬تفحــط وتطــارد ســيارة ‪ ......‬فتركهــا وتوجــه‬\n‫إلــى عملــه وبعــد ذلــك الحــظ أن الســيارة ‪ .......‬متشــي خلفــه حتــى توقــف‬\n‫عنــد مركــز إمــارة‪ ...........‬وتوقــف قائــد الســيارة ‪ .....‬ونــزل ومعــه ســاح‬\n‫شــوزن وقــال لــه ( أنــت وش تبــي منــي ) فأســرع نحــو البــاب لكــي يدخــل‬\n‫للمركــز فأطلــق عليــه النــار وأصابــه برجلــه اليســرى أســفل الفخــذ‬\n‫وذكــر بأنــه ال يعرفــه ‪ .‬وبســماع إفــادة املجنــي عليــه ‪........... /‬أفــاد أنــه‬\n‫أثنــاء ذهابــه إلــى عملــه بقريــة ‪...........‬شــاهد ســيارة ‪ .......‬قــدمي خــارج مــن‬\n‫طريــق إمــارة ‪...........‬وســلك طريــق قريــة ‪...........‬وبعــد فتــرة شــاهد‪......‬‬\n‫متوقــف علــى ميــن الطريــق واســتمر هــو يف طريقــه وبعــد ذلــك شــاهد ‪.....‬‬\n‫ميشــي خلفــه ويطلــب منــه التوقــف وشــاهده ولــم يعرفــه وكان معه ســاح‬\n‫فهــرب منــه فطــارده صاحــب ‪ ....‬وأطلــق النــار عليــه وكســر زجــاج‬\n‫ســيارته اخللفــي وزجــاج بــاب الراكــب األميــن اخللفــي واســتمر مبطاردتــه‬\n‫فدخــل قريــة ‪...........‬وخــرج منها مســرع ًا وكان صاحب الســيارة يطارده‬\n‫وكانــا يســيران بســرعة جنونيــة وعندمــا أقبــل علــى قريــة ‪...........‬اختفــى‬\n‫عنــه واســتمر هــو بالســير حتــى وصــل إلــى مدينــة ‪...........‬وذكــر بأنــه‬\n‫أطلــق النــار عليــه مرتــن مــن ســاح الشــوزن الــذي كان معــه‪ .‬وبســماع‬\n‫إفــادة املجنــي عليــه املقيــم ‪ )28(........... /‬عام ـ ًا باكســتاني اجلنســية‬\n‫أفــاد أنــه أثنــاء ســيره باجتــاه مدينــة ‪...........‬شــاهد ســيارة ‪ .......‬واقفــة‬\n\n\n                                                                                            ‫‪226‬‬\n\f      ‫علــى يســار الطريــق فلمــا أصبــح بجانبــه أطلــق النــار عليــه وأصابــه بيــده‬\n      ‫اليســرى وال يعــرف الســبب واســتمر بالســير حتــى وصــل إلــى مدينــة‬\n      ‫‪............‬وبعــد البحــث والتحــري عــن صاحــب الســيارة لوحظــت ســيارة‬\n      ‫قريبــة مــن مواصفــات الســيارة املطلوبــة عنــد مفــرق قريــة ‪...........‬فتــم‬\n      ‫التوقــف عندهــا واتضــح أنهــا بقيــادة املتهــم املذكــور أعــاه فتــم القبــض‬\n      ‫عليــه وبتفتيــش ســيارة املتهــم وجــد ســاح مــن نــوع شــوزن أمريكــي‬\n      ‫الصنــع ( ‪ ) ......‬صنــع( ‪ ) ...‬بــدون رقــم داخــل الســيارة باملرتبــة اخللفيــة‬\n      ‫مخبــأة حتــت قطعــة قمــاش وعــدد (‪ )26‬ســت وعشــرون طلقــة حيــة‬\n      ‫ووجــدت أظــرف فارغــة لطلقــات ســاح شــوزن ‪ ،‬وباالنتقــال واملعاينــة‬\n      ‫ملوقــع اجلرميــة األول كان عنــد مركــز إمــارة قريــة ‪...........‬شــوهدت آثــار‬\n      ‫إطــاق نــاري علــى مدخــل املركــز الــذي يفتــح ناحيــة الشــرق كمــا‬\n      ‫شــوهدت آثــار دمــاء داخــل حــوش املركــز وقريــب مــن البــاب ووجــدت‬\n      ‫آثــار دمــاء أمــام وداخــل غرفــة الضيافــة باملركــز ولوحــظ أثــر إلطــارات‬\n      ‫ســيارة نتيجــة اســتخدام املكابــح متوقفــة أمــام البــاب الرئيــس للمركــز‬\n      ‫ولــم يشــاهد أي أظــرف فارغــة باملوقــع وقــد أثبــت التقريــر الفنــي رقــم‬\n      ‫‪ ...........‬الصــادر مــن إدارة األدلــة اجلنائيــة برقــم (‪ )...........‬وتاريــخ‬\n      ‫‪1433/6/14‬ه ـ أن األظــرف التــي مت رفعهــا مــن مســرح اجلرميــة وســيارة‬\n      ‫املتهــم مطلقــة مــن الســاح الشــوزن الــذي عثــر عليــه مــع املتهــم وأقــر‬\n      ‫بحيازتــه لــه كمــا مت معاينــة ســيارة مــن نــوع ‪ .....‬حتمــل اللوحــة رقــم (‬\n      ‫‪ .... )...........‬بقيــادة املجنــي عليــه ‪ ........... /‬اتضــح أنهــا تعرضــت إلطــاق‬\n      ‫نــار مــن اخللــف حيــث كســر الزجــاج اخللفــي و زجــاج الراكــب اخللفــي‬\n      ‫األميــن كمــا شــوهدت آثــار للمقذوفــات يف ســقف الســيارة كمــا مت‬\n      ‫معاينــة ســيارة مــن نــوع ‪ .....‬حتمــل اللوحــة رقــم ( ‪ )...........‬بقيــادة املجنــي‬\n\n\n‫‪227‬‬\n\f‫عليــه املقيــم ‪...........‬اتضــح تعرضهــا إلطــاق نــار مــن جهــة بــاب الســائق‬\n‫ونتــج عنــه حتطــم زجــاج بــاب الســائق وارتطام املقذوفات ببــاب الراكب‬\n‫مــن ا لداخــل وشــوهدت آثــار دمــاء علــى عجلــة القيــادة للســيارة وبــاب‬\n‫الســائق مــن الداخــل وقــد أثبــت قصــاص األثــر بعــد معاينتــه للموقــع‬\n‫الــذي يقــع بــن قريــة ‪...........‬وقريــة ‪...........‬أن اآلثــار تبــن أن هناك ســيارة‬\n‫نزلــت ميــن الطريــق وتوقفــت ثــم عــادت للطريــق مــرة أخــرى وهــذه اآلثــار‬\n‫مطابقــة ألثــار الســيارة مــن نــوع ‪ .....‬حتمــل اللوحــة رقــم ‪ ...........‬اللــون‬\n‫التــي يقودهــا املتهــم ومبعاينــة موقــع احلادثــة عنــد إمــارة قريــة ‪...........‬لــم‬\n‫يعثــر علــى مــا يفيــد التحقيــق ألن املوقــع مســفلت وقــد أثبــت خطــاب‬\n‫مديــر شــعبة األســلحة واملتفجــرات عــدم وجــود أي ســاح مرخــص باســم‬\n‫املتهــم وبعــرض الســيارة مــن نــوع ‪ .......‬حتمــل لوحــة رقــم‪ ...........‬علــى‬\n‫املواطــن ‪ ........... /‬اســتطاع التعــرف عليهــا وأنهــا نفــس الســيارة التــي‬\n‫كانــت تطــارده وقــام قائدهــا بإطــاق النــار عليــه كمــا جــرى عــرض‬\n‫الســيارة املشــار إليهــا علــى املواطــن ‪........... /‬واســتطاع التعــرف عليهــا‬\n‫وأنهــا نفــس الســيارة التــي شــاهدها عنــد قدومــه إلــى إمــارة قريــة ‪...........‬‬\n‫وبعــرض املتهــم مــع مجموعــة أشــخاص مشــابهني لــه علــى املواطــن ‪/‬‬\n‫‪...........‬واملواطــن ‪........... /‬اســتطاعا التعــرف عليــه أنــه هــو مــن كان‬\n‫يقــود الســيارة الكابــرس املشــار إليهــا امللــك بحائــل برقــم ‪)...........‬‬\n‫وتاريــخ ‪1433/6/29‬ه ـ والتقريــر الصــادر مــن مستشــفى امللــك بحائــل‬\n‫برقــم‪ )...........‬وتاريــخ ‪ /6/29‬وقــد تضمــن التقريــر الطبــي النهائــي‬\n‫للمجنــي عليــه ‪...........‬رقــم (‪ )...........‬الصــادر مــن مستشــفى امللــك‬\n‫……… بحائــل برقــم (‪ )......................‬وتاريــخ ‪1433/6/21‬ه ـ ادعــاء‬\n‫املجنــي عليــه إصابتــه بطلــق نــاري هوائــي وكان يعانــي مــن كســر‬\n\n\n                                                                                            ‫‪228‬‬\n\f      ‫متفتــت مفتــوح مــن الدرجــة الثالثــة وقــد مت إجــراء عمليــة جراحيــة‬\n      ‫لتنظيــف اجلــرح مــع تثبيــت الكســر مبســمار نخاعــي وخــرج بتاريــخ‬\n      ‫‪1433/6/8‬ه ـ مــع إعطــاءه موعــد للمتابعــة بالعيــادات اخلارجيــة ومــدة‬\n      ‫الشــفاء ســتة أســابيع مــا لــم حتــدث مضاعفــات ‪.‬كمــا أثبتــت التقاريــر‬\n      ‫الطبيــة للمجنــي عليــه ‪........... /‬رقــم (‪ )...........‬الصــادر مــن مستشــفى‬\n      ‫امللــك ……… بحائــل برقــم (‪...........‬وتاريــخ ‪1433/6/29‬ه ـ ورقــم‬\n      ‫(‪ )...........‬الصــادر مستشــفى ‪1433‬ه ـ املتضمنــة إصابــة بطلــق نــاري‬\n      ‫تســبب بإصابــة الشــريان واألوعيــة واألعصــاب للركبــة اليســرى ومــدة‬\n      ‫الشــفاء من ثالثة أشــهر إلى ســتة أشــهر كما أثبت التقرير الكيميائي‬\n      ‫الشــرعي رقم (‪ )...........‬الصادر من مركز مراقبة الســموم والكيمياء‬\n      ‫الطبيــة مبنطقــة القصيــم برقم‪...........‬وتاريــخ ‪1433/6/29‬ه ـ إيجابيــة‬\n      ‫العينــة املأخــوذة مــن املتهــم ملــادة األمفيتامــن املنبهــة واحملظــورة كمــا‬\n      ‫ثبــت إيجابيــة العينــة للتتراهيدروكانــا بينــول وهــو مــن نــواجت أيــض‬\n      ‫احلشــيش املخــدر وورد التقريــر رقــم ‪...........‬الصــادر مــن األدلــة اجلنائيــة‬\n      ‫‪ ،،،‬املتعلــق بفحــص املســحات التــي مت أخذهــا مــن أيــدي املتهــم‬\n      ‫املذكــور ســلبية العينــة ملخلفــات اإلطــاق النــاري وهــذا ال يعنــي عــدم‬\n      ‫اســتخدام الســاح لعــدة عوامــل مــن ضمنهــا ( نوعيــة الســاح وآليتــه‬\n      ‫العامــل الزمنــي وإزالــة اآلثــار عــن طريــق غســيل األيــدي أو مســحها‬\n      ‫بقصــد أو بــدون قصــد) وبســماع شــهادة الشــاهد ‪)26(...................... /‬‬\n      ‫عام ـ ًا ســعودي اجلنســية أفــاد أن زميلــه املجنــي عليــه ‪...................... /‬‬\n      ‫اتصــل بــه وذكــر لــه تعرضــه إلطــاق نــار مــن قبــل قائــد ســيارة ‪......‬‬\n      ‫فتوجــه لــه علــى طريــق ‪...........‬ويف طريقــه شــاهد الســيارة ‪ .....‬واقفــة‬\n      ‫علــى جانــب الطريــق عنــد قريــة ‪...........‬ونــازل منهــا شــخص معــه ســاح‬\n\n\n‫‪229‬‬\n\f‫ولــم يتوقــف عنــده واســتمر بالســير إلــى مدينــة ‪...........‬ملقابلــة املجنــي‬\n‫عليــه ‪.........../‬كمــا ذكــر بأنــه لــم يشــاهد املتهــم وهــو يطلــق النــار أو‬\n‫يقــوم باملطــاردة وبســماع شــهادة الشــاهد ‪...................... /‬أفــاد أنــه عنــد‬\n‫حضــوره إلــى مقــر عملــه بإمــارة قريــة ‪...........‬وقبــل دخولــه للمركــز‬\n‫قابلتــه ســيارة مــن نــوع ‪ ......‬يقودهــا شــخص مكشــوف الــرأس وبعــد‬\n‫دخولــه للمركــز شــاهد زميلــه املجنــي عليــه ‪...................... /‬مصابـ ًا يف‬\n‫غرفــة الضيافــة وقــام بإســعافه مــع مديــر املركــز وأخبــره بــأن قائــد‬\n‫ســيارة ‪ ......‬هــو مــن أطلــق عليــه النــار وباســتجواب املتهــم أقــر بأنــه خــرج‬\n‫مــن مدينــة الريــاض لوجــود ثــاث ســيارات تطــارده وكان يريــد الذهــاب‬\n‫إلــى قريــة ‪...........‬ألخــذ ســاح شــوزن موجــود يف املنــزل وذلــك أنــه تنــاول‬\n‫حبتــن مــن احلبــوب احملظــورة بعــد خروجــه مــن الريــاض وأصبــح يــرى‬\n‫أشــياء تطــارده ووصــل إلــى القريــة قرابــة الســاعة السادســة صباح ـ ًا‬\n‫وأخــذ الســاح الشــوزن وهــو ســاح يعــود لــه وغيــر مرخــص وكان‬\n‫هنــاك ظــل يطــارده وعندمــا تابعــه كانــت ســيارة ‪ ......‬فخرجــت عــن‬\n‫الطريــق وكان اجلــو غبــار وعندمــا عــادت إلــى الطريــق حتولــت الســيارة‬\n‫إلــى جيــب فلحــق بــه حتــى وصــل إلــى إمــارة ‪...........‬ونــزل منــه شــخص‬\n‫وحــاول الهــرب ولكنــه أطلــق عليــه النــار وســمعه يصــرخ فركــب‬\n‫ســيارته وتوجــه إلــى قريــة ‪...........‬وشــاهد ســيارة ‪ .....‬وأطلــق عليــه النــار‬\n‫وبعدمــا جتــاوز قريــة ‪...........‬توقــف فمــرت مــن أمامــه ســيارة ‪ ....‬فأطلــق‬\n‫النــار عليهــا وأنــه ال يعلــم ســبب قيامــه بهــذه األفعــال كمــا ذكــر بأنــه ال‬\n‫يعــرف األشــخاص الذيــن أطلــق عليهــم النــار وليــس بينــه وبينهــم أي‬\n‫عــداوة وقــد اســفر التحقيــق معــه عــن اتهامــه بترويــع اآلمنــن وإخافــة‬\n‫الســبيل وذلــك بإطــاق النــار علــى مجموعــة مــن األشــخاص والتســبب‬\n\n\n                                                                                          ‫‪230‬‬\n\f      ‫بإصابــة بعضهــم وإتــاف ممتلــكات بعضهــم واملجــرم شــرع ًا واتهامــه‬\n      ‫بتنــاول مــادة االمفيتامــن املنبــه واحملظــور واحلشــيش املخــدر واحملظــور‬\n      ‫واملجــرم مبوجــب الفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة وقيــادة الســيارة حتــت تأثيــر املخــدر املجرم‬\n      ‫مبوجــب نظــام املــرور ‪ ( .‬مت فــرز أوراق مســتقلة ملعاجلــة موضــوع حيــازة‬\n      ‫الســاح والذخيــرة بــدون ترخيــص مــن قبــل احملكمــة املختصــة) وذلــك‬\n      ‫لألدلــة والقرائــن التاليــة‪ -1 :‬اعترافــه املصــدر شــرع ًا املــدون علــى‬\n      ‫الصفحــة رقــم ( ‪ )5.4‬لفــة رقــم(‪ -2 .)1‬مــا جــاء بشــهادة الشــهود املدونــة‬\n      ‫علــى الصفحــة رقــم (‪ )14.13.10‬لفــة رقــم (‪ -3 )5‬مــا جــاء بالتقاريــر‬\n      ‫الطبيــة املشــار إليهــا املرفقــة لفــة رقــم ( ‪ -4 )60.53.47.45.24‬مــا جــاء‬\n      ‫مبحضــر املعاينــة املــدون علــى الصفحــة رقــم (‪ )3.2‬لفــة رقــم(‪ -5 )4‬مــا‬\n      ‫جــاء مبحضــر القبــض والتفتيــش املــدون علــى الصفحــة رقــم (‪ )4‬لفــة‬\n      ‫رقــم (‪ -6 )4‬مــا جــاء باحملضــر املعــد مــن قبــل قصــاص األثــر املــدون علــى‬\n      ‫الصفحــة رقــم (‪ )6‬لفــة رقــم (‪ -7 )5‬مــا جــاء مبحاضــر العــرض للمتهــم‬\n      ‫وســيارته املدونــة علــى الصفحــة رقــم (‪ )16.15‬لفــة رقــم (‪ -8 )5‬مــا جــاء‬\n      ‫بالتقريــر اجلنائــي املصــدر رقــم (‪ )8‬لعــام ‪1433‬ه ـ املرفــق لفــة رقــم (‪)71‬‬\n      ‫‪ -9‬مــا جــاء بالتقريــر الفنــي لألســلحة رقــم (‪ )51‬لعــام ‪1433‬ه ـ املشــار‬\n      ‫إليــه واملرفــق لفــة رقــم (‪ -10 )67‬مــا جــاء بالتقرير الكيميائي الشــرعي‬\n      ‫املشــار إليــه املرفــق لفــه رقــم (‪ )56‬وبالبحــث يف ســجله اجلنائــي تبــن أن‬\n      ‫لــه ســتة ســوابق هــي ‪ :‬اعتــداء ‪ -‬فعــل فاحشــة اللــواط ‪ -‬حيــازة واســتعمال‬\n      ‫مخــدرات ‪ -‬ترويــج املســكرات ‪ -‬حيــازة املخــدرات وحيــث إمنــا أقــدم‬\n      ‫عليــه فعــل محــرم ومعاقــب عليــه شــرع ًا ويعــد ضربـ ًا من ضروب اإلفســاد‬\n      ‫يف األرض وملــا فيــه مــن إخافــة الســبيل وترويــع اآلمنــن وســالكي‬\n\n\n‫‪231‬‬\n\f‫الطريــق ‪ ،،،‬أطلــب إثبــات إدانتــه مبــا أســند إليــه اســتناد ًا للمادتــن‬\n‫(‪ )129.126‬مــن نظــام اإلجــراءات اجلزائيــة واحلكــم عليــه بحــد احلرابــة‬\n‫الــوارد يف اآليــة الكرميــة رقــم (‪ )33‬مــن ســورة املائــدة يف ضــوء قــرار‬\n‫هيئــة كبــار العلمــاء رقــم (‪ )85‬وتاريــخ ‪1401/1/11‬ه ـ ومصــادرة‬\n‫الســيارة املســتخدمة يف اجلرميــة وإثبــات إدانتــه بتعاطــي مادتــي احلشــيش‬\n‫املخــدر واالمفيتامــن املنبــه واحلكــم عليــه مبــا يلــي‪ -1 :‬الســجن ‪-2‬املنــع‬\n‫مــن الســفر وفق ـ ًا للمادتــن (‪ )56.41‬مــن نظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة وإثبــات إدانتــه بقيــادة الســيارة حتــت تأثيــر املخــدر‬\n‫وإفهامــه بــأن عقابــه علــى ذلــك عائــد للجهــة املختصــة ( علمـ ًا بــأن احلــق‬\n‫اخلــاص مــا زال قائم ـ ًا ) هكــذا ادعــى وبــرد ذلــك علــى املدعــى عليــه‬\n‫املتهــم فأجــاب وهــو باألهليــة املعتبــرة شــرعا قائــا ‪ :‬مــا ذكــره املدعــي‬\n‫العــام مــن أنــي أطلقــت النــار علــى التفصيــل الــذي ذكــره وعــدده ثــاث‬\n‫مــرات علــى ثالثــة أشــخاص فهــو صحيــح ولكنــي أطلقــت حتــت تأثيــر‬\n‫مــا تعاطيتــه مــن حبــوب الكبتاجــون وعددهــا حبتــان وســيجارة واحــدة‬\n‫مــن احلشــيش املخــدر والســوابق املذكــورة يف الدعــوى العامــة كلهــا‬\n‫صحيحــة وأنــا أعمــل بشــركة ‪ ...........‬مبدينــة الريــاض هكــذا أجــاب‬\n‫فجــرى الرجــوع إلــى أوراق املعاملــة وجــد بــن طياتهــا بينــات املدعــي‬\n                            ‫العام التي أشار اليها يف الئحته وهي كما يلي‪:‬‬\n‫‪ .1‬اعترافــه املصــدر شــرع ًا املــدون علــى الصفحــة رقــم (‪ )5.4‬لفــة رقــم‬\n                                                                                ‫(‪)1‬‬\n‫‪ .2‬مــا جــاء بشــهادة الشــهود املدونــة علــى الصفحــة رقــم (‪14.13.10‬‬\n                                                                   ‫(لفــة رقــم (‪)5‬‬\n‫‪ .3‬مــا جــاء بالتقاريــر الطبيــة املشــار إليهــا املرفقــة لفــة رقــم‬\n\n\n                                                                                      ‫‪232‬‬\n\f                                                            ‫( ‪)60.53.47.45.24‬‬\n      ‫‪ .4‬مــا جــاء مبحضــر املعاينــة املــدون علــى الصفحــة رقــم (‪ )3.2‬لفــة رقــم‬\n                                                                                     ‫( ‪)4‬‬\n      ‫‪ .5‬مــا جــاء مبحضــر القبــض والتفتيــش املــدون علــى الصفحــة رقــم (‪)4‬‬\n                                                                           ‫لفــة رقــم (‪)4‬‬\n      ‫‪ .6‬مــا جــاء باحملضــر املعــد مــن قبــل قصــاص األثــر املــدون علــى الصفحــة‬\n                                                                  ‫رقــم (‪ )6‬لفــة رقــم(‪)5‬‬\n      ‫‪ .7‬مــا جــاء مبحاضــر العــرض للمتهــم وســيارته املدونــة علــى الصفحــة‬\n                                                          ‫رقــم (‪ )16.15‬لفــة رقــم (‪)5‬‬\n      ‫‪ .8‬مــا جــاء بالتقريــر اجلنائــي املصــدر رقــم (‪ )8‬لعــام ‪1433‬ه ـ املرفــق لفــة‬\n                                                                               ‫رقــم (‪)71‬‬\n      ‫‪ .9‬مــا جــاء بالتقريــر الفنــي لألســلحة رقــم (‪ )51‬لعــام ‪1433‬ه ـ املشــار‬\n                                                          ‫إليــه واملرفــق لفــة رقــم (‪)67‬‬\n      ‫‪ .10‬مــا جــاء بالتقريــر الكيميائــي الشــرعي املشــار إليــه املرفــق لفــه رقــم‬\n                                                                                    ‫(‪)56‬‬\n      ‫باالطــاع عليهــا وجدناهــا تتضمــن مــا أشــار اليهــا املدعــي العــام بالئحته‬\n      ‫ومنهــا اعتــراف املدعــى عليــه املصــدق شــرعا املــدون لفــه (‪ )1‬ص ‪5-4‬‬\n      ‫املتضمــن باســتجواب املتهــم أقــر بأنــه خــرج مــن مدينــة الريــاض لوجــود‬\n      ‫ثــاث ســيارات تطــارده وكان يريــد الذهــاب إلــى قريــة ‪...........‬ألخــذ‬\n      ‫ســاح شــوزن موجــود يف املنــزل وذلــك أنــه تنــاول حبتــن مــن احلبــوب‬\n      ‫احملظــورة بعــد خروجــه مــن الريــاض وأصبــح يــرى أشــياء تطــارده ووصــل‬\n      ‫إلى القرية قرابة الســاعة السادســة صباح ًا وأخذ الســاح الشــوزن وهو‬\n      ‫ســاح يعــود لــه وغيــر مرخــص وكان هنــاك ظــل يطــارده وعندمــا تابعــه‬\n\n\n‫‪233‬‬\n\f‫كانــت ســيارة ‪ ......‬فخرجــت عــن الطريــق وكان اجلــو غبــار وعندمــا‬\n‫عــادت إلــى الطريــق حتولــت الســيارة إلــى جيــب فلحــق بــه حتــى وصــل‬\n‫إلــى إمــارة ‪...........‬ونــزل منــه شــخص وحــاول الهــرب ولكنــه أطلــق عليــه‬\n‫النــار وســمعه يصــرخ فركــب ســيارته وتوجــه إلــى قريــة ‪...........‬وشــاهد‬\n‫ســيارة ‪ .....‬وأطلــق عليهــا النــار وبعدمــا جتــاوز قريــة ‪...........‬توقــف فمــرت‬\n‫مــن أمامــه ســيارة ‪ .....‬فأطلــق النــار عليهــا وأنــه ال يعلــم ســبب قيامــه بهــذه‬\n‫األفعــال كمــا ذكــر بأنــه ال يعــرف األشــخاص الذيــن أطلــق عليهــم‬\n‫النــار وليــس بينــه وبينهــم أي عــداوة أ ه ـ والنتهــاء وقــت اجللســة رفعــت‬\n‫اجللســة ‪،،،‬ويف جلســة أخــرى وفيهــا حضــر املدعــي العــام واملدعــى عليــه‬\n‫ويف هــذه اجللســة جــرى الرجــوع إلــى أوراق املعاملــة وجــد بــن طياتهــا‬\n‫اعتــراف مصــدق للمدعــى عليــه مــدون علــى لفــه (‪ )1‬صفحــة صـ ـ ‪5/4‬ـ ـ ـ‬\n‫وهــذا نصــه ‪ :‬اقــر واعتــرف أنــا املواطــن ‪...........‬هويــة وطنيــة رقــم ‪...........‬‬\n‫وتاريــخ ‪1415/8/22‬ه ـ ســجل حائــل بأنــي كنــت ليلــة االثنــن موجــودا‬\n‫بالريــاض ليــا وقمــت بــأكل حبــوب مخــدرة وبعــد ذلــك قــام أصحــاب‬\n‫ثالثــة ســيارات مبضايقتــي فقصــدت التوجــه إلــى قريــة ‪...........‬لكــي‬\n‫آخــذ ســاحي املوجــود مبنزلنــا هنــاك وكانــت الســيارات تضايقنــي‬\n‫حتــى وصلــت إلــى ‪...........‬وتوجهــت مــع طريــق ‪...........‬قاصــدا‪...........‬‬\n‫وكان الفجــر قــد خــرج وانبــاح الشــوف وكان ظــل خلفــي يتابعنــي‬\n‫وتوجهــت إلــى منزلنــا بقريــة ‪...........‬وأخــذت ســاحا لــي نــوع شــوزن ومعــه‬\n‫ذخيــره وركبــت ســيارتي ‪ .....‬ثــم شــاهدت الظــل مــرة أخــرى وقمــت‬\n‫بطــرده وملــا اقتربــت منــه خرجــت ســيارة ‪ ....‬ثــم خــرج عــن اخلــط وعــادت‬\n‫إليــه وملــا عــادت للطريــق حتولــت إلــى ‪ .....‬وقمــت مبطاردتــه حتــى وصــل‬\n‫إلــى مركــز إمــارة ‪...........‬ونــزل منــه شــخص وقلــت لــه مــاذا تريــد منــي‬\n\n\n                                                                                            ‫‪234‬‬\n\f      ‫تالحقنــي ومعــي الســاح نــوع شــوزن فهــرب يريــد الدخــول إلــى مبنــى‬\n      ‫اإلمــارة وقمــت بإطــاق النــار عليــه وســمعت صراخــه ثــم حتركــت‬\n      ‫مــن أمــام املركــز واجتهــت مــع طريــق ‪...........‬وشــاهدت فــورد ميشــي‬\n      ‫أمامــي فقمــت مبطاردتــه وإطــاق النــار عليــه وقمــت باللحــاق بــه حتــى‬\n      ‫منتصــف الطريــق بــن ‪...........‬و‪ ...........‬ثــم توقفــت ومــر مــن عنــدي ‪....‬‬\n      ‫متوجهــا الــى ‪...........‬وقمــت بإطــاق النــار م الســاح الــذي معــي مــن دون‬\n      ‫أي ســبب علمــا باننــي ال أعــرف مــن هــم الذيــن أطلقــت النــار عليهــم‬\n      ‫ولــم يكــن بينــي وبينهــم عــداوة أو مشــكله هــذا اقــرار منــي واعتــراف‬\n      ‫مبــا حصــل ومــا بــدر منــي حــول ذلــك وعليــه اوقــع أ ه ـ واملصــدق عليــه‬\n      ‫ـاء علــى‬ ‫شــرعا مــن قبــل فضيلــة قاضــي احملكمــة العامــة ب‪ ...........‬فبنـ ً‬\n      ‫مــا تقــدم مــن الدعــوى واإلجابــة وبتأمــل القضيــة ودراســتها وحيــث‬\n      ‫صــادق املدعــى عليــه علــى دعــوى املدعــي العــام وأنــه يتعاطــى احلبــوب‬\n      ‫احملظــورة واحلشــيش وأنــه قــاد الســيارة حتــت تأثيــر املســكر وقــرر أنــه‬\n      ‫أطلــق النــار وأصــاب مــن أصــاب حتــت تأثيــر احلبــوب واحلشــيش ومبــا أن‬\n      ‫املدعــى عليــه صاحــب ســوابق ممــا يــدل علــى تأصــل الشــر والفســاد يف‬\n      ‫نفســه وفعلــه أخيــر ًا محاربــه هلل ورســوله وســعي يف األرض فســاد ًا وملــا‬\n      ‫جــاء يف إقــرار املدعــى عليــه املصــدق شــرعا ولقولــه تعالــى [ إمنــا جــزاء‬\n      ‫الذيــن يحاربــون اهلل ورســوله ويســعون يف األرض فســاد ًا أن يقتلــوا أو‬\n      ‫يصلبــوا أو تقطــع أيديهــم وأرجلهــم مــن خــاف أو ينفــوا مــن األرض ذلــك‬\n      ‫لهــم خــزي يف الدنيــا ولهــم يف اآلخــرة عــذاب عظيــم ] املائــدة ‪33‬وملــا جــاء‬\n      ‫يف قــرار هيئــة كبــار العلمــاء رقــم ‪85‬يف‪1401/01/11‬ه ـ وبعــد اإلطــاع‬\n      ‫علــى التعميــم الــوارد لنــا مــن معالــي رئيــس املجلــس األعلــى للقضــاء‬\n      ‫برقــم ‪/292‬ت يف‪1433/08/28‬ه ـ املتضمــن تعميــم األمــر امللكــي رقــم‬\n\n\n‫‪235‬‬\n\f‫‪26834‬تاريخ‪1433/05/29‬ه ـ القاضــي بــأن ال يقــل ســجن احملــارب‬\n‫ـاء علــى‬‫عــن عشــرين عام ـ ًا وأن يكــون ذلــك قاعــدة عامــة ‪ . . .‬إلــخ فبنـ ً‬\n‫مــا ســبق كلــه فقــد ظهــر لنــا مــا يلــي ‪ :‬أوالً‪/‬أمرنــا بإقامــة حــد احلرابــة‬\n‫علــى املدعــى عليــه ونقتــرح يف ذلــك نفيــه علــى ضــوء التعميــم املشــار إليــه‬\n‫أعــاه ‪ -‬ثانياً‪/‬أمرنــا بإقامــة حــد املســكر علــى املدعــى عليــه وذلــك‬\n‫بجلــده ثمانــن جلــده دفعــة واحــدة ‪ -‬ثالثاً‪/‬ثبــت لدينــا إدانــة املدعــى‬\n‫عليــه بتعاطيــه لثــاث حبــات محظــورة وأمرنــا بتعزيــر املدعــى عليــه لقــاء‬\n‫تعاطيــه احلبــوب احملظــورة وذلــك بجلــده ســبعني جلــده دفعــة واحــدة ‪-‬‬\n‫رابعاً‪/‬ثبــت لدينــا أن املدعــى عليــه قــاد الســيارة وحتــت تأثيــر املســكر‬\n‫وعقابــه يف ذلــك عائــد إلــى ولــي األمــر وصرفنــا النظــر عــن بقيــة طلبــات‬\n‫املدعــي العــام ‪ -‬وبــكل مــا تقــدم حكمنــا بعــرض احلكــم علــى املدعــى‬\n‫عليــه واملدعــي العــام قــررا عــدم قناعتهمــا باحلكــم ورغبــا رفــع احلكــم‬\n‫حملكمــة االســتئناف لتدقيقــه كاملتبــع مــن غيــر الئحــة وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                    ‫‪1434/1/10‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم الســبت املوافق‪1434/02/02‬ه ـ‬\n‫افتتحــت اجللســة الســاعة احلاديــة عشــر والنصــف وقــد وردتنــا املعاملــة‬\n‫مــن محكمــة االســتئناف مبنطقــة حائــل مبوجــب كتــاب رئيســها‬\n‫رقــم ‪ 34128869‬بتاريــخ ‪1434/1/26‬ه ــاملرفق معــه قــرار الدائــرة‬\n‫اخلماســية برقــم ‪ 3415383‬بتاريــخ ‪1434/1/18‬ه ـ ونــص احلاجــه منــه‬\n‫(وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة لوحــظ أن أصحــاب‬\n‫الفضيلــة وفقهــم اهلل قــد حكمــوا بإقامــة حــد احلرابــة علــى املدعــى عليه‬\n‫واقترحــوا نفيــه مــن األرض علــى ضــوء التعميــم املشــار إليــه إال أنهــم لــم‬\n\n\n                                                                                        ‫‪236‬‬\n\f      ‫يصرحــوا مبــدة ســجنه حيــث ان التعميــم املشــار إليــه حــدد االقــل ولــم‬\n      ‫يحــدد األعلــى والبــد مــن ذلــك كمــا وجــد أن صــورة الضبــط لــم تصــدق‬\n      ‫طبــق أصلهــا حســب التعليمــات ملالحظــة ذلــك وإجــراء مــا يلــزم واهلل‬\n      ‫املوفــق) أ ه ـ قضــاة اســتئناف ‪...........‬و‪...........‬و‪ ...........‬و‪...........‬ورئيــس‬\n      ‫الدائــرة ‪...........‬أختامهــم وتواقيعهــم عليــه جنيــب أصحــاب الفضيلــة‬\n      ‫وفقنــا اهلل وإياهــم إلــى الصــواب أننــا نقتــرح ســجنه مــدة قدرهــا عشــرون‬\n      ‫عامــا ويعامــل يف إخراجــه بعــد هــذه املــدة وفــق مــا جــاء بالتعميــم املشــار‬\n      ‫إليــه بعاليــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                              ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/2/2‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم األربعــاء املوافــق‪1434/02/13‬‬\n      ‫ه ـ افتتحــت اجللســة الســاعة التاســعة والربــع وقــد عــادت املعاملــة مــن‬\n      ‫محكمــة االســتئناف مبنطقــة حائــل مبوجــب كتــاب رئيســها رقــم‬\n      ‫‪ 34301881‬يف ‪1434/02/06‬ه ـ املرفــق معــه قــرار تصديــق الدائــرة‬\n      ‫اخلماســية برقــم ‪3431178‬يف ‪1434/02/05‬ه ـ املتضمــن املصادقــة على‬\n      ‫ماحكــم بــه أصحــاب الفضيلــة‪ .‬قضــاة االســتئناف ‪ ...........‬و‪...........‬‬\n      ‫و‪ ...........‬و‪ ..............‬ورئيــس الدائــرة ‪...........‬أختامهــم وتواقيعهــم أه ـ‬\n      ‫‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                         ‫وســلم ‪ .‬حــرر يف ‪1434/2/13‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي هــذا اليوم األربعاء املوافــق ‪1434/07/19‬هـ‬\n      ‫افتتحــت اجللســة الســاعة الواحــدة وخمســة وأربعــون دقيقــة وقــد وردنــا‬\n      ‫صــورة مــن كتــاب رئيــس احملكمــة العليــا املوجــه أصلــه إلــى خــادم‬\n      ‫احلرمــن الشــريفني رئيــس مجلــس الــوزراء رقــم ‪ 341118972‬يف‬\n      ‫‪1434/07/03‬ه ــاملرفق معــه قــرار الدائــرة اجلزائيــة األولــى باحملكمــة‬\n\n\n‫‪237‬‬\n\f‫العليــا رقــم ‪ 1/1/139‬يف ‪1434/6/13‬ه ـ املتضمــن املصادقــة علــى‬\n‫احلكــم ونصــه ‪ :‬فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ولألســباب‬\n‫التــي ذكرهــا أصحــاب الفضيلــة حــكام القضيــة قــرروا احلكــم مبــا‬\n‫يلــي ‪ :‬أوال ‪ :‬إقامــة حــد احلرابــة علــى املدعــى عليــه واقتــراح أصحــاب‬\n‫الفضيلــة نفيــه‪ .‬ثاني ـاً‪ :‬إقامــة حــد املســكر بجلــده ثمانــن جلــده دفعــة‬\n‫واحــدة ‪ .‬ثالث ـاً‪ :‬ثبــت لديهــم إدانــة املدعــى عليــه بتعاطيــه لثــاث حبــات‬\n‫محظــورة وقــرروا تعزيــره بجلــده ســبعني جلــده دفعــة واحــدة‪ .‬رابعـاً‪ :‬ثبــت‬\n‫لديهــم قيــادة املدعــى عليــه للســيارة حتت تأثير املســكر وعقابه يف ذلك‬\n‫لولــي األمــر ‪ ،‬وصرفــوا النظــر عــن بقيــة طلــب املدعــي العــام‪ .‬وبعرضــه‬\n‫علــى الطرفــن قــررا عــدم القناعــة ‪ ،‬وبرفعــه حملكمــة االســتئناف‬\n‫مبنطقــة حائــل صدقتــه بالقــرار رقــم (‪ )3431178‬يف ‪1434/02/05‬هــ‪.‬‬\n‫ثــم وردت املعاملــة إلــى احملكمــة العليــا كمــا تقــدم ‪ ،‬وبدراســة الصــك‬\n‫املذكــور ‪ ،‬وجميــع أوراق املعاملــة قــررت الدائــرة املوافقــة علــى احلكــم‬\n‫أه ـ ‪ .‬أعضــاء احملكمــة العليــا ‪...........‬و‪...........‬و‪...........‬و‪ ...........‬ورئيــس‬\n‫الدائــرة ‪...........‬تواقيعهــم وأختامهــم ‪ ،‬وأمــرت بإحلــاق ذلــك علــى ســجله‬\n‫‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                  ‫وســلم ‪ .‬حــرر يف ‪1434/7/19‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                            ‫‪238‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":222,"source_page_end":238,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0b99fb5f1c944d696eee559d8e736030392742c2380eeade5d2b400ebd537083","normalized_text_hash":"9e9cb3ab3bc56d33be370c66ac3702d5f81182f3504ab11fa38d9487c1747c8b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p222-349934"},{"id":"7209ff70-512c-55bc-a036-997a4349aa8d","document_type":"judgment","category":"judicial","subcategory":"general","title":"حرابة -سرقة -سطو مسلح -شرب املسكر -تهديد بالساح - سرقة سيارة -إحداث إصابات -مقاومة قوات األمن -اقرار مصدق شرع ا -من شروط احلرابة حمل الساح -تعزير بالسجن واجللد.","document_number":"34176771","case_number":"34100345","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة ومبشاركة القاضين بها","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/2","year":"1434","subject":"حرابة -سرقة -سطو مسلح -شرب املسكر -تهديد بالساح - سرقة سيارة -إحداث إصابات -مقاومة قوات األمن -اقرار مصدق شرع ا -من شروط احلرابة حمل الساح -تعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 34176771 :‬تاريخه‪1434/4/2:‬هـ‬\n                         ‫رقم الدعوى‪34100345 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                    ‫‪ 195169‬تاريخه‪1434/4/2 :‬هـ‬\n\n\n      ‫حرابــة ‪ -‬ســرقة ‪ -‬ســطو مســلح ‪ -‬شــرب املســكر ‪ -‬تهديــد بالســاح ‪-‬‬\n      ‫ســرقة ســيارة ‪ -‬إحــداث إصابــات ‪ -‬مقاومــة قــوات األمــن ‪ -‬اقــرار مصــدق‬\n      ‫شــرع ًا ‪ -‬مــن شــروط احلرابــة حمــل الســاح ‪ -‬تعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n\n      ‫قــال ابــن قدامــة ‪»:‬الشــرط الثانــي أن يكــون معهــم ســاح فــإن لــم يكــن‬\n      ‫معهــم ســاح فهــم غيــر محاربــن ألنهــم ال مينعــون مــن يقصدهــم وال‬\n                                     ‫نعلــم يف هــذا خالفـ ًا أ‪.‬ه ـ املغنــي ‪. 298/10‬‬\n\n\n\n\n      ‫جــرى توجيــه االتهــام للمدعــى عليــه باالشــتراك يف الســطو علــى عــدد‬\n      ‫مــن العمالــة مبحطــات الوقــود حتــت تهديــد الســاح وســلبهم والتســبب‬\n      ‫يف إصابــة اثنــن منهــم واالشــتراك يف ســرقة ســيارة وصــدم ســيارة‬\n      ‫الدوريــة وإحــداث تلفيــات بهــا‪ ،‬والهــروب مــن رجــال األمــن‪ ،‬والتســتر‬\n      ‫علــى شــريكه باجلرميــة وطلــب إثبــات مــا أســند إليــه واحلكــم عليــه‬\n      ‫بحــد احلرابــة ‪ ،‬حيــث تلقــت الشــرطة بالغــا مــن عمــال محطــة بــأن‬\n      ‫املدعــى عليــه ومعــه شــخص آخــر قامــا بتهديدهــم وســلبوا مــا يقــارب‬\n      ‫تســعة آالف ريــال وعشــرين دفتــرا «بطاقــات وقــود» وجــواالت العاملــن‬\n      ‫وكســرا كاميــرا املراقبــة ثــم هربــا ‪ ،‬ثــم تلقــت الشــرطة بالغــا مــن‬\n‫‪239‬‬\n\f‫منــدوب شــركة تأجيــر ســيارات عــن حضــور املدعــى عليــه ونــزع املفتــاح‬\n‫مــن العامــل بالقــوة وهــرب بهــا ‪ ،‬كمــا تلقــت الشــرطة بالغــا عــن‬\n‫عمليــة ســطو أخــرى ألحــد محطــات الوقــود ‪ ،‬جــرى البحــث والتحــري‬\n‫عنهمــا والتوصــل للمدعــى عليــه وهــرب بعدمــا قــام باالصطــدام بســيارة‬\n‫الدوريــة‪ ،‬قبــض علــى املدعــى عليــه الحقــا عنــد أحــد الشــقق املفروشــة‬\n‫وبتفتيــش الغرفــة التــي يســكنها عثــر معــه علــى ســبعة جــواالت منهــا‬\n‫أحــد اجلــواالت املســروقة مــن أحــد عمــال احملطــة وكوبونــات احملطــة‬\n‫ومســدس أســود غيــر حقيقــي وســاطور‪ ،‬كمــا عثــر معــه علــى قطعــة‬\n‫يشــتبه بأنهــا مــن احلشــيش املخــدر‪ ،‬تعــرف العمــال علــى املدعــى عليــه‪،‬‬\n‫أقــر املدعــى عليــه مبــا ورد يف الئحــة االدعــاء العــام وقــرر بأنــه كان‬\n‫حينهــا ســكرانا وأنــه هــدد عمــال احملطــة مبســدس لعبــة إال أنــه لــم يقــم‬\n‫بضربهــم وتعذيبهــم كمــا أقــر أنــه أخــذ مــن احملطــة املبالــغ املشــار لهــا‬\n‫يف صحيفــة الدعــوى واجلــواالت مــن العمــال والكوبونــات كمــا أنكــر‬\n‫قيامــه بســرقة الســيارة ودفــع بأنــه أخذهــا مــن شــخص آخــر وال يعلــم‬\n‫عــن كونهــا مســروقة وأقــر بهربــه واصطدامــه بســيارة الدوريــة ‪ ،‬عليــه‬\n‫وألن املدعــى عليــه لــم يكــن معــه ســاح وإمنــا مســدس اللعبــة وهــو ليــس‬\n‫بســاح وال يف معنــى الســاح‪ ،‬وألن املدعــي العــام لــم يقــدم بينــة تؤيــد‬\n‫دعــواه وغايــة مــا قــدم إقــرار املدعــى عليــه املصــدق شــرع ًا وأيضـ ًا مــا ورد‬\n‫يف التقريــر الطبــي لعاملــي احملطــة وهــذا يقــوي التهمــة علــى املدعــى‬\n‫عليــه باعتدائــه علــى عاملــي احملطــة بالســاح‪ ،‬وجلميــع مــا ســبق فقــد‬\n‫حكمــت الدائــرة مبــا يلــي‪ :‬أوالً‪ /‬صــرف النظــر عــن طلــب املدعــي العــام‬\n‫إقامــة حــد احلرابــة علــى املدعــى عليــه لعــدم ثبــوت موجبــه‪ .‬ثانيـاً‪ /‬تعزيــر‬\n‫املدعــى عليــه بســجنه ثمانيــة أعــوام مــن تاريــخ إيقافــه وجلــده ثمامنائــة‬\n\n\n                                                                                         ‫‪240‬‬\n\f      ‫جلــدة مفرقــة علــى دفعــات كل دفعــة خمســن جلــدة بــن كل فتــرة‬\n      ‫وأخــرى عشــرة أيــام‪ .‬ثالث ـاً‪ /‬ثبــوت إدانــة املدعــى عليــه بشــرب املســكر‬\n      ‫ويجلــد لقــاء ذلــك ثمانــن جلــدة دفعــة واحــدة حــد املســكر ‪ ،‬قــرر‬\n      ‫املدعــى عليــه القناعــة بينمــا قــرر املدعــي العــام عدمهــا وأفهــم بتعليمــات‬\n                      ‫االســتئناف ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة العامــة‬\n      ‫مبحافظــة جــدة ومبشــاركة القاضيــن بهــا ‪ .............‬والقاضــي ‪...........‬‬\n      ‫القاضــي يف احملكمــة العامــة مبحافظــة جــدة وبنــاء علــى املعاملــة‬\n      ‫احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة جــدة‪/‬‬\n      ‫املســاعد برقــم ‪ 34100345‬وتاريــخ ‪1434/3/1‬ه ـ املقيــدة باحملكمــة‬\n      ‫برقــم ‪ 34381367‬وتاريــخ ‪1434/01/27‬ه ـ ويف يــوم االثنــن‬\n      ‫‪1434/03/09‬هـ افتتحت اجللســة الســاعة ‪ 11 : 00‬وفيها حضر املدعي‬\n      ‫العــام ‪...........‬وادعــى علــى احلاضــر معــه ‪28 ،...........‬عام ـ ًا ‪ ،‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )...........‬موقــوف يف ســجون‬\n      ‫محافظــة جــدة مبوجــب أمــر متديــد التوقيــف رقــم (‪ )18/121‬وتاريــخ‬\n      ‫ا فيدعــواه أنــه بتاريــخ ‪1433/8/21‬ه ـ تلقــت‬           ‫‪1433/9/26‬ه ـ قائ ـ ً‬\n      ‫الدوريــات األمنيــة بــاغ مــن عمــال محطــة ‪...........‬بطريــق ………وهــم‬\n      ‫ال مــن املقيم‪............./‬واملقيــم‪ ........... /‬واملقيــم‪.........../‬‬     ‫ك ً‬\n      ‫واملقيــم‪( .........../‬بنقالديشــيي اجلنســية) واملواطن‪.........../‬الذيــن أفــادوا‬\n      ‫عــن حضــور املدعــى عليــه ومعــه شــخص آخــر الــى احملطــة وبحوزتهمــا‬\n      ‫ســاح ابيــض مــن نــوع ســاطور وســاح نــاري مــن نــوع مســدس (غيــر‬\n\n‫‪241‬‬\n\f‫حقيقــي) وقامــا بتهديدهــم وطلبــا منهــم إرشــادهما علــى مــكان وجــود‬\n‫إيــرادات احملطــة فقــام العامــل بإيصالهمــا إلــى املكتــب اخلــاص باحملطــة‬\n‫حتــت تهديــد الســاح وعنــد وصولهمــا للمكتــب قامــا بضــرب العامــل‬\n‫وتهديــد جميــع األشــخاص الذيــن كانــوا بداخــل الغرفــة وأخــذا إيــراد‬\n‫احملطــة وقــدره (‪ )9272‬تســعة آالف ومائتــان واثنــان وســبعون ريــا ًال‬\n‫وعــدد عشــرين دفتــر (كــروت بنزيــن) وجــواالت العاملــن وعددهــا‬\n‫تســعة جــواالت وكســرا كاميــرا املراقبــة ثــم هربــا‪ ،‬وقــد صــدر بحــق‬\n‫املخبر‪.........../‬التقريــر الطبــي رقــم (بــدون) وتاريــخ ‪1433/8/21‬ه ـ‬\n‫املتضمــن إصابتــه بكدمــة بالعــن اليمنــى ومــدة الشــفاء ثالثــة أيــام‬\n‫وصــدر بحــق املخبر‪.........../‬التقريــر الطبــي رقــم (بــدون) وتاريــخ‬\n‫‪1433/8/21‬ه ـ املتضمــن إصابتــه بجــرح قطعــي يف فــروة الــرأس ومــدة‬\n‫الشــفاء أســبوع ‪ .‬وبتاريــخ ‪1433/8/21‬ه ـ أبلــغ مركــز شــرطة ‪...........‬‬\n‫املواطــن ‪....................../‬منــدوب شــركة‪...........‬لتأجير الســيارات عــن‬\n‫حضــور املدعــى عليــه الــى فــرع الشــركة بشــارع‪...........‬ألجل اســتئجار‬\n‫ســيارة وطلــب معاينــة الســيارة قبــل أن يســتأجرها فخــرج معــه الــى‬\n‫الســيارة التــي كانــت متوقفــة أمــام الفــرع مــن نــوع ‪ ..............‬رقــم اللوحــة‬\n‫(‪ )...........‬اللــون ‪ ..........‬وقــام بفتحهــا لــه ملعاينتهــا إال أنــه ســحب املفتــاح‬\n‫مــن يــده بالقــوة وركــب الســيارة عنــوة وهــرب بهــا ‪ .‬وبتاريــخ‬\n‫‪1433/9/18‬ه ـ تلقــت الدوريــات األمنيــة بــاغ مــن عمــال محطــة ‪...........‬‬\n‫ال مــن املقيم‪.........../‬واملقيــم ‪........... /‬‬      ‫بطريــق املدينــة وهــم ك ً‬\n‫واملقيم‪....................../‬واملقيــم‪( ………/‬بنقالديشــيي اجلنســية) الذيــن‬\n‫أفــادوا عــن حضــور املدعــى عليــه ومعــه شــخص آخــر إلــى مقــر ســكنهم‬\n‫وطرقــا عليهــم البــاب وعندمــا فتحــوا البــاب كان أحــد األشــخاص‬\n\n\n                                                                                              ‫‪242‬‬\n\f      ‫يحمــل يف يــده مســدس هددهــم بــه وأخــذ منهــم إيــراد احملطــة املقــدر‬\n      ‫بحوالــي (‪ )7689‬ســبعة آالف وســتمائة وتســعة وثمانــن ريــا ًال وأجهــزة‬\n      ‫جواالتهــم وعددهــا ســبعة أجهــزة وإقامــة املدعو‪.........../‬ثــم أقفــا‬\n      ‫الســكن عليهــم مــن اخلــارج وهربــا وبنــاء علــى املعلومــات التــي أدلــى بهــا‬\n      ‫املجنــي عليهــم وبالبحــث والتحــري اتضــح بــأن هنــاك شــريحتني مت‬\n      ‫تركيبهــا علــى احــد األجهــزة املســروقة بعــد احلادثــة وان الشــريحتني‬\n      ‫تخــص املدعو‪(.........../‬لــم يتــم توجيــه االتهــام إليــه بشــيء) الــذي مت‬\n      ‫القبــض عليــه بتاريــخ ‪1433/9/18‬ه ـ بحــي ‪...........‬ومبناقشــته أفــاد بأنــه‬\n      ‫قبــل شــهر رمضــان ورد لــه اتصــال علــى جوالــه مــن املدعــى عليــه وطلــب‬\n      ‫منــه مقابلتــه لوجــود مشــكلة لديــه وقابلــه املدعــى عليــه ومعــه شــخص‬\n      ‫آخــر ال يعرفــه ألجــل إيصالهمــا إلــى شــارع ‪...........‬فركبــا معــه فذكــر‬\n      ‫لــه املدعــى عليــه بأنــه حدثــت لهمــا مضاربــة مــع عمــال محطــة ‪...........‬‬\n      ‫ولــم يوضــح لــه تفاصيــل مــا حــدث وبســؤاله عــن الشــريحتني وجهــاز‬\n      ‫الهاتــف اجلــوال املســروق ذكــر بــأن اجلهــاز أخــذه مــن املدعــى عليــه وهــو‬\n      ‫موجــود لديــه باملنــزل وتبــن انــه اجلهــاز الــذي ســلب مــن املجنــي‬\n      ‫عليه‪،....................../‬وقــد مت الوصــول إلــى املدعــى عليــه مــن خــال‬\n      ‫متكــن املدعو‪.........../‬مــن االتصــال عليــه وقــد حضــر وبقيادتــه الســيارة‬\n      ‫الفــورد املبلــغ عــن ســرقتها وأثنــاء القبــض صــدم ســيارة الدوريــة ممــا‬\n      ‫أحــدث بهــا تلفيــات قــدرت مببلــغ (‪ )1500‬ريــال وهــرب وبتاريــخ‬\n      ‫‪1433/9/19‬ه ـ عثــر علــى الســيارة ‪ .....‬متوقفــة عنــد إحــدى الشــقق‬\n      ‫املفروشــة التــي يســكن بهــا املدعــى عليــه فتــم القبــض عليــه وبتفتيــش‬\n      ‫الغرفــة التــي يســكنها عثــر علــى ســبعة أجهزة هواتف جــوال من ضمنها‬\n      ‫اجلهــاز املســروق مــن عمــال احملطــة وكذلــك كوبونــات بنزيــن تابعــة‬\n\n\n‫‪243‬‬\n\f‫حملطــة ‪...........‬ومســدس لونــه أســود (غيــر حقيقــي) وســاطور كمــا عثــر‬\n‫علــى قطعــة يشــتبه أنهــا مــن احلشــيش املخــدر (فصلــت لذلــك أوراق‬\n‫مســتقلة وأحيلــت ملكافحــة املخــدرات) واتضــح بــأن الســيارة التــي‬\n‫كانــت بقيادتــه مســروقة ومعمــم عنهــا ومبناقشــته مبدئي ـ ًا اعتــرف‬\n‫بالســرقة مبرافقــة شــخص آخــر يدعى‪،.........../‬ســعودي اجلنســية‬\n‫(فصلــت أوراق مســتقلة للبحــث عنــه( وباســتجواب املدعــى عليــه اعتــرف‬\n‫أنــه اتفــق مــع املدعو‪.........../‬علــى ســرقة محطــة ‪...........‬الواقعــة بطريــق‬\n‫امللــك ……… كونهمــا محتاجــن للمــال وعنــد وصولهمــا للمحطــة‬\n‫كان يوجــد هنــاك غرفــة بأحــد زوايــا احملطــة وعنــد مشــاهدتهما لعمال‬\n‫احملطــة هددهــم بواســطة مســدس لونــه أســود (لعبــة) وهددهــم زميلــه‬\n‫بســكني وأدخلوهــم داخــل الغرفــة وســلبا مــا معهــم مــن مبالــغ ماليــة‬\n‫وكــروت تعبئــة بنزيــن ثــم هربــا إلــى عمــارة حتــت اإلنشــاء قريبــة مــن‬\n‫احملطــة وظــا بهــا قرابــة ثــاث ســاعات ثــم اتصــل بزميلــه ‪......................‬‬\n‫وطلــب منــه احلضــور ألجــل إيصالهمــا إلــى دوار ‪...........‬وبعــد أن ركبــا‬\n‫مــع‪........... /‬يســلمه احــد اجلــواالت املســروقة دون أن يبلغــه بعمليــة‬\n‫الســرقة كمــا أقــر بــان الســيارة‪......‬التي ضبطــت معــه ســرقها زميلــه‬\n‫‪.........../‬ويعلــم بســرقتها وقــد أخذهــا منــه مقابــل مبلــغ وقــدره خمســمائة‬\n‫ريــال وصدقــت أقوالــه شــرع ًا بذلــك‪ .‬وبعــرض املدعــى عليــه‬\n‫واملدعو‪.........../‬علــى املخبريــن يف محطــة ‪...........‬بحــي ‪...........‬تعرفــوا‬\n‫علــى املدعــى عليــه وأكــدوا أنــه مــن ضمــن األشــخاص الذيــن هددوهــم‬\n‫مبســدس كان يحملــه ‪ .‬وبعرضهمــا علــى املخبريــن يف محطــة ‪...........‬‬\n‫بحــي ‪...........‬تعرفــوا علــى املدعــى عليــه وأكــدوا أنــه مــن ضمــن‬\n‫األشــخاص الذيــن هددوهــم مبســدس كان يحملــه ‪ .‬وقــد انتهــى‬\n\n\n                                                                                         ‫‪244‬‬\n\f      ‫التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه باالشــتراك يف الســطو علــى‬\n      ‫عــدد مــن العمالــة مبحطــات الوقــود حتــت تهديــد الســاح وســلبهم‬\n      ‫والتســبب يف إصابــة اثنــن منهــم واالشــتراك يف ســرقة ســيارة وصــدم‬\n      ‫سيارة الدورية وإحداث تلفيات بها‪ ،‬والهروب من رجال األمن‪،‬والتستر‬\n      ‫علــى شــريكه باجلرميــة ‪،‬مبوجــب قــرار االتهــام رقــم ‪ ...........‬املؤيــد بقــرار‬\n      ‫جلنــة إدارة الهيئــة رقم‪...........‬لعــام ‪1434‬ه ـ وذلــك لألدلــة والقرائن التالية‬\n      ‫‪ -1:‬اعترافــه املصــدق شــرع ًا املنــوه عنــه املــدون يف دفتــر التحقيــق لفــة‬\n      ‫(‪ )40‬ص(‪ -2.)12‬محضــر القبــض املنــوه عنــه املــدون يف دفتــر التحقيــق‬\n      ‫املرفــق داخــل الطــرد لفــة (‪ )40‬ص(‪ -3.)10-2‬محضــر العــرض املــدون‬\n      ‫علــى ص(‪ )8‬لفــة(‪ -4 .)1‬محضــر العــرض املنــوه عنــه املــدون يف دفتــر‬\n      ‫التحقيــق املرفــق داخــل الطــرد لفــة(‪ )68‬ص (‪ -5 .)4-3‬مــا جــاء يف‬\n      ‫التقريريــن الطبيــن املنــوه عنهمــا املرفقــن داخــل الطــرد لفــة (‪.)13-12‬‬\n      ‫‪ -6‬العثــور علــى بعــض املســروقات بحوزتــه مــن ضمنهــا جــواالت‬\n      ‫وكوبونــات التعبئــة اخلاصــة باحملطــة‪ -7 .‬ماجــاء يف كتــاب البحــث‬\n      ‫اجلنائــي رقــم ‪/14/20/19275‬ع‪ 22‬يف ‪1433/9/25‬ه ـ املتضمــن صــدم‬\n      ‫املدعــى عليــه بالســيارة التــي كان يقودهــا ســيارة الدوريــة وقيمــة تقديــر‬\n      ‫التلفيــات التــي حلقــت بهــا ص(‪ -8 .)50-49‬مــا ورد يف إقــرار ‪...........‬‬\n      ‫املــدون علــى ص(‪ )11‬لفــة(‪ .)40‬وباالطــاع علــى صحيفــة ســوابقه عثــر‬\n      ‫لــه علــى ســابقة حيــازة مخــدرات‪ .‬وحيــث إن مــا أقــدم عليــه املدعــى عليــه‬\n      ‫وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n      ‫ويعــد ضربـ ًا مــن ضــروب احلرابــة والســعي يف األرض فســاد ًا وتعــد علــى‬\n      ‫حرمــات املســلمني وأموالهــم علــى ســبيل الغلبــة والقهــر‪ ،‬فإننــي اطلــب‬\n      ‫إثبــات مــا اســند إليــه اســتنادا ًللمادتــن (‪ ) 126،129‬مــن نظــام‬\n\n\n‫‪245‬‬\n\f‫اإلجــراءات اجلزائيــة واحلكــم عليــه بحد احلرابة الــوارد يف اآلية الكرمية‬\n‫رقــم (‪ )33‬مــن ســورة املائــدة علــى ضــوء قــرار هيئــة كبــار العلمــاء رقــم‬\n‫(‪ )85‬وتاريــخ ‪1401/11/11‬هــ‪( .‬علم ـ ًا أن احلــق اخلــاص مــازال قائم ـاً)‬\n‫هــذه دعــواي وبعــرض مــا جــاء يف دعــوى املدعــي العــام علــى املدعــى عليــه‬\n‫ا مــا ذكــره املدعــي العــام يف الئحتــه مــن الســطو على‬     ‫‪...........‬أجــاب قائـ ً‬\n‫احملطــة فهــو صحيــح وأنــا كنــت يف حالــة ســكر عنــد قيامــي بالســطو‬\n‫علــى احملطــة وقــد هــددت عمــال احملطــة مبســدس لعبــة ولــم أقــم‬\n‫بضربهــم وتعذيبهــم وقــد أخــذت مــن احملطــة املبلــغ املذكــور يف الدعــوى‬\n‫وكذلــك بعــض اجلــواالت والكوبونــات وأمــا مــا ذكــر مــن اشــتراكي‬\n‫يف ســرقة الســيارة فغيــر صحيــح فقــد أخــذت الســيارة مــن ‪...........‬وال‬\n‫أعلــم بســرقتها مــن عدمــه وأمــا مــا ذكــر مــن صدمــي لســيارة الدوريــة‬\n‫وهروبــي مــن رجــال األمــن فهــو صحيــح وأنــا تائــب ونــادم علــى مــا فعلــت‬\n‫ا نعــم لــدي ســابقة‬  ‫هكــذا أجــاب وبســؤاله عــن الســابقة أجــاب قائ ـ ً‬\n‫حيــازة مخــدرات هكــذا أجــاب ولالطــاع علــى أوراق املعاملــة جــرى‬\n‫تأجيــل اجللســة إلــى يــوم االثنــن ‪1434/3/23‬ه ـ الســاعة ‪09 : 00‬‬\n‫وأغلقــت اجللســة الســاعة ‪ 11 : 30‬وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n‫نبينــا محمــد وعلــى آلــه وصحبــه حــرر يف ‪1434/3/16‬ه ـ ثــم يف جلســة‬\n‫أخــرى ويف هــذا اليــوم االثنــن ‪1434/3/23‬ه ـ افتتحــت اجللســة الســاعة‬\n‫‪ 09 : 00‬وفيهــا حضــر املدعــي العــام حضــر حلضوره املدعــى عليه ‪...........‬‬\n‫ا بينتــي مــا جــاء يف أوراق‬  ‫وبســؤال املدعــي العــام عــن بينتــه أجــاب قائ ـ ً‬\n‫املعاملــة هكــذا أجــاب وبالرجــوع إلــى أوراق املعاملــة وجدنــا باللفــة رقــم‬\n‫‪ 40‬صحيفــة ‪ 12‬إقــرار االعتــراف املصــدق شــرع ًا والــذي نصــه إقــرار‬\n‫اعتــراف بتاريــخ ‪1433/9/19‬ه ـ أقــر أنــا املدعــو‪ .............. /‬ســعودي‬\n\n\n                                                                                           ‫‪246‬‬\n\f      ‫اجلنســية ‪ 28‬ســنة رقــم الهويــة ( ‪ )...........‬وأنــا بكامــل قــواي العقليــة‬\n      ‫املعتبــرة شــرع ًا وبطوعــي واختيــاري ال مجبــر ًا وال مكره ـ ًا بأنــه قبــل‬\n      ‫شــهر رمضــان بحوالــي أســبوعني تقريبـ ًا قابلــت أحــد أصدقائــي يدعــى‪/‬‬\n      ‫‪ ...........‬واتفقــت معــه علــى ســرقة محطــة‪ ...........‬الواقعــة بطريــق امللــك‬\n      ‫ا عنــد وصولنــا للمحطــة كان‬         ‫لكونــه ال يوجــد معنــا أي مبالــغ وفع ـ ً‬\n      ‫يوجــد هنــاك غرفــة يف إحــدى زوايــا احملطــة عندهــا شــاهدنا عمــال‬\n      ‫احملطــة وقمنــا بتهديدهــم بواســطة مســدس لونــه أســود معــي لعبــة‬\n      ‫وســكني مــع زميلــي وقمنــا بإدخالهــم بداخــل الغرفــة وتهديدهــم‬\n      ‫باملســدس وبعــد ذلــك قمنــا بســلب منهــم مبلــغ وقــدره ســبعة آالف ريــال‬\n      ‫وكــروت كوبــون تعبئــة بنزيــن وشــريط س يــدي اخلــاص باحملطــة‬\n      ‫وبعدهــا ذهبــت إلــى عمــارة قريبــة مــن احملطــة حتــت اإلنشــاء وجلســنا‬\n      ‫بهــا مــا يقــارب ثــاث ســاعات وعندهــا اتصلــت علــى أحــد أصدقائــي‬\n      ‫ا حضــر‬   ‫يدعــى‪........... /‬وطلبــت منــه احلضــور لغــرض إيصالــي وفع ـ ً‬\n      ‫املذكــور بســيارة ‪ ......‬وكان معــه شــخص يدعــى‪........... /‬وعنــد حضور‬\n      ‫املذكــور ‪...........‬ركبنــا معــه وقــام بإيصالــي إلــى دوار ‪...........‬بحــي‬\n      ‫‪...........‬علم ـ ًا بأننــي قمــت بإعطــاء املذكــور جهــاز مــن األجهــزة التــي‬\n      ‫قمنــا بســرقتها مــن عمــال احملطــة هــذا إقــراري ومســتعد التصديــق عليــه‬\n      ‫شــرعاً‪ .‬املقــر مبــا فيــه ‪......................‬بصمــة أ‪.‬ه ـ وبعــرض ذلــك علــى‬\n      ‫ا مــا ورد يف اإلقــرار كلــه صحيــح ولكنــي‬           ‫املدعــى عليــه قــرر قائ ـ ً‬\n      ‫كنــت يف حالــة ســكر أثنــاء قيامــي بالســطو علــى احملطــة هكــذا قــال‬\n      ‫كمــا وجــد باللفــة ‪ 13‬التقريــر الطبــي املبدئــي رقــم ‪ 10861698‬يف‬\n      ‫‪1433/8/21‬ه ـ املتضمــن إصابة‪...........‬بنغالديشــي اجلنســية بكدمــة‬\n      ‫بالعــن اليمنــى ‪.‬كمــا وجــد باللفــة رقــم ‪ 14‬التقريــر الطبــي املبدئــي رقــم‬\n\n\n‫‪247‬‬\n\f‫‪ 10861699‬يف ‪1433/8/21‬ه ـ املتضمــن إصابة‪...........‬بنغالديشــي‬\n‫اجلنســية بجــرح قطعــي يف فــروة الــرأس‪ .‬وبعــرض التقريريــن علــى‬\n‫ا ال أذكــر أنــي ضربــت عمــال احملطــة وإمنــا‬   ‫املدعــى عليــه أجــاب قائ ـ ً‬\n‫اكتفيــت بتهديدهــم مبســدس اللعبــة‪ ،‬لكــن قــد أكــون قمــت بدفعهــم‬\n‫هكــذا أجــاب كمــا جــرى االطــاع علــى اإلقــرار املصــدق شــرع ًا‬\n‫ل‪...........‬يف اللفــة (‪ )40‬صحيفــة (‪ )11‬والــذي نصــه إقــرار بتاريــخ‬\n‫‪1434/9/19‬ه ـ أقــر أنــا املدعــو‪...................... /‬ســعودي اجلنســية ‪34‬‬\n‫ســنة رقــم الهويــة (‪ )...........‬وأنــا بكامــل قــواي العقليــة شــرع ًا وبطوعــي‬\n‫واختيــاري بأنــه قبــل شــهر رمضــان ورد لــي اتصــال علــى جوالــي رقــم‬\n‫(‪ )...........‬مــن املدعــو‪........... /‬وكان ذلــك يف حــدود الســاعة الرابعــة‬\n‫فجــر ًا وطلــب منــي احلضــور إلــى طريــق امللــك لغــرض مقابلتــه لكــون‬\n‫ا قمــت بقيــادة ســيارتي مــن نــوع ‪ ......‬وذهبــت إلــى‬ ‫لديــه مشــكلة وفع ـ ً‬\n‫ال من شــخص يدعى‪........... /‬وشــخص‬        ‫طريــق امللــك وكان يرافقنــي ك ً‬\n‫آخــر يدعــى ‪........... /‬وعنــد وصولــي لطريــق امللــك قابلــت املذكــور‪/‬‬\n‫‪...........‬وشــخص ال أعــرف اســمه وركبــوا معــي بالســيارة وذكــر لــي‬\n‫املذكــور‪........... /‬بأنــه حــدث مقاومــة لهــم مــع عامــل محطــة ‪...........‬‬\n‫وقــام بإعطائــي جــوال ‪ ......‬وهــو اجلهــاز الــذي أحضــره أخــي ‪...........‬‬\n‫لــإدارة وكذلــك قــام املذكــور بإعطائــي كوبونــات تعبئــة بنزيــن‬\n‫شــركة‪...........‬وكان الشــخص الــذي يرافــق املدعــو‪........... /‬يرتــدي‬\n‫كاب علــى رأســه هــذا إقــراري وعليــه جــرى التوقيــع أ‪.‬ه ـ كمــا جــرى‬\n‫االطــاع علــى أوراق املعاملــة وجــرى االطــاع علــى مــا ورد يف محضــر‬\n‫القبــض املنــوه عنــه املــدون يف دفتــر التحقيــق املرفــق داخــل الطــرد لفــة‬\n‫(‪ )40‬صحيفــة (‪ .)2،10‬كمــا جــرى االطــاع علــى مــا ورد يف محضــر‬\n\n\n                                                                                       ‫‪248‬‬\n\f      ‫العــرض املــدون علــى ص(‪ )8‬لفــة (‪ .)1‬محضــر العــرض املــدون يف دفتــر‬\n      ‫التحقيــق داخــل الطــرد لفــة (‪ .)13،12‬كمــا جــرى االطــاع علــى مــا ورد‬\n      ‫يف كتاب البحث اجلنائي رقم ‪/14/20/19275‬ع‪ 22‬يف ‪1433/9/25‬هـ‬\n      ‫املتضمــن صــدم املدعــى عليــه بالســيارة التــي كان يقودهــا ســيارة‬\n      ‫الدوريــة وقيمــة تقديــر التلفيــات التــي حلقــت بهــا ص (‪ ،)50،49‬وللتأمــل‬\n      ‫رفعــت اجللســة وتأجلــت ليــوم االثنــن ‪1434/4/1‬ه ـ الســاعة ‪09 : 00‬‬\n      ‫وأغلقــت اجللســة الســاعة ‪ 09 : 30‬وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n      ‫نبينــا محمــد وعلــى آلــه وصحبــه حــرر يف ‪1434/3/23‬ه ـ ثــم يف جلســة‬\n      ‫أخــرى ويف هــذا اليــوم االثنــن ‪1434/04/01‬هـ افتتحت اجللســة الســاعة‬\n      ‫‪ 10 : 00‬وفيــه احضــر املدعــي العــام حضــر حلضوره املدعــى عليه ‪...........‬‬\n      ‫وبعــد االطــاع علــى املعاملــة وتأمــل أوراق القضيــة عليــه وبنــاء علــى مــا‬\n      ‫تقــدم مــن الدعــوى واإلجابــة ومبــا أن املدعــى عليــه قــد أقــر مبهاجمتــه‬\n      ‫لعمــال احملطــة وإخافتهــم مبســدس اللعبــة وأنكــر أن معــه ســاح أو‬\n      ‫ســكني أو غيــر ذلــك وألن مــن شــروط احملــارب وجــود الســاح معــه فــإن‬\n      ‫لــم يكــن معــه ســاح فهــو غيــر محــارب قــال ابــن قدامــة‪ :‬الشــرط الثانــي‬\n      ‫أن يكــون معهــم ســاح فــإن لــم يكــن معهــم ســاح فهــم غيــر محاربــن‬\n      ‫ألنهــم ال مينعــون مــن يقصدهــم وال نعلــم يف هــذا خالف ـ ًا أ‪.‬ه ـ املغنــي‬\n      ‫‪ 298/10‬واملدعــى عليــه لــم يكــن معــه ســاح وإمنــا كان معــه مســدس‬\n      ‫اللعبــة كمــا ذكــر ومســدس اللعبــة ليــس بســاح وال يف معنــى الســاح‬\n      ‫وألن املدعــي العــام لــم يقــدم بينــة تؤيــد دعــواه وغايــة مــا قــدم إقــرار‬\n      ‫املدعــى عليــه املصــدق شــرع ًا وأيضـ ًا مــا ورد يف التقريــر الطبــي لعاملــي‬\n      ‫احملطــة وهــذا يقــوي التهمــة علــى املدعــى عليــه باعتدائــه علــى عاملــي‬\n      ‫احملطــة بالســاح وجلميــع مــا ســبق فقــد حكمنــا مبــا يلــي‪ :‬أوالً‪ :‬صــرف‬\n\n\n‫‪249‬‬\n\f‫النظــر عــن طلــب املدعــي العــام إقامــة حــد احلرابــة علــى املدعــى عليــه‬\n‫لعــدم ثبــوت موجبــه‪ .‬ثاني ـاً‪ :‬تعزيــر املدعــى عليــه بســجنه ثمانيــة أعــوام‬\n‫مــن تاريــخ إيقافــه وجلــده ثمامنائــة جلــدة مفرقــة علــى دفعــات كل دفعــة‬\n‫خمســن جلــدة بــن كل فتــرة وأخــرى عشــرة أيــام ثالث ـاً‪ :‬ثبــت لدينــا‬\n‫إدانــة املدعــى عليــه بشــرب املســكر ويجلــد لقــاء ذلــك ثمانــن جلــدة‬\n‫دفعــة واحــدة حــد املســكر علمـ ًا بــأن احلــق اخلــاص مــازال قائمـ ًا وبعــرض‬\n‫ذلــك علــى املدعــي العــام قــرر عــدم القناعــة وجــرى تســليمه نســخة مــن‬\n‫احلكــم لالعتــراض عليــه خــال ثالثــن يوم ـ ًا وأمــا املدعــى عليــه فقــرر‬\n‫القناعــة وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n                                       ‫وصحبه وسلم حرر يف ‪1434/04/01‬هـ‬\n‫احلمــد هلل وحــده فلــدي أنــا ‪ .........‬القاضــي باحملكمــة العامــة بجــدة‬\n‫وكانــت املعاملــة قــد عــادت مــن محكمــة االســتئناف مبوجــب خطــاب‬\n‫فضيلــة رئيســها برقــم ‪ 34/381367‬يف ‪1434/6/27‬ه ــواملتضمن أنــه‬\n‫جــرى تدقيــق احلكــم مــن الدائــرة اجلزائيــة اخلماســية الثالثــة وصــدر‬\n‫بشــأنه القــرار ذو الرقــم ‪ 34176771‬وتاريــخ ‪1434/4/2‬ه ـ املــدون‬\n‫علــى ظهــر الصــك والــذي نصــه احلمــد هلل وحــده وبعــد‪ :‬فقــد اطلعنــا‬\n‫علــى هــذا الصــك رقــم ‪ 341767771‬وتاريــخ ‪1434/4/2‬ه ــالصادر مــن‬\n‫أصحــاب الفضيلــة القضــاة باحملكمــة العامــة بجــدة وأصدرنــا القــرار‬\n‫رقــم ‪ 34229460‬وتاريــخ ‪1434/6/4‬ه ـ املتضمــن املوافقــة علــى احلكــم‬\n‫أ‪.‬ه ـ وعليــه أمــرت بإحلــاق ذلــك علــى ضبطــه وســجله وبــاهلل التوفيــق‬\n‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه حــرر يف‬\n                                                            ‫‪1434/07/17‬ه ـ ‪.‬‬\n\n\n\n                                                                                     ‫‪250‬‬\n\f251\n\f252\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":239,"source_page_end":252,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"aac87b8e01cd0d7b182b59c954ad25da931b0899c73c848247402e76f72e98e8","normalized_text_hash":"81ce48e270a5d4d89a7cdf1eb80253d9c015fee84893fac41f8f1d8022714ff2","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p239-34176771"},{"id":"2dcfb181-1c31-5cc4-86dd-2be226324cc1","document_type":"judgment","category":"judicial","subcategory":"general","title":"خطف -إرغام فتاة على ركوب سيارة ومحاولة خطفها -االعتداء على فتاة بالضرب وسبها -االصطدام بسيارة -التعزير بالسجن واجللد واملنع من مباشرة أي عمل له ارتباط بالنساء األجنبيات","document_number":"34239665","case_number":"341974","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بينبع","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/13","year":"1434","subject":"خطف -إرغام فتاة على ركوب سيارة ومحاولة خطفها -االعتداء على فتاة بالضرب وسبها -االصطدام بسيارة -التعزير بالسجن واجللد واملنع من مباشرة أي عمل له ارتباط بالنساء األجنبيات","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34239665 :‬تاريخه ‪1434/6/13 :‬هـ‬\n                            ‫رقم الدعوى‪341974 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34290759‬تاريخه‪1434/8/8 :‬هـ‬\n\n\n      ‫خطــف ‪ -‬إرغــام فتــاة علــى ركــوب ســيارة ومحاولــة خطفهــا ‪ -‬االعتــداء‬\n      ‫علــى فتــاة بالضــرب وســبها ‪ -‬االصطــدام بســيارة ‪ -‬التعزيــر بالســجن‬\n      ‫واجللــد واملنــع مــن مباشــرة أي عمــل لــه ارتبــاط بالنســاء األجنبيــات‬\n                                                                             ‫عنــه ‪.‬‬\n\n\n\n\n       ‫ال) ‪.‬‬\n          ‫‪ -1‬قول اهلل تعالى‪( :‬وال تقربوا الزنا إنه كان فاحشة وساء سبي ً‬\n      ‫‪ -2‬قولــه صلــى اهلل عليــه وســلم‪( :‬إياكــم والدخــول علــى النســاء) رواه‬\n                                                               ‫البخــاري ومســلم‬\n      ‫‪ -3‬قولــه صلــى اهلل عليــه وســلم‪( :‬ال يخلــون رجــل بامــرأة إال كان‬\n                                         ‫الشــيطان ثالثهمــا) رواه الترمــذي‬\n\n\n\n\n      ‫توجيــه االتهــام للمدعــى عليــه بــإركاب فتــاة ال متــت لــه بصلــة شــرعية‬\n      ‫واالعتــداء عليهــا وســبها‪ ،‬واالصطــدام بســيارة متوقفــة بالطريــق‪،‬‬\n      ‫حيــث تقدمــت فتــاة بشــكوى علــى املدعــى عليــه مبحاولــة خطفهــا‪،‬‬\n      ‫طلــب املدعــي العــام إثبــات مــا أســند للمدعــى عليــه واحلكــم بعقوبــة‬\n      ‫تعزيريــة رادعــة لــه ولغيــره‪ ،‬أقــر املدعــى عليــه بركــوب الفتــاة ‪ ،‬وصــدم‬\n      ‫الســيارة املتوقفــة‪ ،‬وإنــكاره مــا ســوى ذلــك ‪ ،‬ودفــع بعــدم خطــف الفتــاة‬\n\n‫‪253‬‬\n\f‫وإمنــا ركبــت معــه لتوصيلهــا مــن املستشــفى ملنزلهــا ثــم طلبــت منــه مــا ًال‬\n‫فرفــض فادعــت بهــذه الدعــوى‪ ،‬أحضــر املدعــي العــام شــاهد ًا وهــو أحد‬\n‫أعضــاء الدوريــات األمنيــة‪ ،‬فشــهد بوجــود الفتــاة ملقــاة علــى األرض‬\n‫وذكــرت لــه مــا حصــل عليهــا مــن قبــل قائــد الســيارة ‪ ،‬جــرى الرجــوع‬\n‫إلــى محضــر االســتجواب ومحضــر الضبــط ومحضــر الشــهادة ومحضــر‬\n‫أقــوال املــرأة‪ ،‬صــدر احلكــم بثبــوت إدانــة املدعــى عليــه بــإركاب فتــاة‬\n‫ال متــت لــه بصلــة شــرعية ‪ ،‬وصــدم ســيارة متوقفــة ‪ ،‬وتوجيــه التهمــة‬\n‫لــه باالعتــداء علــى الفتــاة بالضــرب والــركل والتلفــظ عليهــا وتعزيــره‬\n‫بالســجن خمســة أشــهر وجلــده مائتــي جلــدة مفرقــة علــى دفعــات ومنعــه‬\n‫مــن مباشــرة أي عمــل لــه ارتبــاط بالنســاء األجنبيــات عنــه ‪ ،‬صــدق‬\n                                            ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد‪ :‬فلــدي أنــا ‪ .........‬القاضــي يف احملكمــة العامــة‬\n‫بينبــع ‪ ،‬وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بينبع‪/‬املســاعد برقــم ‪ ..........‬وتاريــخ ‪1434/01/03‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ ..........‬وتاريــخ ‪1433/12/29‬ه ـ ففــي يــوم االثنــن‬\n‫املوافــق ‪1434/01/26‬ه ـ افتتحــت اجللســة وفيهــا تقــدم املدعــي العــام‬\n‫ســعودي بالســجل املدنــي رقــم ‪ ..............‬بدعــوى محــررة يف املعاملــة جــاء‬\n‫فيهــا‪ :‬بصفتــي مدعيــا عامــا يف دائــرة االدعــاء العــام مبحافظــة ينبــع‬\n‫أدعــي علــى ‪ ......... ، .........‬عامــا ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم (‪ )..........‬عســكري بالدفــاع اجلــوي‪ ،‬قبــض عليــه بتاريــخ‬\n‫‪1433/7/16‬ه ـ وأفــرج عنــه بتاريــخ ‪1433/7/22‬هــ‪ ،‬حيــث أنــه بتاريــخ‬\n\n                                                                                       ‫‪254‬‬\n\f      ‫‪1433/7/16‬ه ـ تقدمــت الفتــاة‪ ........... /‬قيــام املتهــم أعــاه مبحاولــة‬\n      ‫خطفهــا وباالطــاع علــى محضــر القبــض تبــن أن املتهــم قــام بصــدم‬\n      ‫مجموعــة مــن الســيارات أثنــاء ســيره بالطريــق‪ ،‬وبســماع شــهادة‪......‬‬\n      ‫شــاهد الســيارة التــي يقودهــا املتهــم متيــل للجهــة اليســرى واليمنــى‬\n      ‫وصدمــت إحــدى الســيارات ‪ ،‬وبســماع شــهادة شــاهد الســيارة التــي‬\n      ‫يقودهــا املتهــم ويقــوم بــركل فتــاة مــن الســيارة وطرحهــا علــى األرض‬\n      ‫والتلفــظ عليهــا بقولــه‪( :‬اهلل يلعنــك) ‪ ،‬وباســتجواب املتهــم بعــد إحاطتــه‬\n      ‫بالتهمــة املنســوبة إليــه اعتــرف باصطحابــه للفتــاة املدعيــة ألجــل‬\n      ‫إيصالهــا وأنكــر مــا نســب إليــه مــن تهمــة ‪ ،‬وبالبحــث عــن ســوابقه تبــن‬\n      ‫عــدم وجــود ســوابق مســجلة عليــه ‪ ،‬وانتهــى التحقيــق إلــى توجيــه االتهــام‬\n      ‫ل ــه بــإركاب فتــاة ال متــت لــه بصلــة شــرعية واالعتــداء عليهــا والتلفــظ‬\n      ‫عليهــا وصــدم ســيارة كانــت متوقفــة بالطريــق ‪ ،‬وذلــك لألدلــة والقرائــن‬\n                                                                                 ‫التاليــة‪:‬‬\n      ‫‪ -1‬مــا جــاء يف أقــوال املتهــم علــى الصفحــة (‪ )1‬املرفــق علــى ملــف‬\n                                                   ‫التحقيــق املرفــق لفــة رقــم (‪)18‬‬\n                                  ‫‪ -2‬ما جاء يف محضر القبض املرفق لفة رقم (‪)8‬‬\n         ‫‪ -3‬ما جاء يف شهادة الشاهد على الصفحة رقم ‪ )4( :‬املرفق لفة (‪)2‬‬\n      ‫‪ -4‬مــا جــاء يف شــهادة الشــاهد علــى الصفحــة رقــم ‪ )8( :‬املرفــق لفــة‬\n      ‫(‪ ، )18‬وحيــث أن مــا أقــدم عليــه املتهــم فعــل محــرم ومعاقــب عليــه‬\n      ‫شــرع ًا ‪ -‬لــذا أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة‬\n      ‫رادعــة لــه ولغيــره ‪ .‬هكــذا ادعــى املدعــي العــام ‪ .‬وبعــرض الدعــوى علــى‬\n      ‫املدعــى عليــه أجــاب قائــا ‪ :‬مــا ذكــره املدعــي العــام يف دعــواه منــه‬\n      ‫مــا هــو صحيــح ومنــه مــا هــو غيــر صحيــح ‪ ،‬فالصحيــح هــو ركــوب‬\n\n\n‫‪255‬‬\n\f‫الفتــاة املذكــورة يف الدعــوى معــي وصدمــي لســيارة واحــد نــوع (‪).....‬‬\n‫ومــا ســوى ذلــك فغيــر صحيــح ‪ ،‬فلــم أختطــف الفتــاة وإمنــا ركبــت معــي‬\n‫لتوصيلهــا مــن مستشــفى ‪ .....‬إلــى منزلهــا ثــم طلبــت منــي مــاال فرفضــت‬\n‫إعطاءهــا ‪ ،‬فادعــت أنــي قــد قمــت بخطفهــا هكــذا أجــاب ‪ .‬وعليــه‬\n‫ولطلــب البينــة مــن املدعــي العــام رفعــت اجللســة ‪ .‬ويف جلســة أخــرى‬\n‫حضــر املدعــي العــام واملدعــى عليــه وبســؤال املدعــي العــام عــن البينــة؟‬\n‫أحضــر للشــهادة ‪ .........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫(‪ ).............‬والــذي يعمــل يف الدوريــات األمنيــة يف ‪ ، ....‬وبســؤاله عمــا‬\n‫لديــه مــن شــهادة ؟ قــال ‪ :‬أشــهد هلل تعالــى بأنــه أثنــاء تعقيــب الدوريــة‬\n‫بحــي ‪ ...‬علــى طريــق الشــاحنات الحظنــا وجــود مواطنــن يفيــدون أن‬\n‫صاحــب ‪ ....‬لوحــة رقــم (‪ ).......‬قــام بصــدم عــدة ســيارات ودخــل داخــل‬\n‫احلــي ومت البحــث عليــه مــن قبلنــا ووجدنــا فتــاة تســتنجد وهــي كاشــفة‬\n‫عــن وجههــا وتقــول أنهــا كانــت مــع صاحــب ‪ ...‬ال تعــرف اســمه لكــي‬\n‫يوصلهــا مشــوار وطلــب منهــا جوالهــا لكــي يتصــل لكونــه ليــس لديــه‬\n‫رصيــد وقــام بقفــل اجلــوال وعنــد محاولــة أخذهــا للجــوال قــام بســحب‬\n‫غطــاء وجههــا وعنــد تغييــر مســار الطريــق قامــت بالركــوب لألمــام‬\n‫ولــف دركســون الســيارة وصــدم الســائق بســيارات كانــت واقفــة حتــى‬\n‫تســتنجد باملواطنــن ثــم صــدم صبــة داخــل احلــي ووقفــت الســيارة وقــام‬\n‫بتنزيلهــا مــن الســيارة وقــام بضربهــا وســبها هــذا مــا قالتــه لنــا الفتــاة ‪،‬‬\n‫وقــد بحثنــا عــن صاحــب الســيارة ‪ ....‬ولــم جندهــا وســلمنا الفتــاة قســم‬\n‫شــرطة ‪ .....‬هــذا مــا شــهد بــه ‪ ،‬وبســؤال املدعــي العــام هــل لديــك مزيــد‬\n‫بينــة ؟ قــال ‪ :‬نعــم ‪ ،‬وأطلــب مهلــة إلحضارهــا فأجيــب لطلبــه ورفعــت‬\n‫اجللســة لذلــك ‪.‬ويف جلســة أخــرى حضــر املدعــي العــام واملدعــى عليــه‬\n\n\n                                                                                        ‫‪256‬‬\n\f      ‫وبســؤال املدعــي العــام عــن البينــة؟ قــال‪ :‬لــم حتضــر وأطلــب مهلــة أخــرى‬\n      ‫فأجيــب لطلبــه وأفهــم بأنهــا املهلــة األخيــرة لذلــك ورفعــت اجللســة لذلــك ‪.‬‬\n      ‫ويف جلســة أخــرى حضــر املدعــي العــام واملدعــى عليــه وجــرى عــرض مــا‬\n      ‫جــاء يف الشــهادة املدونــة يف اجللســة قبــل الســابقة عليــه فقــال ‪ :‬مــا جــاء‬\n      ‫يف الشــهادة بعضــه صحيــح والبعــض اآلخــر غيــر صحيــح ‪ ،‬فمــا جــاء‬\n      ‫يف الشــهادة مــن أنــي صدمــت عــدة ســيارات فغيــر صحيــح فلــم أصــدم‬\n      ‫ســوى ســيارة واحــدة نــوع (‪ ).....‬بعــد أن قامــت الفتــاة بلــف مقــود الســيارة‬\n      ‫‪ ،‬ومــا ذكــره عــن الفتــاة مــن أنــي ســحبت غطــاء وجههــا ثــم تنزيلهــا‬\n      ‫وضربهــا وســبها فغيــر صحيــح هكــذا قــال ‪ ،‬وعليــه إلفهــام املدعــي‬\n      ‫العــام بإحضــار مزكــن لشــاهده املذكــور رفعــت اجللســة ‪ .‬ويف جلســة‬\n      ‫أخــرى حضــر املدعــي العــام واملدعــى عليــه ‪ ،‬وبســؤال املدعــي العــام عــن‬\n      ‫تزكيــة الشــاهد ؟ قــال‪ :‬لــم أمتكــن مــن إحضــار مزكــن وأطلــب مهلــة‬\n      ‫لذلــك فأجيــب لطلبــه ‪ .‬ويف جلســة أخــرى حضــر املدعــي العــام واملدعــى‬\n      ‫عليــه وبســؤال املدعــي العــام عــن تزكيــة الشــاهد؟ قــال لــم أمتكــن‬\n      ‫مــن إحضــار مزكــن وأطلــب مهلــة أخــرى إلحضارهــم فأجيــب لطلبــه‬\n      ‫وأفهــم بأنهــا املهلــة األخيــرة لذلــك ‪ .‬ويف جلســة أخــرى حضــر املدعــي‬\n      ‫العــام واملدعــى عليــه ‪ ،‬وجــرى ســؤال املدعــي العــام عــن تزكيــة شــاهده‬\n      ‫ـزك لــه ‪ ،‬هكــذا قــال ‪ ،‬وعليــه فقــد‬  ‫؟ فقــال لــم نتمكــن مــن إحضــار مـ ٍ‬\n      ‫اعتبرتــه عاجــز ًا عــن ذلــك ‪ ،‬ثــم جــرى الرجــوع للمعاملــة واالطــاع علــى‬\n                                                     ‫أدلــة املدعــي العــام فتبــن أنهــا‪:‬‬\n      ‫‪ /1‬مــا جــاء يف أقــوال املتهــم علــى ص ‪ 1‬مــن لفــة ‪ 18‬وبالرجــوع إليهــا‬\n      ‫تبــن إقــرار املدعــى عليــه بــإركاب املــرأة معــه يف الســيارة لوحدهــا بــا‬\n      ‫ا وإنــكاره محاولــة خطفهــا ‪،‬‬       ‫محــرم الســاعة التاســعة والنصــف لي ـ ً‬\n      ‫ودعــواه أنهــا هددتــه إن لــم يعطهــا مــا ًال فســوف تقــوم بالصــراخ وتدعــي‬\n‫‪257‬‬\n\f                                                              ‫عليــه أنــه خطفهــا ‪.‬‬\n‫‪ /2‬مــا جــاء يف محضــر القبــض لفــه (‪ )8‬وفيــه أنــه عنــد قيــام الدوريــة‬\n‫بجولــة داخــل احلــي وجــد فتــاة تســتنجد وكانــت كاشــفة عــن وجههــا‬\n‫وعنــد ســؤالها أفــادت إنهــا كانــت مــع صاحــب ســيارة ‪ .........‬الــذي قــام‬\n‫بصــدم العربــات وكان يحــاول اختطافهــا وقــام بأخــذ جوالهــا وإقفالــه‪.‬‬\n‫‪ /3‬شــهادة الشــاهد املدونــة علــى ص ‪ 4‬لفــه ‪ 2‬وفيهــا بأنــه أثنــاء ذهابــه‬\n‫إلــى منزلــه شــاهد ســيارة مــن نــوع (‪ )...‬أبيــض قــام بالوقــوف خلــف‬\n‫طبلــون الكهربــاء وســمع أصــوات غيــر مفهومــة وبعــد ذلــك فتــح صاحــب‬\n‫الســيارة البــاب وقــام بــركل فتــاة مــن الســيارة وطرحهــا علــى األرض‬\n‫وقــال لهــا ‪( :‬اهلل يلعنــك) وهــرب أ‪ .‬ه ـ وبعــرض مــا جــاء يف الشــهادة‬\n‫أعــاه علــى املدعــى عليــه قــال‪ :‬مــا جــاء يف الشــهادة غيــر صحيــح‪،‬‬\n‫والصحيــح مــا ذكرتــه هكــذا قــال‪ .‬كمــا جــرى االطــاع علــى أقــوال‬\n‫الفتــاة املدونــة علــى ص ‪ 3‬لفــة ‪ 18‬وفيهــا‪( :‬قمــت باالتصــال عليــه يف‬\n‫ا فحضــر وقمــت بالركــوب معــه وطلــب‬            ‫حــدود الســاعة العاشــرة لي ـ ً‬\n‫منــي جوالــي وبعدهــا شــاهدته يقــوم مبحاولــة إقفــال اجلــوال وطلبــت‬\n‫منــه اســتعادته إال إنــه أخــذ يضحــك بصــوت مرتفــع ثــم قمــت باالتصــال‬\n‫علــى الدوريــات األمنيــة إال إنــه أخــذ جوالــي الثانــي ثــم قــام بإخــراج‬\n‫مســدس وقــال لــي ‪( :‬هــذا مســدس مــو لعبــة) ‪ ،‬حيــث قــام بإخراجــه مــن‬\n‫مــكان لــم أشــاهده ثــم قمــت بضــرب يــده برجلــي ثــم ركبــت باملقعــد‬\n‫األمامــي وقمــت بلــف الطــارة حيــث صدمــت ســيارة كانــت واقفــة ثــم‬\n‫قــام بضربــي وعضنــي بيــدي ثــم قــام بركلــي برجلــه وخرجــت خــارج‬\n‫الســيارة ثــم ذهــب بســيارته )اه ـ ‪ .‬وبعــرض مــا جــاء يف أقــوال املــرأة أعــاه‬\n‫علــى املدعــى عليــه قــال ‪ :‬مــا ذكرتــه مــن اعتدائــي عليهــا أو تهديدهــا‬\n\n\n                                                                                       ‫‪258‬‬\n\f      ‫فغيــر صحيــح هكــذا قــال ‪ ،‬فبنــاء علــى مــا تقــدم وبعــد االطــاع علــى‬\n      ‫دعــوى املدعــي العــام وإجابــة املدعــى عليــه‪ ،‬وبعــد االطــاع علــى املعاملــة‬\n      ‫ونظــر ًا إلقــرار املدعــى عليــه مبــا نســبه إليــه املدعــي العــام مــن إركاب‬\n      ‫فتــاة ال متــت لــه بصلــة شــرعية وصــدم ســيارة كانــت متوقفــة وإنــكاره‬\n      ‫االعتــداء والتلفــظ علــى الفتــاة ‪ ،‬وملــا جــاء يف شــهادة الشــاهد املدونــة يف‬\n      ‫جلســة ســابقة مــن العثــور علــى الفتــاة وهــي تســتنجد وكانــت كاشــفة‬\n      ‫عــن وجههــا ‪ ،‬وملــا جــاء يف شــهادة الشــاهد املدونــة أعــاه مــن مشــاهدته‬\n      ‫لســيارة املدعــى عليــه يف توقفهــا ثــم ســيرها مــرة أخــرى ثــم توقفهــا وقيــام‬\n      ‫املدعــى عليــه بفتــح بــاب الســيارة وركل الفتــاة ثــم طرحهــا علــى األرض‬\n      ‫وقولــه لهــا‪ ( :‬اهلل يلعنــك ) وملــا جــاء يف أقــوال الفتــاة املشــار إليهــا اعــاه ‪،‬‬\n      ‫وألنــه يبعــد علــى املــرأة أن جتــر علــى نفســها األذى يف ســمعتها وعرضهــا‬\n      ‫ا ؛لذلــك كلــه فقــد‬  ‫باتهــام مــن اعتــدى عليهــا إال يف حــال وقــوع ذلــك فعـ ً‬\n      ‫ثبــت لــدي إدانــة املدعــى عليــه بــإركاب فتــاة ال متــت لــه بصلــة شــرعي‬\n      ‫وصــدم ســيارة كانــت متوقفــة بالطريــق وتوجــه التهمــة لــه باالعتــداء‬\n         ‫علــى الفتــاة بالضــرب والــركل والتفلــظ عليهــا بقولــه‪(:‬اهلل يلعنــك )‬\n      ‫وألن مــا قــام بــه املدعــى عليــه فعــل محــرم وســلوك منكــر وفيــه تســاهل‬\n      ‫يف شــأن األعــراض التــي جــاءت الشــريعة اإلســامية بحفظهــا وألن يف‬\n      ‫فعلــه بــإركاب الفتــاة لوحدهــا دون محــرم ويف الليــل قــرب مــن اخلطــوات‬\n      ‫املوصلــة للفاحشــة وقــد قــال اهلل تعالــى‪ ( :‬وال تقربــوا الزنــا إنــه كان‬\n      ‫ال ) ولقوله صلى اهلل عليه وســلم‪ (:‬إياكم والدخول‬                ‫فاحشــة وســاء ســبي ً‬\n      ‫علــى النســاء ) رواه البخــاري ومســلم ولقولــه صلــى اهلل عليــه وســلم ‪« :‬‬\n      ‫ال يخلــون رجــلٌ بامــرأة إال كان الشــيطان ثالثهمــا » رواه الترمــذي ‪ .‬لــذا‬\n                           ‫فقــد قــررت تعزيــر املدعــى عليــه للحــق العــام مبــا يلــي ‪:‬‬\n\n\n‫‪259‬‬\n\f‫‪ /1‬ســجنه ملــدة خمســة أشــهر يحتســب منهــا مــا أمضــاه مــن توقيــف‬\n                                                         ‫بســبب هــذه القضيــة ‪.‬‬\n‫‪ /2‬جلــده مئتــن وخمســن جلــدة مفرقــة على دفعات كل دفعة خمســون‬\n                  ‫جلــدة وبــن كل دفعــة وأخــرى مــا ال يقــل عــن عشــرة أيام ‪.‬‬\n‫‪/3‬منعــه مــن مباشــرة أي عمــل لــه ارتبــاط بالنســاء األجنبيــات عنــه ‪.‬‬\n‫هــذا مــا ظهــر لــي وبــه حكمــت وبعــرض احلكــم علــى املدعــي العــام‬\n‫قــرر اعتراضــه بــدون الئحــة اعتراضيــة ‪ ،‬وبعرضــه علــى املدعــى عليــه‬\n‫قــرر اعتراضــه وطلــب تســليمه نســخة مــن احلكــم لتقــدمي اعتراضــه‬\n‫عليــه فأفهــم باملراجعــة يــوم الثالثــاء ‪1434/6/13‬ه ـ الســتالم نســخة‬\n‫احلكــم وجــرى إفهامــه بتعليمــات االســتئناف يف ضبطــه وبــاهلل التوفيــق‬\n      ‫‪ ،‬وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف ‪1434/6/11‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد‬\n‫فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة اخلامســة مبحكمــة‬\n‫االســتئناف يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بينبــع املســاعد برقــم‬\n‫‪ 332274610‬وتاريــخ ‪1434/7/19‬ه ـ املرفــق بهــا القــرار رقــم‬\n‫‪ 34239665‬وتاريخ‪1434/6/13‬ه ـ الصــادر مــن فضيلــة الشــيخ ‪.....‬‬\n‫القاضــي باحملكمــة العامــة بينبــع املتضمــن دعــوى املدعــي العــام ضــد‬\n‫‪ .....‬ســعودي اجلنســية املتهــم بــإركاب فتــاة ال متــت لــه بصلــه شــرعية‬\n‫والتلفــظ عليهــا‪ ،‬احملكــوم فيــه مبــا دون بباطنــه ‪ ،‬وبدراســة القــرار‬\n‫وصــورة ضبطــه والئحتــه االعتراضيــة قررنــا املوافقــة علــى احلكــم ‪،‬‬\n‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n                                                                                    ‫‪260‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":253,"source_page_end":260,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7b58e3642fcf09130448d46bb4c7f02af295143f78571ffe1db355e56c888132","normalized_text_hash":"678728fcbf3b395d8e75444153235dde3f4202bd9524e725491c91c6bcde734b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p253-34239665"},{"id":"175c2ad3-e2b1-5f76-8633-eac5ce1dcab5","document_type":"judgment","category":"judicial","subcategory":"general","title":"خطف -الشروع يف خطف فتاة -عدم ثبوت البينة -عدم ثبوت","document_number":"34206620","case_number":"34197926","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/05/06","year":"1434","subject":"خطف -الشروع يف خطف فتاة -عدم ثبوت البينة -عدم ثبوت","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34206620 :‬تاريخه‪1434/05/06 :‬هـ‬\n                         ‫رقم الدعوى‪34197926 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34246663‬تاريخه‪1434/6/20 :‬هـ‬\n\n\n       ‫خطــف ‪ -‬الشــروع يف خطــف فتــاة ‪ -‬عــدم ثبــوت البينــة ‪ -‬عــدم ثبــوت‬\n                                                                                 ‫إدانــة ‪.‬‬\n\n\n\n\n       ‫قــول النبــي صلــى اهلل عليــه وســلم ( لــو يعطــى النــاس بدعواهــم الدعــى‬\n                                                    ‫رجــال دمــاء قــوم وأموالهــم )‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــي العــام علــى املدعــى عليــه بقيامــه باالشــتراك يف محاولــة‬\n       ‫خطــف فتــاة بالقــوة ويطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة‬\n       ‫تعزيريــة رادعــة ‪ -‬حيــث إنــه مت القبــض علــى املدعــى عليــه إثــر ورود بــاغ‬\n       ‫عــن وجــود حالــة بحــي ‪ ...‬وبالوصــول للموقــع وجــدت (املجنــي عليهــا)‬\n       ‫وتدعــي بــأن املدعــى عليــه قــام باالشــتراك مــع شــخص آخــر مبحاولــة‬\n       ‫خطفهــا بالقــوة‪ ،‬أنكــر املدعــى عليــه مبــا جــاء يف الدعــوى ‪ -‬عــدم‬\n                                                           ‫وجــود بينــة للمدعــي العــام‪.‬‬\n       ‫فبنــاء علــى مــا تقــدم حكمــت احملكمــة بإخــاء ســبيل املدعــى عليهــم‬\n       ‫وصــرف النظــر عــن الدعــوى‪ ،‬قــرر املدعــي العــام االعتــراض وطلــب‬\n       ‫االســتئناف بالئحــة وقــرر املدعــى عليــه القناعــة‪ .‬صــدق احلكــم مــن‬\n                                                                 ‫محكمــة االســتئناف‪.‬‬\n‫‪261‬‬\n\f‫احلمد هلل وحده وبعد فلدي أنا ‪ ....‬القاضي يف احملكمة اجلزائية مبكة‬\n‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة مبكــة املكرمــة برقــم ‪ 34197926‬وتاريــخ ‪1434/04/29‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 341054864‬وتاريــخ ‪1434/04/29‬ه ـ ففــي‬\n‫يــوم األربعــاء املوافــق ‪1434/05/01‬ه ـ افتتحت اجللســة الســاعة ‪10 : 15‬‬\n‫وفيهــا حضــر املدعــي العــام ‪ ....‬مبوجــب خطــاب التكليــف مــن مرجعــه‬\n‫رقــم ‪ 337‬يف ‪1434/01/24‬ه ـ وادعــى علــى احلاضــر معــه باملجلــس‬\n‫ا بدعــواه حيــث أنــه‬  ‫الشــرعي ‪ ....‬مينــي اجلنســية باإلقامــة رقــم ‪ ....‬قائ ـ ً‬\n‫بتاريــخ ‪1434/05/21‬ه ـ مت القبــض علــى املدعــى عليــه أثــر ورود بــاغ‬\n           ‫عــن وجــود حالــة بحــي ‪ ......‬وبالوصــول للموقــع يف متــام الســاعة‬\n‫(‪ 05 : 58‬صباحــا) وجــدت (املجنــي عليهــا) وتدعــى (‪ )...‬تفيــد بأنهــا‬\n‫حضــرت إلــى احلــرم ألداء العمــرة حيــث قــام أخوهــا بإيصالهــا للحــرم‬\n‫وبعــد أن انتهــت مــن أداء العمــرة بعــد صــاة الفجــر مباشــرة ركبــت‬\n‫ســيارة وذلــك إليصالهــا مشــوار حلــي الكعكيــة لشــراء رأس مــن الغنــم‬\n‫مــن حلقــة الكعكيــة ويف أثنــاء الطريق طلب منها قائد الســيارة األجرة‬\n‫مبلــغ وقــدره (‪ )20‬ريــا ًال فقامــت بإعطائــه مبلــغ (‪ )100‬ريــال لكــي يأخذ‬\n‫قيمــة املشــوار ويــرد لهــا الباقــي فتوقــف قائــد الســيارة أمــام بقالــة تدعــى‬\n‫‪ .....‬ثــم خــرج هــو وصاحــب البقالــة املدعــى عليــه وتــرك البقالــة مفتوحــة‬\n‫ثــم قــام املدعــى عليــه بفتــح بــاب غرفــة تقــع بجــوار البقالــة وقــال (دخلهــا‬\n‫هنــا) بينمــا حضــر إليهــا صاحــب الســيارة وســحبها بالقــوة مــن جهــة‬\n‫كتفهــا األيســر ممــا أدى إلــى شــق عباءتهــا وذلــك لكــي يدخلهــا الغرفــة‬\n\n                                                                                         ‫‪262‬‬\n\f      ‫فرفضــت وصرخــت وعندهــا هــرب قائــد الســيارة ولــم يــرد لهــا باقــي‬\n      ‫املبلــغ فقامــت باالتصــال علــى الدوريــات األمنيــة وعنــد حضــور الدوريــة‬\n      ‫أرشــدت رجــال األمــن إلــى منــزل املدعــى عليــه وذكــرت بأنــه قــام بفتــح‬\n      ‫بــاب الغرفــة الواقعــة بجــوار البقالــة وكان ينتظــر عنــد البــاب حتــى‬\n      ‫يتمكــن قائــد الســيارة مــن إدخالهــا للغرفــة وأفــادت بأنهــا لــم تتعــرض‬\n      ‫ألي إصابــة ســوى أن مالبســها تعرضــت للتلــف وبســؤالها عــن قائــد‬\n      ‫الســيارة أفــادت بأنــه شــخص مــن اجلنســية اليمنيــة عمــره حوالــي (‪)30‬‬\n      ‫عامـ ًا طويــل القامــة نحيــف اجلســم لــه شــارب وذقــن خفيفــان كان يلبــس‬\n      ‫بنطــال جنــز أبيــض اللــون وقميــص أســود اللــون وأفــادت بــأن الســيارة‬\n      ‫صغيــرة احلجــم ال تعــرف نوعهــا أو رقــم لوحاتهــا بيضــاء اللــون مقاعدهــا‬\n      ‫رصاصيــة اللــون (فصلــت لــه أوراق مســتقلة) ومبعاينــة مالبــس املجنــي‬\n      ‫عليهــا اتضــح متــزق عباءتهــا مــن جانــب كتفهــا األيســر حيــث تبــن وجــود‬\n      ‫قطــع كبيــر جــد ًا وبعــرض املدعــى عليــه علــى الفتــاة تعرفــت عليــه وقــد‬\n      ‫انتهــى التحقيــق إلــى توجيــه االتهــام إليــه باالشــتراك يف محاولــة خطــف‬\n      ‫فتــاة بالقــوة وذلــك لألدلــة والقرائــن املوضحــة بالدعــوى وحيــث إن مــا‬\n      ‫قــام بــه املدعــى عليــه فعــل محــرم ومعاقــب عليــه شــرعا أطلــب إثبــات مــا‬\n      ‫أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة رادعــة علمـ ًا بــأن احلــق اخلــاص‬\n      ‫ال زال قائمـ ًا هــذه دعــواي وبســؤال املدعــى عليــه قــال مــا ذكــره املدعــي‬\n      ‫العــام غيــر صحيــح وال أعــرف املــرأة املذكــورة وال صاحــب الســيارة‬\n      ‫املزعومــة وال أعــرف عــن هــذه القضيــة ســوى أننــي ابتليــت بهــذه التهمــة‬\n      ‫الباطلــة جملــة وتفصيــا هــذه إجابتــي وقــال املدعــي العــام الصحيــح مــا‬\n      ‫ذكــرت وبطلــب البينــة قــال بينتــي مــا جــاء يف أوراق املعاملــة وبدراســة‬\n      ‫القضيــة وقــراءة املعاملــة ومحاضــر التحقيــق واألدلــة لــم أجــد فيهــا مــا‬\n\n\n‫‪263‬‬\n\f‫يديــن املدعــى عليــه ســوى شــكوى املجنــي عليهــا وتعرفهــا علــى املدعــى‬\n‫عليــه ومبواجهتــه أصــر علــى إنــكاره فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n‫واإلجابــة وإلــى إنــكار املدعــى عليــه لدعــوى املدعــي العــام وعــدم وجــود‬\n‫البينــة املوصلــة ســوى دعــوى املشــتكية ‪ ،‬ولقــول النبــي صلــى اهلل‬\n‫عليــه وســلم ‪ ( :‬لــو يعطــى النــاس بدعواهــم الدعــى رجــال دمــاء قــوم‬\n‫وأموالهــم ) لــذا فقــد حكمــت بعــدم ثبــوت دعــوى املدعــي العــام وأخليــت‬\n‫ســبيل املدعــى عليــه مــن هــذه الدعــوى وقنــع املدعــى عليــه وقــد عــارض‬\n‫املدعــي العــام وطلــب االســتئناف بالئحــة فأجيــب لطلبــه وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n‫‪1434/05/01‬ه ـ ثــم عــادت املعاملــة مــن محكمــة االســتئناف وبرفقهــا‬\n‫القــرار رقــم ‪ 34246663‬وتاريــخ ‪1434/06/20‬ه ـ املتضمــن املوافقــة‬\n‫والتصديــق علــى احلكــم قاضــي اســتئناف ‪ ....‬قاضــي اســتئناف ‪.....‬‬\n‫قاضــي اســتئناف ‪ ....‬لــذا جــرى إحلاقــه وإثباتــه وبــاهلل التوفيــق حــرر يف‬\n                                                              ‫‪1434/07/10‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                   ‫‪264‬‬\n\f265\n\f266\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":261,"source_page_end":266,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ec765bfebaf6af347c2233143af912401db0a332dc22cda4477d525ca13b02f8","normalized_text_hash":"90c3004390543f3282ca9facda9db531237f00b2f918112f905c92ddbd2a0021","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p261-34206620"},{"id":"c91ca4d6-c095-5d8c-9d9c-7f2e28903950","document_type":"judgment","category":"judicial","subcategory":"general","title":"سحر -حيازة طالسم سحرية -متائم بها شيء من القرآن -كون املدعى عليه كفيف وأجنبي ويغلب عليه اجلهل يف األمور العقدية -ظرف مخفف للعقوبة -تعزير بأخذ التعهد عليه.","document_number":"34229340","case_number":"3350512","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/06/04","year":"1434","subject":"سحر -حيازة طالسم سحرية -متائم بها شيء من القرآن -كون املدعى عليه كفيف وأجنبي ويغلب عليه اجلهل يف األمور العقدية -ظرف مخفف للعقوبة -تعزير بأخذ التعهد عليه.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34229340:‬تاريخه‪1434/06/04 :‬هـ‬\n           ‫رقم الدعوى‪ 3350512 :‬رقم قرار التصديق‬\n                ‫من محكمة االستئناف‪34266244:‬‬\n                           ‫تاريخه‪1434/07/11:‬هـ‬\n\n\n       ‫ســحر ‪ -‬حيــازة طالســم ســحرية ‪ -‬متائــم بهــا شــيء مــن القــرآن ‪ -‬كــون‬\n       ‫املدعــى عليــه كفيــف وأجنبــي ويغلــب عليــه اجلهــل يف األمــور العقديــة‬\n                         ‫‪ -‬ظــرف مخفــف للعقوبــة‪ -‬تعزيــر بأخــذ التعهــد عليــه‪.‬‬\n\n\n\n\n       ‫‪ -1‬قولــه صلــى اهلل عليــه وســلم (إن الرقــى والتمائــم والتولــة شــرك)‪.‬‬\n       ‫رواه أحمــد وأبــو داود واحلاكــم وصححــه ووافقــه الذهبــي واأللبانــي‪.‬‬\n       ‫‪ -2‬الراجــح مــن قــول أهــل العلــم أن التمائــم التــي ال تشــتمل علــى شــيء‬\n                    ‫مــن القــرآن وأســماء اهلل عــز وجــل وصفاتــه محرمــة مطلقـ ًا‬\n\n\n\n\n       ‫ادعــى املدعــي العــام علــى املدعــى عليــه بحيــازة عــدد مــن األوراق حتتــوي‬\n       ‫علــى طالســم ســحرية ومتيمتــن بهمــا طالســم ســحرية‪ ،‬وذلــك بعــد مــا‬\n       ‫مت القبــض عليــه مــن قبــل اجلهــات املختصــة ومعــه أوراق حتتــوي علــى‬\n       ‫أعمــال كفريــة وشــركية محرمــة كتبــت بخــط اليــد‪ ،‬ومتيمتــن بهمــا‬\n       ‫طالســم ســحرية ‪،‬وطلــب املدعــي العــام احلكــم عليــه بعقوبــة تعزيريــة‪،‬‬\n       ‫‪،‬وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه بواســطة املترجــم‬\n       ‫أنكرهــا ودفــع بــأن حيازتــه ملــا ذكــر يف دعــواه ألجــل أن يكــون هنــاك‬\n       ‫محبــة بينــه وبــن زميلــه يف العمــل وال يــدري مــا يف هــذه األوراق وال‬\n\n‫‪267‬‬\n\f‫يعلــم إن كان القصــد منهــا ســحر وشــعوذة ‪،‬وباالطــاع علــى األوراق‬\n‫وجــد أنهــا حتتــوي علــى آيــات قرآنيــة وليســت طالســم‪،‬ولكون املدعــى‬\n‫عامــي وأجنبــي ويغلــب عليــه اجلهــل يف األمــور العقديــة لــذا فقــد مت‬\n                                                                        ‫عليــه ّ‬\n‫احلكــم بأخــذ التعهــد الشــديد عليــه بعــدم تكــرار مــا بــدر منــه وإفهامــه‬\n‫بــأن يعلــق أمــره كلــه هلل‪ ،‬ويفــوض أمــره إليــه‪ ،‬فهــو النافــع الضــار وهــو‬\n‫الــذي يجلــب الــرزق واخليــر وليــس التمائــم وتعليقهــا فهــي ال تنفعــه وال‬\n‫تضــره‪ ،‬وال تغنــي عنــه شــيئاً‪ ،‬فمــن تــوكل علــى اهلل كفــاه‪ ،‬وقــرب إليــه‬\n‫كل بعيــد‪ -‬ويســر لــه كل عســير ‪،‬وبعــرض احلكــم علــى املدعــى عليــه‬\n‫قــرر القناعــة بــه كمــا قــرر املدعــي العــام املعارضــة عليــه واكتفــى مبــا‬\n‫جــاء يف الئحــة الدعــوى عــن تقــدمي الئحــة اعتراضيــة‪ ،‬وبعــد رفــع احلكــم‬\n                                  ‫حملكمــة االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد ويف يــوم األحــد املوافــق ‪1433 /10 /29‬ه ـ وبنــاء‬\n‫علــى املعاملــه املقيــده بهــذه احملكمــة برقــم ‪ 33130963‬يف ‪/19‬‬\n‫‪1433 /01‬ه ـ واحملالــة لنــا مــن رئيــس احملكمــة برقــم ‪ 3350512‬يف‬\n‫‪1433 /01 /19‬ه ـ افتتحــت اجللســه الســاعة احلاديــة عشــر صباحــا يف‬\n‫هــذه القضيــه رقــم ( ‪ ) 3338800003‬وفيهــا حضــر املدعــي العــام ‪/‬‬\n‫‪...‬وادعــى علــى املدعــو‪... /‬البالــغ مــن العمــر ( ‪ ) 28‬عامــا مســلم الديانــه‬\n‫باكســتاني اجلنســية مبوجــب رخصــة االقامــة رقــم ( ‪ )...‬ســائق شــاحنة‬\n‫غيــر محصــن قبــض عليــه بتاريــخ ‪1433 /1 /5‬ه ـ وافــرج عنــه بالكفالــة‬\n‫بتاريخ ‪1433 /1 /5‬هـ يســكن محافظة االحســاء ‪ /‬الهفوف انه بتاريخ‬\n‫‪1433 /1 /5‬ه ـ قبــض عليــه مــن قبــل هيئــة االمــر باملعــروف والنهــي‬\n\n                                                                                     ‫‪268‬‬\n\f      ‫عــن املنكــر املتضمــن انــه باالطــاع علــى محتــوى الظــرف البريــدي‬\n      ‫الــوارد مــن باكســتان املرســل الــى املدعــى عليــه تبــن أنــه عبــارة عــن‬\n      ‫مجموعــة أوراق وذاكــرة جــوال وبالكشــف علــى األوراق تبــن أنهــا‬\n      ‫حتتــوي علــى أعمــال كفريــة وشــركية محرمــة وحتتــوي علــى عــدة‬\n      ‫طالســم ســحري كتبــت بخــط اليــد مبــاء زعفــران مخلــوط بنجاســات‬\n      ‫بهــا رائحــة كريهــة جــدا ‪ ،‬ومتيمتــن بهمــا طالســم ســحرية كإحــراز‬\n      ‫وحجــب تخــص املدعــى عليــه ‪ ،‬وأمــا ذاكــرة اجلــوال حتتــوي علــى اغانــي‬\n      ‫بلغتهــم وبســماع اقــوال املدعــى عليــه أقــر بحيــازة األوراق املضبوطــة معــه‬\n      ‫وأن القصــد منهــا الشــفاء كونــه يعانــي مــن بعــض اآلالم ‪ .‬وقــد أســفر‬\n      ‫التحقيــق عــن توجيــه االتهــام لــه بحيــازة عــدد مــن االوراق حتتــوي علــى‬\n      ‫طالســم ســحرية ومتيمتــن بهمــا طالســم ســحرية وذلــك لألدلــة والقرائــن‬\n      ‫التاليــة ‪ -1 :‬مــا جــاء يف اقــوال املدعــى عليــه املدونــة رقــم ( ‪) 11 -10‬‬\n      ‫مــن ملــف إجــراءات االســتدالل املرفــق علــى اللفــة رقــم ( ‪ -2 ) 1‬محضــر‬\n      ‫املعاينــة املعــد مــن قبــل هيئــة االمــر باملعــروف والنهــي عــن املنكــر املرفــق‬\n      ‫علــى اللفــة رقــم ( ‪ ) 8‬وبالبحــث عمــا إذا كان لــه ســوابق لــم يعثــر لــه‬\n      ‫علــى ســوابق علــى املســتوى احمللــي وحيــث ان مــا اقــدم عليــه املذكــور‬\n      ‫وهــو بكامــل اهليتــه املعتبــرة شــرعا فعــل محــرم ومعاقــب عليــه شــرعا‬\n      ‫اطلــب اثبــات مــا اســند اليــه واحلكــم عليــه بعقوبــة تعزيرية تزجــره وتردع‬\n      ‫غيــره هــذه دعــواى وبعــرض ذلــك علــى املدعــى عليــه عــن طريــق املترجــم‬\n      ‫املعــروف لدينــا املدعــو ‪... /‬هنــدي اجلنســية مبوجــب اإلقامــة رقــم[ ‪]...‬‬\n      ‫قــال مــا ذكــره املدعــي العــام يف دعــواه مــن حيازتــي اوراق كفريــة‬\n      ‫وشــركية محرمــة وحتتــوي علــى طالســم ســحرية كتبــت بخــط اليــد‬\n      ‫مبــاء زعفــران ومتيمتــن بهــا طالســم ســحرية فغيــر صحيــح والصحيــح‬\n\n\n‫‪269‬‬\n\f‫حيــث انــي كنــت اعمــل يف باكســتان فأخبرنــي زميلــي اســمه ‪...‬وكان‬\n‫يعمــل يف الســعودية كمنــدوب يف شــركة ‪...‬قــال لــي حينمــا تصــل الــى‬\n‫الســعودية ســتعطى راتبــا وقــدره الفــان ومئتــا ريــال فلمــا ذهبــت الــى‬\n‫الســعودية قــام باعطائــى راتبــا فجــن جنونــي فاتصلــت علــى اخــي يف‬\n‫باكســتان فاخبرتــه مبــا حــدث لــي ثــم قــام اخــي بارســال هــذه الطالســم‬\n‫لــي حتــى يكــون هنــاك محبــة بينــي وبــن زميلــي ‪...‬وانــا ال ادري مــا هــو‬\n‫يف هــذه االوراق وال اعلــم ان كان القصــد منهــا ســحر وشــعوذه ام ال‬\n‫هكــذا اجــاب وبتصفــح كامــل اوراق املعاملــة لإلطــاع علــى الطالســم‬\n‫املذكــورة لــم اجــد فيهــا مــا يفيــد عمــا ذكــر يف باطــن تلــك االوراق‬\n‫وعليــه فقــد قــررت رفــع اجللســة إلحضــار تلــك التمائــم لالطــاع عليهــا‬\n‫وحضــور البينــة ويف جلســة أخــرى وبنــاء علــى تعميــدي مــن فضيلــة‬\n‫الشــيخ‪ /‬د‪... .‬رئيــس احملكمــة اجلزائيــة باألحســاء املكلــف مبوجــب‬\n‫خطابــه رقــم (‪ )34/1238435‬يف ‪1434/5/21‬ه ـ لنظــر القضايــا مــا‬\n‫عــدا الســجناء وفيهــا حضــر املدعــي العــام وحضــر حلضــوره املدعــى‬\n‫عليــه كمــا حضــر حلضورهمــا املترجــم وكان قــد جــرت الكتابــة‬\n‫منــا ملركــز شــرطة الرقيقــة مبوجــب خطابنــا رقــم (‪ )3411397‬يف‬\n‫‪1434/1/3‬ه ـ إلحضــار الطالســم وقــد ألفــى اجلــواب مبوجــب خطابهــم‬\n‫رقــم (‪7090/9/21‬س) وبرفقــه ظــرف وبفتحــه وفحــص مــا بداخلــه‬\n‫وجــد خرقــة بداخلهــا خيــط مطاطــي مخــاط عليــه قطعــة صغيــرة علــى‬\n‫شــكل مربــع ومت فحــص مــا بداخلــه وجــد بــه ورقتــان وبتصفحهمــا‬\n‫وقراءتهمــا اتضــح أنهــا آيــات قرآنيــة وليســت طالســم ســحرية وحلاجتــي‬\n‫لدراســة القضيــة لــذا فقــد قــررت رفــع اجللســة ويف جلســة أخــرى حضــر‬\n‫املدعــي العــام وحضــر حلضــوره املدعــى عليــه كمــا حضــر حلضورهمــا‬\n\n\n                                                                                   ‫‪270‬‬\n\f      ‫املترجــم وبدراســة وتأمــل أوراق املعاملــة وضبــط القضيــة فبنــاء علــى مــا‬\n      ‫تقــدم مــن الدعــوى واإلجابــة وحيــث إن احملــوز مــع املدعــى عليــه ليســت‬\n      ‫طالســم ومتائــم ســحرية وإمنــا هــي متيمــة فيهــا ورقتــان مكتــوب فيهمــا‬\n      ‫آيــات قرآنيــة وحيــث إن الراجــح مــن أقــوال أهــل العلــم أن التمائــم التــي‬\n      ‫تشــتمل علــى شــيء مــن القــرآن وأســماء اهلل عــز وجــل وصفاتــه محرمــة‬\n      ‫مطلقــا؛ لعمــوم نهــي النبــي صلــى اهلل عليــه وســلم ‪(( :-‬إن الرقى والتمائم‬\n      ‫والتولــة شــرك))‪ .‬رواه أحمــد وأبــو داود واحلاكــم وصححــه ووافقــه‬\n      ‫الذهبــي واأللبانــي‪ .‬وســد ًا للذريعــة؛ فإنــه يفضــي إلــى تعليــق مــا ليــس‬\n      ‫مباح ـ ًا مــن التمائــم الشــركية والطالســم الســحرية؛ وحتــى ال ميتهــن‬\n      ‫شــيئا مــن القــرآن بحملــه يف مــكان قضــاء احلاجــة والقــاذورات‪ .‬لذلــك‬\n      ‫كلــه فقــد قــررت مــا يلــي‪ :‬أوال‪ :‬لــم يثبــت لــدي حيــازة املدعــى عليــه‬\n      ‫لطالســم ســحرية ومتيمتــن بهــا طالســم ســحرية وصرفــت النظــر مــن‬\n      ‫إثبــات ذلــك ثانيــا‪ :‬ثبــت لــدي حيــازة املدعــى عليــه لتميمــة فيهــا ورقتــان‬\n      ‫مكتوبــا فيهــا آيــات قرآنيــة ونظــرا لكــون املدعــى عليــه عامــي وأجنبــي‬\n      ‫ويغلــب عليــه اجلهــل يف األمــور العقديــة لــذا فقــد قــررت أخــذ التعهــد‬\n      ‫الشــديد عليــه بعــدم تكــرار مــا بــدر منــه وأفهمتــه بــأن يعلــق أمــره كلــه‬\n      ‫هلل؛ ويفــوض أمــره إليــه‪ ،‬فهــو النافــع الضــار وهــو الــذي يجلــب الــرزق‬\n      ‫واخليــر وليــس التمائــم وتعليقهــا فهــي ال تنفعــه وال تضــره‪ ،‬وال تغنــي عنــه‬\n      ‫شــيئاً‪ ،‬فمــن تــوكل علــى اهلل كفــاه‪ ،‬وقــرب إليــه كل بعيــد‪ ،‬ويســر‬\n      ‫لــه كل عســير‪ .‬ففهــم ذلــك ومبــا ســبق كلــه حكمــت وبعرضــه علــى‬\n      ‫املدعــى عليــه بواســطة املترجــم قــرر القناعــة بــه كمــا قــرر املدعــي العام‬\n      ‫املعارضــة عليــه واكتفــى مبــا جــاء يف الئحــة الدعــوى عــن تقــدمي الئحــة‬\n      ‫اعتراضيــة وبذلــك تكــون القضيــة منتهيــة وقــررت بعــث كامــل أوراق‬\n\n\n‫‪271‬‬\n\f‫املعاملــة حملكمــة االســتئناف بالشــرقية لتدقيــق احلكــم حســب املتبــع‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n‫تســليما كثيــرا احلمــد هلل وحــده وبعــد ‪ .........‬املســجل برقــم ‪34229340‬‬\n‫وتاريــخ ‪1434/6/4‬ه ـ اخلــاص بدعــوى املدعــى العــام ضــد‪ ...‬اجلنســية‬\n‫يف قضيــة ســحر وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n‫املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                     ‫وصحبــه وســلم حــرر يف ‪1434/7/8‬ه ـ‬\n\n\n\n\n                                                                                  ‫‪272‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":267,"source_page_end":272,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d81337d0114a98a280ce6fe402a42c298da3b6a67c510224acbf7baed2c9257e","normalized_text_hash":"e1c3c0aa71f26a50fe1c700063ba44337e96b9f63984a8b334225783422fe94b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p267-34229340"},{"id":"15609758-d658-517c-871c-cc7114cf8a52","document_type":"judgment","category":"judicial","subcategory":"general","title":"سحر -الوساطة يف أعمال السحر عن طريق النقل -إنكار -عدم وجود بينة -عدم إدانة -صرف نظر.","document_number":"3430618","case_number":"3417710","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/05","year":"1434","subject":"سحر -الوساطة يف أعمال السحر عن طريق النقل -إنكار -عدم وجود بينة -عدم إدانة -صرف نظر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 3430618:‬تاريخه‪1434/02/05 :‬هـ‬\n           ‫رقم الدعوى‪ 3417710:‬رقم قرار التصديق‬\n               ‫من محكمة االستئناف‪34192651:‬‬\n                           ‫تاريخه‪1434/04/20:‬هـ‬\n\n\n      ‫ســحر‪ -‬الوســاطة يف أعمــال الســحر عــن طريــق النقــل ‪ -‬إنــكار ‪ -‬عــدم‬\n                                       ‫وجــود بينــة ‪ -‬عــدم إدانــة ‪ -‬صــرف نظــر‪.‬‬\n\n\n\n\n                    ‫‪ .1‬األصل براءة ذمة املتهم حتى يدل الدليل على خالفه‪.‬‬\n                     ‫‪ .2‬كل دليل تطرق إليه االحتمال سقط به االستدالل‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام علــى املدعــى عليــه بالتوســط يف أعمــال الســحر‬\n      ‫عــن طريــق النقــل ألكل أمــوال النــاس بالباطــل ‪،‬وطلــب املدعــي العــام‬\n      ‫احلكــم عليــه بعقوبــة تعزيريــة ‪،‬وبعــرض دعــوى املدعــي العــام علــى‬\n      ‫املدعــى عليــه أنكرهــا جملــة وتفصيــا ودفــع أنــه ســائق وطبيعــة عملــه‬\n      ‫التوصيــل ‪،‬ونظــر ًا إلنــكار املدعــى عليــه لدعــوى املدعــي العــام ‪،‬وألن‬\n      ‫األصــل بــراءة ذمــة املتهــم حتــى يــدل الدليــل علــى خالفــه‪ ،‬وبنــاء علــى مــا‬\n      ‫تقــدم حكمــت احملكمــة بصــرف النظــر عــن طلــب املدعــي العــام إيقــاع‬\n      ‫العقوبــة التعزيريــة علــى املدعــى عليــه ‪،‬وبعــرض احلكــم علــى الطرفــن‬\n      ‫قــرر املدعــى عليــه قناعتــه باحلكــم وقــرر املدعــي العــام االعتــراض‬\n      ‫علــى احلكــم بــدون الئحــة اعتراضيــة ‪،‬وبعــد رفــع احلكــم حملكمــة‬\n                                                   ‫االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n‫‪273‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‬\n‫فلــدي أنــا القاضــي باحملكمــة اجلزئيــة بالدمــام ففــي يــوم األربعــاء‬\n‫املوافق‪1434/1/28‬ه ـ افتتحــت اجللســة الســاعة احلاديــة عشــر صباح ـ ًا‬\n‫بنــاء علــى املعاملــة احملالــة إلينــا مــن فضيلــة رئيــس احملكمــة اجلزئيــة‬\n‫بالدمــام برقــم ‪ 3417710‬وتاريخ‪1434/1/7‬ه ـ واملقيــدة بــوارد مكتبنا‬\n‫برقــم‪ 3483224‬وتاريخ‪1434/1/11‬ه ـ واملتعلقــة بدعــوى املدعــي العــام‬\n                                                                         ‫ضــد ‪.../‬‬\n‫وفيهــا حضــر املدعــي العــام ‪ .../‬وادعــى علــى احلاضــر معــه ‪... /‬اجلنســية‬\n‫مبوجــب الرقــم الشــخصي ‪...‬قائــا يف دعــواه إنــه باالطــاع علــى محضــر‬\n‫القبــض املعــد مــن قبــل هيئــة األمــر باملعــروف و النهــي عــن املنكــر تبــن‬\n‫انــه وردت لهــم شــكوى مــن أحــد املواطنــن ضــد أحــد الســحرة يف‬\n‫مملكــة البحريــن يدعــى‪ .......... /‬و أن زوجتــه تضــررت منــه و أن لــه‬\n‫أعــوان و وســطاء يقومــون بإيصــال األعمــال الســحرية إلــى اململكــة‬\n‫العربيــة الســعودية مقابــل مبالــغ ماليــة و قــام املدعــي بتزويــد الهيئــة برقــم‬\n‫الســاحر البحرينــي فتــم تكليــف أحــد املصــادر ( امــرأة ) باالتصــال‬\n‫عليــه و طلبــت منــه أن يعمــل لزوجهــا عطفــا و تســخير ًا لهــا بحيــث ال‬\n‫يــرى يف الوجــود إال هــي و طلبــت أيض ـ ًا عالج ـ ًا ألختهــا لكونهــا تعانــي‬\n‫مــن االنطــواء و العزلــة و طلــب مــن املصــدر اســمها و اســم أمهــا و اســم‬\n‫الــزوج و اســم أمــه و اســم أختهــا و اســم أمهــا و طلــب مبلــغ خمســة آالف‬\n‫ريــال قيمــة العــاج و ثالثــة آالف أتعــاب الوســيط الــذي ســيأتي بــه للدمام‬\n‫و قــال للمصــدر ســيتصل عليــك شــخص لتحديــد االســتالم و التســليم‬\n\n                                                                                         ‫‪274‬‬\n\f      ‫‪ ،‬ثــم ورد اتصــال علــى املصــدر مــن قبــل املدعــى عليــه و مت حتديــد‬\n      ‫اليــوم و املــكان يف مجمــع ‪ ...‬بالدمــام ‪ ،‬و نظــر ًا لضخامــة املبلــغ و خوفـ ًا‬\n      ‫عليــه مــن الضيــاع مت ترقيــم مبلــغ ألــف ريــال و تزويــد املصــدر بــه و يف‬\n      ‫الوقــت احملــدد متــت مشــاهدة املصــدر و هــو يتقابــل مــع املدعــى عليــه‬\n      ‫فقــام بإعطــاء املصــدر ظــرف بــه حجابــن و قــارورة مــاء صحــة غيــر‬\n      ‫مختومــة و قــام املصــدر بتســليمه املبلــغ فتــم القبــض عليــه و علــى مرافــق‬\n      ‫لــه يدعــى ‪(...‬صــدر بحقــه أمــر حفــظ دعــوى ) و بفتــح احلاجبــن لــم‬\n      ‫يتضــح فيهمــا شــئ مــن أعمــال الســحر فقــد كتــب يف األول ( صــار لــم‬\n      ‫يكــن الــى صفيــه ) و الثانــي ( إلــى مــن هــذا مــن هنــا هــو ( و باســتجواب‬\n      ‫املدعــى عليــه أفــاد أنــه يعمــل ســائق ســطحه لنقــل الســيارات و قــدم إلــى‬\n      ‫الســعودية إليصــال ظــرف حيــث اتصــل عليــه شــخص ال يعرفــه و طلــب‬\n      ‫منــه إيصــال أوراق خلالتــه يف الســعودية فوافــق كونــه يحضــر للســعودية‬\n      ‫كثيــر ًا و تقابــل مــع شــخص يف مجمــع البحريــن و أعطــاه ظــرف و معــه‬\n      ‫وقــارورة فســأله عــن الــذي بداخــل الظــرف فقــال أوراق و فتحــه لــه ثــم‬\n      ‫أخــذه و قــال لــه الشــخص إذا عــدت أعطيتــك املبلــغ حيــث اتفقــا علــى‬\n      ‫مبلــغ ‪ 50‬دينــار و أخبــره الشــخص بــأن خالتــه ســوف تســتلم الظــرف ‪،‬‬\n      ‫و عنــد وصولــه للســعودية اتصــل علــى املــرأة و بعــد مقابلتــه لهــا ســلمها‬\n      ‫الظــرف و القــارورة و أعطتــه ظــرف ثــم تفاجــأ بالقبــض عليــه كمــا أفــاد‬\n      ‫بــأن مرافقــه صديــق لــه و كثيــر مــا يكــون معــه و ليــس لــه أي عالقــة‬\n      ‫بــاألوراق و قــد انتهــى التحقيــق إلــى اتهــام املدعــى عليــه بالتوســط يف‬\n                                  ‫أعمــال الســحر ألكل أمــوال النــاس بالباطــل ‪.‬‬\n                                                        ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n      ‫‪ -1‬اعترافــه بأنــه اتصــل عليــه شــخص ال يعرفــه و طلــب منــه إيصــال‬\n\n\n‫‪275‬‬\n\f‫أوراق إلــى الســعودية فوافــق و تقابــل مــع الشــخص و أعطــاه ظــرف و‬\n‫معــه قــارورة و اتفقــا علــى مبلــغ ‪ 50‬دينــار مقابــل إيصالهــا املرفــق علــى‬\n                                                             ‫أللفــه رقــم (‪.)15-11‬‬\n                         ‫‪ -2‬محضر القبض املرفق على اللفه رقم ( ‪.) 5 - 4‬‬\n    ‫‪ -3‬ضعف دفعــه ال سيما ما يتعلق بـمعرفته مبن أعطاه املضبوطات ‪.‬‬\n                        ‫‪ -4‬استالمه للمبلغ املرقم قرينة على صحة االتهام ‪.‬‬\n‫و حيــث إن مــا أقــدم عليــه املدعــى عليــه و هــو بكامــل أهليتــه املعتبــرة‬\n                      ‫شــرع ًا فعــل محــرم و معاقــب عليــه شــرع ًا أطلــب إثبــات‬\n‫إدانتــه مبــا أســند إليــه و احلكــم عليــه بعقوبــة تعزيريــة تزجــره و تــردع‬\n‫غيــره هــذه دعــواي وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه‬\n‫أجــاب بقولــه مــا ذكــره املدعــي العــام مــن اتهامــي بالتوســط يف أعمــال‬\n‫الســحر ألكل أمــوال النــاس بالباطــل فغيــر صحيــح هكــذا أجــاب و‬\n‫ا بأنــي اعمــل ســائق ســطحه وطبيعــة عملــي هــي التوصيــل‬          ‫أضــاف قائـ ً‬\n‫ورقــم جوالــي معلــق للجميــع وذلــك بكتابتــه علــى الســطحة هكــذا‬\n‫ا ال توجــد علــي‬  ‫أضــاف وبســؤال املدعــى عليــه عــن الســوابق أجــاب قائـ ً‬\n‫أي ســابقة كمــا جــرى اطالعــي علــى أوراق املعاملــة كمــا جــرى‬\n‫اطالعــي علــى الئحــة دعــوى املدعــي العــام املتضمنــة عــدم وجــود ســوابق‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ونظــر ًا‬ ‫علــى املدعــى عليــه فبنـ ً‬\n                           ‫ملــا قــرره الطرفــان ومــا مت رصــده وضبطــه أعــاه‬\n                                                    ‫ونظر ًا إلنكار املدعى عليه‬\n‫لدعــوى املدعــي ونظــرا إلــى أن األصــل بــراءة ذمــة املتهــم حتــى يــدل‬\n‫الدليــل علــى خالفــه ونظــرا إلــى أن مــا قــام بــه املدعــى عليــه يتطــرق‬\n‫إليهــا احتمــال أنــه خــدع بذلــك وكل دليــل تطــرق إليــه االحتمــال ســقط‬\n\n\n                                                                                        ‫‪276‬‬\n\f      ‫بــه االســتدالل ونظــرا إلــى أن خلــو ســجل املدعــى عليــه مــن الســوابق‬\n                                                    ‫قرينــة تعضــد أصــل بــراءة الذمــة ‪.‬‬\n      ‫لــذا ولــكل مــا ســبق ‪:‬لــم يثبــت لــدي إدانــة املدعــى عليــه مبــا نســب‬\n      ‫إليــه يف دعــوى املدعــي العــام وبذلــك حكمــت وصرفــت النظــر عــن‬\n      ‫طلــب املدعــي العــام إيقــاع العقوبــة التعزيريــة علــى املدعــى عليــه وبذلــك‬\n      ‫حكمــت وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه قناعتــه‬\n      ‫باحلكــم وقــرر املدعــي العــام االعتــراض علــى احلكــم بــدون الئحــة‬\n      ‫اعتراضيــة ورفعــه حملكمــة االســتئناف مكتفيــا مبــا يف أوراق املعاملــة‬\n      ‫وعليــه فقــد قــررت رفــع املعاملــة كاملــة حملكمــة االســتئناف لتدقيــق‬\n      ‫احلكــم وختمــت يف احلاديــة عشــر والنصــف صباح ـ ًا وعلــى ذلــك جــرى‬\n      ‫التوقيــع وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n                                    ‫وصحبــه وســلم ‪ .‬حــرر يف ‪14 34 /1 /28‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n      ‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبدينــة الدمــام برقــم ‪3483224‬‬\n      ‫وتاريــخ ‪1434/2/30‬ه ـ املقيــدة لــدى احملكمة برقم ‪/34/521850‬ج‪1‬‬\n      ‫وتاريــخ ‪1434/3/1‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n      ‫باحملكمــة الشــيخ ‪...‬املســجل برقــم ‪ 3430618‬وتاريــخ ‪1434/2/5‬ه ـ‬\n      ‫اخلــاص بدعوى‪/‬املدعــي العــام ضد‪.../‬اجلنســية يف قضيــة ســحر وقــد‬\n      ‫تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة‬\n      ‫القراروصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة ععلــى احلكــم‬\n      ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                                  ‫حرريف‪1434/4/20‬ه ـ‬\n\n\n‫‪277‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":273,"source_page_end":277,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0ff08efb6255387b0a1ce32b59b892646377ab0c5a337a84ea53672dfe3aa45e","normalized_text_hash":"d851d8bdaea964a6011dde57e24dce8aff929f8a01edb3d1b0be55296ac1bc07","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p273-3430618"}]$archive_payload$::jsonb) AS x LIMIT 25
